/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231002-4","meetingId":"r05-c-settlement","date":"2023年10月2日","dateIso":"2023-10-02","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時５８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"せお副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"せりざわ委員","kind":"確認","question":"私からは、１５０ページの歩行喫煙防止過料、関連して１１７ページの歩行喫煙防止推進経費から、喫煙の防止についてお伺いします。歩行喫煙防止の認識を確認したいのですが、武蔵小山の５エリアを、説明を求めました。","respondent":"河合生活安全担当課長","answer":"縛りになっておりますので、９６件の過料につきましては全て、地域美化推進地区の過料となっています。５エリアというのは、また地域の環境、そして路上喫煙の状況等を踏まえて指定されているものです。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"推移がどうなっているのかを把握できているのかをお聞かせいただきたいのと、あと、１件１,０００円ですから恐らく９６件だと思いますが。それぞれの状況というのは違うのだと思いますが、他区との比較として、品川区の実績をどう評価されているのかを説明を求めました。","respondent":"河合生活安全担当課長","answer":"ポイ捨てのたばこの本数を、著しく今減っているという状況は、現状は正直言いましてございません。今後も公衆喫煙所、指定喫煙所の整備等をやるとともに、効果的な指導・啓発でそういったところを抑え込んでいきたいと考えております。","id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"過料に至らないところの指導件数というところまで確認されているのかもお聞かせほしいと求めました。このエリアの制定というのは品川区で当然やっているものですから、過料が、そもそも１,０００円でいいのかというところもあります。","respondent":"河合生活安全担当課長","answer":"件数につきましては、令和４年度になりますと、各５地区に限定しますと２,５３８件というところで指導件数は出ております。条例の改正の検討というところで提案がございましたが、整備も踏まえた上で検討だとは思いますので、吸う人。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"そういった時間帯をずらしてみるとか、併せて言えば、ごみのポイ捨てについてもぜひ過料をしっかり取ってほしいと求めました。その方々もどんどん高齢化していって、まちをきれいにする力が弱まっていくというのも事実だと思いますので、最後にそこのご答弁をお願いいたします。","respondent":"河合生活安全担当課長","answer":"著しく環境を害するというふうなところでありますけれども、捨てている状況といったものを確認したときには、悪質なものは過料の対象というところで積極的にやっていきたいとは考えております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは２点、お伺いしたいと思います。７８ページの従前居住者用住宅使用料、また１１５ページの共通商品券普及促進事業について、それぞれお伺いしてまいります。","respondent":"小川木密整備推進課長","answer":"従前居住者用住宅の現在の入居状況ですが、１０月１日現在、５７部屋中３４部屋の入居、入居率といたしましては６０％といった状況です。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"５７部屋中３４部屋で６０％ということで、余裕があることを確認いたしました。私が先日、一般質問にて取り上げさせてもらった火災被災者の住まいについて、より具体的な内容がご紹介できるようであればお願いしたいと思います。","respondent":"伊藤災害対策担当課長","answer":"私からは、従前居住者用住宅の使用に際しまして、火災被災者について減免等についてお答えさせていただきたいと思います。検討は進めているような状況ですが、まだまだ検討段階ということですので、また進みましたらご説明。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"あれば人員はどう組まれているのか。お聞きしたいと思います。","respondent":"伊藤災害対策担当課長","answer":"所在を確認し、職員が少なくとも最低２名体制で現場に行き、被害の状況を確認しているという形になっております。これにつきましては、土日祝日、年末年始にかかわらず災害対応をしているというような状況です。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"続いて、１１５ページの共通商品券普及促進事業に関連しまして、プレミアム商品券についてお伺いします。令和４年度の申込み希望数はどのくらいあって、それに対して現在は具体的にどう対応なされたか、お聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"３冊、４冊とそれぞれご希望がありまして、最終的には商店街連合会で抽せんを行っております。あるいはもともと１冊ご購入で１冊、４冊ご購入を希望された方に対しては、現在は最大３冊までご購入いただけたという状況です。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"４万冊で、現在２万１,０００冊ということで、こちらは余りというのはどういう対応をされているか、もう一度ご答弁を。","respondent":"小林商業・ものづくり課長","answer":"１冊ごとに必ず買えるようにはいたしております。実際に１,８７３名、また２冊希望以上の方でまた抽せんという形で、販売総数が約４万冊になるように調整しています。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"そこで、商店街連合会のホームページでは現在、地図と一緒に様々な商品券の店舗検索ができるサイトも出され、工夫されていると認識しています。そちらを読み取ると、現在の取組状況など、改善の最新の工夫されている情報等があれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問にお答えいたします。ＱＲコードなどの活用なども含めまして、利便性をどうやって上げられるかというところは、商店街連合会とまた協議してまいりたいと思います。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"併せて、ご高齢の方だとスマートフォン等を活用できない方もいらっしゃると思いますが、こういった点での支援対策等があれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問にお答えいたします。そういう中で直接ご案内するものもありますし、「こういうふうに使います」ということでお教えいただくというような方法もあります。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、７８ページ、自転車駐車場使用料に関連して、１６２ページ、放置自転車等保管料について併せて伺います。そこで、駅付近の駐車場の利用状況、そして放置自転車の撤去数について、区の状況を説明を求めました。","respondent":"工藤交通安全担当課長","answer":"区内自転車等駐車場は２６か所ありますが、こちらについては全体で７０.４％の利用率となっております。放置自転車の撤去数については、おおむね８,０００台という形になってあります。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"恐らく２６か所、また駅から遠いところも合わせての利用率になっていると思いますが、駅付近の利用の状況についてお伺いしたいという点が１点。この状況について、区としてどのようにお考えか尋ねました。","respondent":"工藤交通安全担当課長","answer":"令和３年度と令和４年度の撤去台数の関係なのですが、令和３年度はコロナの影響がございまして、撤去活動に若干の制限をかけてございました。令和４年度につきましては、その制限を緩和した関係で、撤去台数が増えているところです。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"子育て中の保護者の方から駅付近でお話を伺うと、チャイルドシートをつけた自転車は幅があって、そもそもとめられる設計になっていない。先ほどご答弁で、駅近くの利用率を把握していないということでしたが、このような一つ一つの区民の声をどのように把握しているのか尋ねました。","respondent":"工藤交通安全担当課長","answer":"２点目、視覚障害者の方々の危険につながるところですので、そちらについては指導・啓発を厳しく継続してやってまいりたいと思います。駐輪場の状況によって、駐輪の利用率の高いところは、そういったところは適宜工夫しながらやっていきたいと考えています。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"区として、自転車活用推進計画と駐輪場整備について、どのようにお考えでしょうか。そして駅付近の駐輪場の利用が偏ることに対して、区としては現在どのように対応を検討しているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"自転車活用推進計画、昨年度から今年度にかけて２か年、公募区民の方にも参加いただきながら、策定に向け、検討を行っている状況です。先ほどいただいた様々な声については、今回、計画策定に当たって、区民アンケート、それから駐輪場の利用者アンケートなども実施しています。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"いいとは私も思うのですけれども、まずは今困っているという声をしっかりと聞きながら、対策をした上で進めていただければと要望します。本日、質問をほかにも考えてきていたのですけれども、間に合わない点については別の委員会で質問させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"１２０ページ、１０１ページ、品川駅南地域周辺まちづくり事業について伺います。定点観測になっていると伺いましたけれども、紹介できるものがあれば、直近でよいので併せてお願いいたします。","respondent":"坂野保健予防課長","answer":"その１個前の週が１１.３７人。インフルエンザについては、まだ増加傾向です。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、高齢者の命と健康を守るためにも、接種を促す予防接種の無料化を品川区でも行うべきではないでしょうか。今からでも補正予算を組むなどして対応するよう求めますが、いかがでしょうかということが１つ。","respondent":"坂野保健予防課長","answer":"今日は１０月２日なのですが、１０月１日から、本日からもう既に接種が始まっておるという状況です。２,５００円の部分が、この２,５００円を全額公費負担するとすると、１億３,７００万円ぐらいが概算です。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"品川区で、令和２年度、令和３年度、令和４年度のインフルエンザ予防接種の接種者数と、およその接種率を伺いたいと伺います。それと、他区で無料にしているという区は、今、２３区中どれぐらいあるのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"こちらは概算ベースの接種率で恐縮なのですが、令和２年度で約６３.９％、令和３年度で約５０.５％、令和４年度で約６１.０％で、概算です。２３区全体の半分よりはまだ多くはない区が、今年度、そういう感じで補助していると承知しております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"渋谷区も６５歳以上、目黒区は７０歳以上、これはどうなっているのかと。なぜ品川区はやらないのか、その理由を伺いたいと思います。","respondent":"坂野保健予防課長","answer":"令和２年度、令和４年度に関しましては、東京都の補助があってやっていたという経緯があります。来年度以降、これはどうなるかというところももちろんあるかと思うのですが、東京都の補助の趨勢を注視してまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですけれども、これが結果的に経営も圧迫しているというような実態など、ご存じなのでしょうか。伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区内の特別養護老人施設等における人材の確保等についてのご質問についてお答えします。は実務者研修等の研修を受けた者に対して助成金を出すなどして、少しでも人材確保が務まるように、区としても支援をしているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"提案","question":"社会的にもこれからますます必要な仕事で求められるし、ＡＩなどに任せることもできない仕事なわけですから、介護の現場に思い切って税金も投じて。この２つを要望し続けているわけですが、改めてこの２点を求めたいと思いますが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"国でも第９期の介護保険事業計画の策定に向けまして、介護報酬の改定というところで、その動向を引き続き注視したいと思っているところです。例えば区の特別養護老人ホームにＩＣＴの見守り機器を設置させていただいたりすることによって、そういったところで少しずつ…","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"もうどうにもならないと思っていますので、人が集まるための対策を、区として独自に打っていただきたいというのを繰り返し求めます。それと、国に処遇改善交付金の復活を求めてくださいと言ったのですが、求めないということなのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区の介護人材の確保の独自策というところでは、品川区は平成７年から介護専門学校も運営しておりますので、その辺りのところに引き続き努めたいというところと、国の処遇改善については今後も動向を注視してまいります。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１４６ページ、ふるさと納税寄附金、１７３ページ、インターネット映像配信委託、５４ページ、特別区たばこ税について伺います。一方で、品川区に歳入として入ってくる分、令和５年度の見通しと令和６年以降の見通しをそれぞれ説明を求めました。","respondent":"提坂税務課長","answer":"その先というのは、なかなか見込みを出すのは難しいところです。令和６年度以降について、流入額というのも読むのがなかなか難しいというのが実情です。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。特別区長会としていろいろとご要望など出されていると思うのですけれども、対抗策をどう立てていくおつもりなのか、説明を求めました。","respondent":"提坂税務課長","answer":"寄附金の使い道を明確にして、各セクションで様々なプロジェクトを前面に押し出して、それに賛同していただける方についてご寄附いただくという形でＰＲしていければと考えています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。今年の７月３１日にもうご要望を出しておりますけれども、そうした改善やご要望を出しているのですけれども、どういったご様子か尋ねました。","respondent":"提坂税務課長","answer":"７月に区長会から要望を出したときの国側の受け止めとしては、引き続き現状を受け止めて検討していくといった内容だったかと思います。","id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"提案として、例えば返礼品、お酒や食料品を区民の方が寄附します。ぜひ言っていただきたいのですけれども、そうしたご提案について、いかがお考えか尋ねました。","respondent":"提坂税務課長","answer":"やはり先ほども申し上げたような、使い道を明記した寄附金を募るなどという形で、粘り強くやっていきたいと考えています。区外の方については、食料品、どれぐらいの効果があるかということを研究してまいりたいと考えています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"私が言っているのは、ふるさと納税制度はもう全体、全国で、返礼品目当てで行うのであれば、併せてその地方のガバメントクラウドファンディングに寄附をしなくてはいけないというような規制について言ったのですけれども、その辺りはいかがお考えか尋ねました。","respondent":"提坂税務課長","answer":"その辺は品川区単独で判断できるものではないので、他自治体の動向も踏まえながら、動向を注視してまいりたいと考えています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"このままだと平行線をたどってしまうので、特別区長会を通じて、ぜひ厳しくご要望をおっしゃっていただきたいと考えております。３４６万円ほどかかっているかと思うのですけれども、このインターネット映像配信委託は、現行はどこかの業者に頼んで配信されているのか尋ねました。","respondent":"大澤区議会事務局長","answer":"インターネットの配信ですけれども、これは委託しておりまして、本会議の生中継と録画の中継、予算・決算特別委員会の録画中継を、インターネットを通して配信しているというものです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"何より今、ユーチューブというのは本当に一般的なものになってきておりますし、いわゆる拡散力が非常に優れている。その辺り、今後、ユーチューブで議会中継をやっていくというのはいかがか尋ねました。","respondent":"大澤区議会事務局長","answer":"区議会に関心を持っていただくためにも、様々な方法での周知が必要とは認識しています。予算的なことやシステム的なことなど、いろいろあると思いますけれども、実現に向けてご対応させていただきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"続いて、特別区たばこ税について伺います。これは、たばこ税増税といったこともあるのか尋ねました。","respondent":"提坂税務課長","answer":"令和４年度と令和３年度を比較した場合、やはり２億６,５００万円ほど増収になっておりますが、なかなか分析は難しいところです。減っていくのかというのは、なかなか難しいところではありますけれども、少なくとも減ることはないのではないかという気がいたします。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"在宅勤務が増えてくると、やはりたばこを吸われる方が増えてくるということで、なかなか減ることはないということです。したがいまして、これはやはり今後、急激に減ることなく、むしろ安定財源として、たばこ税が定着するというお考えでよろしいのか尋ねました。","respondent":"提坂税務課長","answer":"安定した財源ということで、貴重な税目ということで注視してまいりたいと考えています。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"広告料収入の内訳について教えていただけますでしょうか。掲載している企業の分野の例や、媒体ごとの収入をお伺いできればと思います。","respondent":"遠藤財政課長","answer":"こちらの関係で約６１８万２,０００円、このような形で広告がつきまして、こちらが２００万円余となっております。庶務課で教育委員会の広報紙の広告掲載ということで、５万円ほどの歳入をしています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"確認","question":"そこで、デジタルサイネージについてもお伺いしたいです。事務事業概要より、現在、品川区内においてデジタルサイネージは２９台設置されていると確認しました。","respondent":"辻広報広聴課長","answer":"委員がおっしゃいますとおり、全部で２９台、庁舎や地域センターを中心に配置しています。これは静止画なのですが、地域センターは独自にやっておるものもありますが、動画コンテンツにつきましては共通のものが多いです。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"例えば江東区では、その財政効果は全体で１,５００万円ほど見込んでいて、当区の収入額の約１.５倍以上の収入を想定しています。この点の見解も併せて伺います。","respondent":"辻広報広聴課長","answer":"今後、デジタルサイネージの置き場所も含めまして、多分、別の場所になった場合には、また検討の俎上にのるかとは考えております。デジタルサイネージを使って多くの人に有益な情報を流せるということはすばらしいことだと思いますので、調査研究も進めてまいりたいと考えていま…","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"最後に、広告料収入の増加が品川区の収入確保にどのように貢献するとお考えか、また今後の展望についてご意見をお伺いできればと思います。広告収入を活用して、区の発展と住民サービスの向上に貢献する方法について、お考えをお聞かせいただけますか尋ねました。","respondent":"遠藤財政課長","answer":"広告料収入のこれからの増加ですけれども、やはり一般財源として自由に使えるお金が少しでも多いというのは重要かと考えています。今後も広告収入をはじめ、様々な財源の確保に努めていきたいと考えているところです。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"公園運動施設の使用料について質問します。未済が発生するケースと、未済が発生する主な要因やパターンについて、詳細を教えていただけますか尋ねました。","respondent":"三井スポーツ推進課長","answer":"もう一つが、当日予約で利用した納付書払いでの支払いがなかった方が５件程度で、約３万円ほどとなります。続きまして、督促や催告を繰り返しても支払われない状況が続いているというような形で、収入未済として残ってしまっているような状況になります。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"その際、こちらの当日払いを可能にすることで、納付漏れが減少したりというお考えがありますでしょうか。使用料金の支払いが滞った利用者・団体に対してのアプローチなのですけれども、さらなる検討がされているか、伺います。","respondent":"三井スポーツ推進課長","answer":"ただ、やはり委員がおっしゃるように、当日払いができれば、そちらの未納は防げるのかと思います。今後やはり支払い漏れがないようにしていくためには、キャッシュレスなどの対応も含めて検討していく必要があると考えております。","id":"exchange-039"},{"speaker":"せらく委員","kind":"意見","question":"皆様が利用しやすい施設になるように、引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、児童相談所新築についてお伺いいたします。人事と財政部門からの理解と協力ということについて、２０１７年９月の行財政改革特別委員会、２０２０年９月の一般質問でお伺いしました。","respondent":"崎村人事課長、遠藤財政課長、若生健康課長","answer":"虐待の対応件数などに応じて配置基準が定められておりますし、また、育休等で欠員となることも多いということも聞いているところです。… 令和４年度の協議を継続というところで、協議を進めるというところで、しっかり取り組んでいければと考えているところです。… こちらの器具のメーカーの説明によりますと、独自に指標を算出することで、骨の健康度を５段階で表示するというようなものです。…","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは時間がありませんので、要望までになってしまうかもしれないのですけれども、まずグリーフとは何でしょうか。要望なのですけれども、グリーフケアの理解を広めていくことが大切だと考えておりますので、こちらは要望とします。","respondent":"榎本荏原保健センター所長","answer":"大切な人を亡くされてショックを受けているグリーフケアについて、お答えいたします。ご自身で悩まれてご相談がある場合もありますが、心の相談という形で、丁寧にお気持ちを聞いてご相談対応に乗っております。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"都支出金、１３４ページ、学校・家庭連携推進事業費、いじめ防止対策事業補助金、１３７ページ、マイスクール運営費より伺ってまいります。改めて、学校・家庭連携推進事業の現状を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"令和４年度は１１校、令和５年度は１６校で実施しております。こうした取組が広がっていくよう支援してまいります。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"活動が子どもたちに人気だとは伺っていたのですけれども、校長先生よりお話を伺いまして、改めて感銘を受けました。マイスクール八潮のキャパシティーの現状と、八潮まで通えない地域のご家庭の現状の課題について、区のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"送り迎えが難しいエリアのご家庭があることも認識しております。学習支援は喫緊の課題と考え、校内の居場所づくり等、様々な受入先を確保することが必要であると考えております。","id":"exchange-044"},{"speaker":"西村委員","kind":"質問・要望","question":"同じく会派の視察で景徳学園へ伺わせていただいた際に、荏原第五中学校でランチルーム登校があるというお話を伺っております。こうした荏原第五中学校の取組をぜひ広げていってほしいと求めましたが、ランチルーム登校がどのようなものなのか教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"教室に入れない生徒をランチルームに受け入れ、教室とオンラインで結んで授業を受けるといった取組を独自に行ってまいりました。令和５年度からは、校内別室指導支援員配置事業を活用し、退職校長や大学生を支援員として、教室に入れない生徒の学習支援等に取り組んでおります。","id":"exchange-045"},{"speaker":"西村委員","kind":"質問・要望","question":"プレーパーク運営者の方に伺うと、実際に不登校になってプレーパークに来ていたお子さんがいると。区のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"区立図書館をはじめとする区内施設やフリースクール等との連携、またメタバースといった仮想空間の活用などが考えられると考えております。今後、国や都の動向も注視しながら、児童・生徒、そしてご家庭の安心につながる取組を検討してまいりたいと考えております。","id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"今日、一番ご提案させていただきたいのが、不登校になる前の行き渋りの入り口の段階でサポートできる支援をご提案させていただきたいと考えています。場合によってはフリースクール提携先まで掲載できればとてもいいと、私の中ではイメージしているのですが、区のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"現在、登校渋りのお子様に対しては、保護者は担任を通して相談を行っており、必要な支援を行っているところです。今後、ホームページの内容をより充実させたり、保護者への十分な案内ができるように努めてまいりたいと考えております。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問・要望","question":"その後、いろいろな選択肢があるところで悩んでいる方が多いと考えていますので、ぜひともご検討ほしいと求めました。促すことが難しくても、サイトに掲載できるとすごく理想的だと考えていますが、区のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"家庭に起因するような場合であっても、現在、ＨＥＡＲＴＳが対応させていただいて、必要な支援や関係機関とのつなぐ役割を果たしております。今後とも、そうしたこともできるということを広く周知してまいりたいと考えております。","id":"exchange-048"},{"speaker":"西村委員","kind":"意見","question":"子どもたちにも選択肢がたくさんあるのだということを伝えていくためにも、予算をしっかりと割いていただいて、対応をお願いしたいと思います。こういったところとの、品川区を出た活動もあってもいいのではないかと思いますが、ご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"現在、マイスクール八潮では、学校の宿泊行事に参加できなかった児童・生徒を対象に、２泊３日の宿泊行事を行っております。そうした社会的な自立に向けた有意義な取組になっておりますので、今後も継続してまいりたいと考えております。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"先日、ここでもやはり相談窓口が明確で、右往左往しないで済むというのはすごく重要だと思いました。いろいろな選択肢があっていいですから、そういった場所も、区のお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒が様々な興味や関心を持ったものにチャレンジできる、そうした取組が大事だと考えております。地域未来塾等で学校の中でサポートできるものが多くありますけれども、今後そうした場の提供についても検討してまいりたいと考えております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"５２ページ、特別区民税、１２２ページのベビーシッター利用支援事業（一時預かり利用支援）補助金について伺っていきたいと思います。特別区民税ですが、最近ずっと決算特別委員会のときに伺っています。","respondent":"佐藤企画課長","answer":"子ども・子育て支援、虐待・いじめ対応、様々な行政課題があります。国や都の動向を見まして、財源は１円でも活用するというスタンスを守って、積極的に施策を展開していきたいと思います。","id":"exchange-051"},{"speaker":"つる委員","kind":"提案","question":"各委員がこれからいろいろな提案、本当に地域で聞いた声を伺って、こうした機会をいただきながら施策提案をしているのが。実は２００３年ぐらいだったでしょうか、この書籍を引用されながら質問をして、当時において推進をいただいたという質疑も確認させていただきましたとの意見を述べました。","respondent":"宮尾庶務課長","answer":"今、郷土史の作成のご支援についてのお尋ねをいただきました。今、委員からお話があったように、歴史館の学芸員の方におつなぎするような取組もさせていただいているところです。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"求めて、２０２２年ですか、令和４年度から実施いただきました。利用想定も１７０人だったのが１,１９０人ということで、令和５年度を確認させていただきましたらば、予算立てとしては４,５００万円。","respondent":"石井保育支援課長","answer":"昨年度の実績１億３,０００万円に対して、今年度予算が４,５００万円ということでございました。令和４年度後半にかけて、そこまでの状況が想定されずに、４,５００万円ということで計上したところです。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"１０分の１０ですから、例えばこれは年４回、今は清算する利用者のタイミングがあろうかと思います。今、走っている今年度の感触も含めて、現状を説明を求めました。","respondent":"石井保育支援課長","answer":"想定をはるかに上回る申請をいただいてあります、この事業ですが、もちろん審査体制等、強化していかなければならないと考えています。今年度は１つの係だけに任せることをせず、委託等々の手法も含めて、もろもろ検討していきたいと考えています。","id":"exchange-054"},{"speaker":"つる委員","kind":"提案","question":"当然、利用できる時間、１４４時間、それから多胎児については２８８時間ということで設定いただいています。これを提案させていただいた当時も含めて、そうした両方の視点を含めて、この強化を図ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"では、本日は、２６ページ、国民健康保険、３２ページ、後期高齢者医療、１２６ページ、健康増進事業費についてお伺いいたします。高齢者の健康維持、介護予防についてお伺いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"そうしましたら、しながわシティマラソンの進捗状況についてお伺いいたします。こちらではどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして１２６ページ、健康増進事業費についてお伺いいたします。こちらの健康づくり支援事業に関して、現状を説明を求めました。","respondent":"若生健康課長","answer":"健康部分につきましては、各種健康診査・検診の費用、それから成人歯科検診等の影響の歳入となっています。肝炎ウイルス検診、眼科検診、それから先ほど申し上げました歯科検診といった幅広い健診を実施しています。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"提案","question":"１つ提案があります。多くのメリットのある地域のラジオ体操も、健康プランの一部に組み入れて、助成金を出すのはいかがでしょうか、区の見解をお聞きいたしますとの意見を述べました。","respondent":"若生健康課長","answer":"実際、具体的なラジオ体操の活動といったところについて、様々行われていることは区も認識しております。健康プランへの位置づけや、そういったものも含めて、今後そういった支援ができるかどうかというところは考えてまいりたいと思います。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"これで本日の質問を終了いたします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"山本委員","kind":"質問","question":"私からは、１０５ページの就学援助費、時間次第で１１５ページの中小企業事業資金融資あっせんについて伺います。１０５ページの就学援助費について伺います。","respondent":"柏木学務課長","answer":"令和４年度の実績ですが、申請者数は４,４９９人、認定者は３,３４３人で、申請者に対する認定率は７４.３％です。全児童・生徒に関わる受給率は１５.１％となっています。","id":"exchange-061"},{"speaker":"山本委員","kind":"意見","question":"それから申請者に対して２５％ほど、利用できていない方がいらっしゃるという現状を理解いたしました。就学援助制度については、引き続き、保護者の負担を軽減するための援助・拡充に向けた検討が必要であると思いますが、区のお考えを説明を求めました。","respondent":"柏木学務課長","answer":"就学援助の事業につきましては重要な事業と考えています。品川区は特別区の中でも基準は高いほうと考えていますが、引き続き、他区の状況を注視しながら考えてまいります。","id":"exchange-062"},{"speaker":"山本委員","kind":"質問・要望","question":"品川区はほかの区に比べて高い水準を維持していると思いますが、さらに取り組んでいただきたいというところでございまして、２点ご要望申し上げます。２点目は、必要な世帯への援助が行き届くよう、援助対象者の所得金額の上限の引上げについてもご検討を要望いたします。","respondent":"柏木学務課長","answer":"就学援助の月額の物価スライドについてですが、就学援助の支給額ですが、基本的に都区財政調整の基準額を基に、毎年度、見直しを実施しています。月ごとの物価スライドの導入につきましては、なかなか毎月どういう形で図っていくかというところがありますので…","id":"exchange-063"},{"speaker":"山本委員","kind":"質問","question":"全ての家庭でかかる就学費用の負担削減に向けた取組は、品川区の子育て教育施策の中で重要な課題の一つであると考えますが、いかがでしょうか。区のお考えをお伺いいたします。","respondent":"柏木学務課長","answer":"保護者の負担の軽減は必要なことと考えています。学用品に限らず、保護者の負担を軽減することについて検討してまいります。","id":"exchange-064"},{"speaker":"山本委員","kind":"提案","question":"１つのメーカーに大量発注するなどの工夫、現状よりコストダウンが図れるのではないかと考えますが、いかがでしょうか。地域との関係性を踏まえ、地域の販売店との結びつきについては別の機会を提供し、子育て世帯のことを第一に考えるべきではないか尋ねました。","respondent":"柏木学務課長","answer":"保護者の負担軽減は必要なことと先ほど答弁させていただいた考えには変わりはございません。学校とも相談しまして、方法等も含め、今後検討してまいります。","id":"exchange-065"},{"speaker":"山本委員","kind":"質問・要望","question":"次に中小企業事業資金融資あっせんについてお伺いしたいと考えておりましたが、時間も限られておりますので、次の機会に移したいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問","question":"令和４年度になって、各１件ずつで合計２件ということで、かなり実績が乏しいのですけれども、区としてのお考えはいかがでしょうか。どういうことでこんなふうに使われていないのかということで、お願いします。","respondent":"菅野高齢者福祉課長","answer":"こちらにつきましては、委員ご指摘のとおり、令和４年度に看護師が１件、保健師が１件ということで、助成をしています。各法人、今後どういった形で１件ずつだったのかというところも法人等に聞き取りをしながら、よりよい方策については検討していきたいと考えています。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私からの提案なのですけれども、３０万円支払われるという助成金なのですが、これは非常に使い勝手が悪い。緊急介護職員確保と銘打っていらっしゃるわけですから、もっと検討したり、そういった取組を今後検討していただけるか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"具体的なお話等をいただきましてありがとうあります。遠隔地からの人材確保支援につきましては、１年に一、いろいろな様々な支援というか方法で人材確保には努めたいと考えていますので。","id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはり使い勝手が悪いし、むしろ、条件をもっと緩和して、早急に実施してほしいと思います。早急に実施していただけますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘のとおり、確かにヘルパーの確保ということで、有効求人倍率の１５倍という数字は、私も国の調査等で見ました。その次の、区の実情に応じた形で、事業者の支援に可能な限り努めていきたいと思っているところです。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"意見","question":"５年もしたら、４人に１人が７０歳になってしまうという状況で、なのに離職率が高い。以上ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"澤田委員","kind":"質問","question":"この２つから、お伺いします。１１６ページの民生費補助金、高次脳機能障害者支援促進事業についてお伺いいたします。","respondent":"松山障害者支援課長","answer":"私から、高次脳機能障害者支援促進事業、１５７万９,０００円の内訳についてお答え申し上げます。２人の専門相談員が交互に対応しているものです。","id":"exchange-071"},{"speaker":"澤田委員","kind":"質問","question":"絵柄を多く利用したり、当事者の「あるある」なエピソードを漫画化して紹介するなど、より分かりやすくブラッシュアップするのはいかがでしょうか。区としてのご見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"確かに現在のリーフレットは、関係機関向けのリーフレットとなっており、５年以上も前に作成したものを随時更新しているという状況のものです。心身障害者福祉会館や、ぐるっぽ等の指定管理者の方々と協議をして、リニューアルの方向で検討を進めたいと考えています。","id":"exchange-072"},{"speaker":"澤田委員","kind":"質問・要望","question":"周囲などの不理解に苦しむ方々にとって、それらを緩和し、次の行動へとつなげる大切な事業だと考えています。様々な関係機関との連携をより一層深め、強化していただきますことを要望いたしますが、区としてのお考えを説明を求めました。","respondent":"松山障害者支援課長","answer":"高次脳機能障害の方への関係機関の連携についてのご質問にお答え申し上げます。幅広い関係者と一緒になってワークショップ等を行っておりますので、今後も引き続き顔の見える関係をつくっていきたいと考えております。","id":"exchange-073"},{"speaker":"澤田委員","kind":"質問","question":"増額に至った理由はなぜだとお考えでしょうか。令和４年度のリサイクルの収入の内訳として、何によるものが一番多いのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"２番目の質問に対しても、収入の中で一番大きいものを占めているというのはペットボトル。それから、あとはアルミ缶なども、かなりの収入の多くを占めているものです。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問・要望","question":"プラスチック製品全般の資源化を求められることとなりましたけれども、ごみ分別の一覧表をすぐに確認できるなどすれば、区としてのご見解を説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"収入金額、皆様がリサイクルで出している金額がこれだけ反映していますという説明というのは、そういう啓発を行う際には。それから、ＱＲコードについても、様々工夫しまして、啓発に取り入れていきたいと考えています。","id":"exchange-075"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"５２ページの特別区民税について、６０ページの特別区財政調整交付金、お聞かせほしいと求めました。なぜかというと、４人の都議会議員が選出されるのですが、急に東京都の立場になってしまうのです。","respondent":"提坂税務課長、遠藤財政課長","answer":"様々な経済支援策などで、令和２年１月が底だったのですけれども、そこから令和４年にかけまして持ち直したということが一番大きいのかと思います。それから… 私も３月までは商業・ものづくり課というところにおりまして、４月から財政課というところに飛び込んです。財政課の立場として、一生懸命やるですので、そこは変わりがないと思っているところです。","id":"exchange-076"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"だって、品川区は魅力がいっぱいあるではないですか。何で、ふるさと納税になると急に、やらないと言ってしまうのか尋ねました。","respondent":"河合生活安全担当課長、提坂税務課長","answer":"区といたしましても、吸う人、吸わない人の共存というところで、喫煙所の整備を進めているところです。民間喫煙所の補助事業というところで協力していただいているところに助成する形で、整備を進めていきたいと考えております。 品川区に来ていただく、ひいては品川区に住んでいただけるような返礼品を開発して、流入額も増やしてまいりたいと考えています。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問","question":"１２０ページ、１２４ページ、順不同で質問します。委託契約しております事業の現状と評価も併せてお答えください。","respondent":"藤村子ども育成課長","answer":"令和５年度に関しましては、システム関係の導入等を考えているというところで補助金に充当しているような形です。就労につながっているということもありますので、ひきこもりの方々にとっても、家族の方々にとっても有用な事業になっているかと考えております。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"現実、農業体験というのはなかなか利用されていないという現状もお聞きしております。当事者や家族の方など、この点についてご見解をお聞かせいただきたいのと、現在そういうことで取り組んでいることがあればご紹介ください。","respondent":"藤村子ども育成課長","answer":"ひきこもりから脱却するというところの１つのプロセスを経ているのかとは思いますけれども、アウトリーチ的な支援というところなのですが、早期発見やアウトリーチというところも今後検討していければよいかと考えております。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"やはり当事者の方が、また家族の方の実態把握、この調査は必須ではないかと考えております。タイミングを捉えて、必要な方へ必要な支援が届くような仕組みの構築を検討してはどうかと考えますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"子ども未来部としても、また区としても、横のつながりで横断的にこういった問題について考えていかないといけないとは考えているところです。調査についても今後どういった形で行っていけばいいかというところを考えつつ…","id":"exchange-080"},{"speaker":"こんの委員","kind":"確認","question":"次は、高齢社会対策包括補助金の中で、高齢者の安否確認事業についてお聞きいたします。約８万人強の人数から見て、利用者はこれだけなのですかと、利用実績の現状についてどのように分析されていますか尋ねました。","respondent":"東野福祉計画課長","answer":"利用者数の、まず推移ですが、令和２年度７８３件、令和３年度７７６件、令和４年度８３１件ということで、設置の件数が推移しています。誤報がそのうち３９件、正報が１０９件ということで、救急搬送に至ったのが７０件というような実績が上がってあります。","id":"exchange-081"},{"speaker":"こんの委員","kind":"提案","question":"独り暮らしの高齢者の安否を確認したくても、把握したくても、できないといったことが考えられます。周知する、受給者については安否確認体制の構築をこのシステムでつくったらどうかと提案いたしますが、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"生活保護の関係につきましては、生活保護の担当の部局と連携を取りまして、区として周知方法につきましては考えてまいりたいと思います。区の広報やＳＮＳなどにつきましても、周知方法の拡大を考えてまいりたいと思います。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"ＳＮＳでもという話ですが、高齢者はなかなか、ＳＮＳを使って果たして周知が広がるのでしょうかというところが気になります。月３００円の代金はなかなか生活的に難しいということも考えられますので、双方、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほども少し説明があったのですけれども、よく分からなかったので、改めて住民税が増える理由についてどう捉えているのか伺います。非課税世帯の推移がどうなっているのか、増えていることはないのか、どうでしょうかということで伺いたいと思います。","respondent":"提坂税務課長、遠藤財政課長","answer":"住民税が増えている理由かと考えています。統計上で、所得がおおむね１００万円超の、非課税者の方の所得などについては把握していないというのが現状です。 特に財政調整基金につきましては、令和２年度に１人３万円交付した部分があろうかと思います。少し今現在、少ないような状況がありますので、今後もできるだけ積み増すような形で考えているところです。","id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここで言われたのが、お店で冷蔵庫が壊れてしまってすぐに入れざるを得ないという場合もあるので、この点についても伺いたいと思います。家賃や電気代など、固定控除もしてほしいと求めましたが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ゼロゼロ融資の対応ということでいきますと、これから本格的に支払いが始まるという方で、このような対応で資金繰りの支援を行っているところです。ご支援の必要性が高まっているところですけれども、品川区としましては…","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問","question":"こういう商店街の大変な実態に対して、区としてどう捉えられているかということと、区として今後、やはり品川区の魅力である商店街に対して、それを元気づけていくためにどんな支援がされようとしているのかについて伺いたいということで伺ったので、お願いします。","respondent":"小林商業・ものづくり課長","answer":"商店街の前向きな取組を支援するものとしましては、また個店レベルということでいきますと、融資あっ旋の制度があります。今後の前向きな取組を支援するというような制度がございまして、商店街の、今後の活力が出るような取組を一層支援していきたいと考えております。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０２３年度は新型コロナウイルス感染症対応地方創生臨時交付金は幾らだったのか、また、伺います。この理由についても、どう捉えられているのか、伺いたいと思います。","respondent":"遠藤財政課長","answer":"新型コロナウイルス感染症対応地方創生臨時交付金のお話です。最初に７割の交付、残り３割交付ということになっておりますので、区に来るのかと考えているところです。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問","question":"そのインボイスの問題で少し伺いたいのですが、のだて区議会議員の一般質問で、「インボイス制度は消費税額を適正に納付するための手段。インボイス制度は、消費税を預かっていながら納めなかった免税業者に納めてもらう肯定なものとの考え方なのか、伺いたいと思います。","respondent":"遠藤財政課長","answer":"物価高が３％程度という形になっておりますので、もちろん一因ではあるかですけれども、ほかの要因も大きいのかと考えているところです。そういう部分で、適正なというところで考えているところです。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"益税論、それから預り金ではない、ここのところは品川区としても、そういうことで認識しますということでいいのか、確認させていただきたい。この点についても伺いたいと思います。","respondent":"遠藤財政課長","answer":"そこの部分につきまして区として何かというところになりますと、なかなか難しいのかと思っているところですので、こちらの答弁につきましては国でということで差し控えします。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、アニメーターの方からも伺いました。ここにインボイスがかかってきたら、本当に大変な状況だということも、区も認識してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"田中委員","kind":"確認","question":"財政調整の問題のほうにどうしても注目されてしまうので、それに対して都側の、どういう対応をされているのかということをお伺いしたいと思います。議会運営上、何か問題が新たに発生したということがあるのかどうか、その点をまずは確認したいと思います。","respondent":"遠藤財政課長、大澤区議会事務局長","answer":"３割程度のお金をもらえるところですけれども、７％という形になりまして、４年に分けて歳入をいただくという形になっているところです。ぜひ協議をというところなのですけれども、実質的には議論に今… 議会費のお尋ねです。運営上特に困ったことがあるとは認識してございませんが、コロナの間は行くことができずに、視察の中でいろいろ皆さんに学んでいただいて。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"１番は世田谷区で、２番が実は品川区であります。お考えをお聞かせいただきたいのと、新年度以降の議会費の議論にも、今のご答弁を活かしていきたいと思います。","respondent":"遠藤財政課長","answer":"おおむね２５％という基準があって、この事業費につきましても、なかなかその満額を見てくれなかったりというところもあるです。その辺が厳しいところではありますけれども、必要なものというところで今後もやっていければと思っています。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"その上限を撤廃してほしいという項目も入っているかと思いますので、令和４年度の収支で、予算よりも事業執行が減っているのです。その辺、時間がないですが、説明を求めました。","respondent":"遠藤財政課長","answer":"こちらの部分につきましては、予算と実際の執行になったときで、当然、乖離が出てくる部分もあろうかと思います。２５万円プラスマイナス１０％の、そういうところを引き続き、こちらはできるだけ区の収入を確保できるよう努めてまいりたいと思います。","id":"exchange-093"},{"speaker":"えのした委員","kind":"質問","question":"私からは、１６２ページ、放置自転車等保管料についてお伺いします。撤去した台数の返却率が分かれば併せてお知らせください。","respondent":"工藤交通安全担当課長","answer":"具体的には、短時間に明確な定義はございませんが、１０分から２０分程度というようなところで捉えております。放置自転車の撤去の台数ですが、令和４年度、約９,０００台というところで撤去作業をしております。","id":"exchange-094"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。撤去・保管料の引上げについて、区のお考えを説明を求めました。","respondent":"工藤交通安全担当課長","answer":"条例の制定の部分につきましては、まずは電動キックボードが、委員ご説明のとおり、新たな乗り物ということで出てきております。受け取りに来る者が少なくなるといったところもありますので、今後も他区の動きを注視して研究してまいりたいと考えております。","id":"exchange-095"},{"speaker":"えのした委員","kind":"質問・要望","question":"重たい荷物をどうすればいいのかと、自転車撤去によりお困りの方が増えているとも伺っております。地域区民の現状も鑑みて、緩やかな撤去や、また指導・啓発の頻度、あと改めて周知も多くしていただきたいですが、区のお考えを説明を求めました。","respondent":"工藤交通安全担当課長","answer":"その後に撤去という形を取っておりますので、引き続き、区民に理解を得られるような形で活動を続けていければと考えています。その辺のバランスを見ながら、今後、有効な撤去活動をどうやっていけばいいかということを考えていきたいと考えています。","id":"exchange-096"},{"speaker":"えのした委員","kind":"質問・要望","question":"先ほどの係員の方からのお声かけで、そういったことを多くしてほしいという、これは要望として終わらせていただきます。区内２６か所ある区営の駐輪場が、少しでも駐輪スペースを確保できるような取組をお考えいただいて、私からの要望とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"意見","question":"もっともっと打ち出すべきだと思っていて、これはもう２０３０年に飲料メーカーが、ペットボトルはリサイクルすると打ち出したわけです。それこそ出すべきだと思うのだけれども、その辺、まず先にそれをとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"それから、最近、動向がいろいろと変わっている場面もありますので、こういうリサイクルのものというのは非常に単価の変動が激しいところがあります。いろいろ買取り業者を選ぶところでも難しいところもあったりしますので…","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうところの予想をまず教えていただきたいのと、それでスクラップをどうかけていくのだなどという考えを持ってやったほうが私はいいと思う。行政評価のシートがあるのだから、こういうのも即時対応すればいいような気がしてならないのだけれども、その辺の考え方を説明を求めました。","respondent":"遠藤財政課長、吉岡政策推進担当課長","answer":"こちらは地方自治法第２３３条５項の規定に基づいて、必ず議会に出す、報告するというものになっているところです。今、ここは非常に重なる部分もあろうかと思いますので… 今回約１０年ぶりに事務事業評価を実施するということで、なかなか見にくいというご指摘もいただきました。より効果的な、効率的な事務事業評価を行っていただきたいと思いますので…","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"横断的にやるべきだというのを私は思っていて、これはぜひその考え方を教えていただきたいのと、これも収入もこだわってほしい。私は今４つ目だと言ったけれども、１か所は成功しているけれども、あとはそんなにうまくいっていないと思っている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"足の具合が少し悪いものですから、座って質問いたします。６回まとめてでありますけれども、お聞かせほしいと求めました。","respondent":"大澤区議会事務局長","answer":"区議会だよりの発行ですが、令和４年度につきましては、６回の発行のうち、定例号の４回および臨時号は全戸配布によりそれぞれ２４万部強、新年号は新聞折り込みと駅スタンドによる配布で１０万部弱、合計で１３０万１,６００部となっております。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"区民が本当に品川区に対してどういう気持ちを持っているのかにかかってくると私は思っています。理事者の皆さんのお考えや、何かアイデア的なものがあれば、お聞かせほしいと求めました。","respondent":"大澤区議会事務局長","answer":"区に興味を持って、子育て環境や福祉施策などは一定のウエイトを占めることから、品川区の現状や取組を伝えていくことが重要だと考えております。その中で、このようなことが決まりましたという見出しで新規事業の紹介等がありますので…","id":"exchange-102"},{"speaker":"木村委員","kind":"質問・要望","question":"それを、本当に一人でも多く関心を持たせる方向に導いていくためには、一体何が必要なのか。もしそれがあれば、何か、理事者の皆さんのお考えをお聞かせいただきたいのですが、いかがでしょう。","respondent":"大澤区議会事務局長","answer":"世論調査の中でも、区議会へ関心があると答えた方は５０.２％と半数を超えておりまして、これも前回の調査時よりもアップしております。ぱっと目を引くような写真となっておりまして、まずは区議会だよりを手に取っていただくという狙いに大きく寄与しているものと考えておりま…","id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"ほかに注意点があれば、何をどうすれば、もっともっと興味を引くのか。何かあれば説明を求めました。","respondent":"大澤区議会事務局長","answer":"タブロイド版からＡ４の冊子型に変えたように、必要であれば現状からの変更も含めて工夫を重ねていくということが大切ではないかと考えています。現在、特に若い世代の活字離れも視野に、今後も多様な方法での周知を検討することが必要だと感じております。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひともまだ頑張ってほしいと求めましたけれども、実行したいような何かがあれば、ぜひそれはやっていただきたいと思っています。少しでも興味を持っていただくには、これからは何が今以上に必要だと皆さんはお考えになっているのか、説明を求めました。","respondent":"大澤区議会事務局長","answer":"例えばお子さんができて子育て施策が気になったり、災害に遭われたときに災害対策について調べたりというようなことがあろうかと思います。議会でも取り組んでいらっしゃいますけれども、やはり引き続き、特に若い世代への働きかけが重要ではないかと感じております。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問・要望","question":"私たちは、ただそれを傍観しているだけではなく、我々区議会ができること、やらなければならないことはあると思いますけれども、それは何なのか、もしお考えがあればお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"木村委員","kind":"意見","question":"行政側としては、また私自身もあまりよく分かりませんけれども、もしよろしければ、そういう点をお聞かせください。それを教訓にしていきたいと思っていますとの意見を述べました。","respondent":"大澤区議会事務局長","answer":"恐らく自分の毎日の生活にそのことが関わってくることに気づいているか、気づいていないかということだと思いますので、区政や区議会の動きというのが自分の生活にダイレクトに影響してくるということを併せて伝えていくことが大切なのかと考えております。","id":"exchange-107"},{"speaker":"若林委員","kind":"質問","question":"今後の大きな課題になると思いますけれども、まずは品川区として、このシートをどのように活用していくかというお考えをお聞きしたいと思います。活用というのは、いわゆるどういう成果をここから生み出していくのかというところをまずお聞きしておきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"行政評価シートの区の活用ですけれども、こちらは、区でこういった事業につきまして、課題を検証・分析・評価することで、より効率的で効果的な行財政運営につなげる、そして区政そのものをバージョンアップさせるといったものを目標として行ったものです。","id":"exchange-108"},{"speaker":"若林委員","kind":"提案","question":"無償化というのでしょうか、ぜひ新たな財源の中で、品川区にはご検討いただきたいということが１点。この２つをまずは要望しますけれども、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"現在、事務事業評価と並行いたしまして、令和６年度の予算編成をさせていただいているところです。依命通達の中で、先ほど１％というお話がありましたけれども、引き続き来年度の予算ということで進めさせていただければと考えているところです。","id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"２０億円という数字はともかく、ぜひ新たなチャレンジというか、区民のための着実なサービス向上につなげていただきたい。今後、この協定によって、今やっている森林環境譲与税の活用事業が何か変化していくのかどうかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"構造ですが、特に変更はございません。担い手の確保、木材利用の促進などを狙うものでございまして、こういったものを一層促進させるための都区連携というものです。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問","question":"こういう目に見えるサービスというものも１つあると思います。お父さん、その辺は来年度になりますけれども、今後の取組を説明を求めました。","respondent":"河内環境課長","answer":"１つ、多摩の森活性化プロジェクトといたしまして、都区連携の中で１つ行うもの。それから、エコルとごしなどの啓発講座などでも力強く発信していきたいと考えているところです。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"この約６５億円を何に使うのですかということ。もう少し大胆にすべきところがあるのではないかと思いますが、お考えをお聞きします。","respondent":"提坂税務課長、遠藤財政課長","answer":"先ほど、５０代の方の転入が多いということに関してのご説明ですけれども、結局、５０代の方は高所得者層が多いだろうと。そこに入ってきたことにより人口が増えたということも確かに一因だと思います。 ９月６日に都区協議会が整いまして、一旦は令和４年度の協議を継続するということで、５５.１％の確保ができたところです。区は様々な事業にチャレンジさせていただいているですので…","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうところがあって、人口が増えてきているのではないのですか。もう既に分かっていながら任命されたと思いますので、それをお答えほしいと求めました。","respondent":"佐藤企画課長、遠藤財政課長","answer":"今後の区政の方向性ですが、先ほど来お伝えしているとおり、コロナ禍を受けまして、様々な社会情勢の変更があります。長期基本計画・実施計画がありますけれども、いろいろな施策を練って、区民に求められる施策を進めてまいります。 〔時間切れにより答弁なし〕","id":"exchange-113"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書１２０ページ、高齢者見守り相談窓口設置事業補助金について質問をいたします。これは一体どういう事業のもので、この事業に組み込まれているものなのか、お示しください。","respondent":"東野福祉計画課長","answer":"当初、民生費の福祉計画費のうち、地域福祉推進費の支え愛・ほっとステーション事業に当たる補助金として予定されていたものです。なお、支え愛・ほっとステーション事業に当たる高齢社会対策包括補助金としましては、７,２３８万円を歳入しています。","id":"exchange-114"},{"speaker":"まつざわ委員","kind":"確認","question":"支え愛・ほっとステーション事業に入れる予定があって、メニューの統合、そして補助金で７,２３８万円があるということが、確認が取れました。私の周りにもあまり多くいらっしゃらないように感じますが、事業の周知など、どのような方法で行っているのかお示しください。","respondent":"東野福祉計画課長","answer":"区では、民生委員と支え愛・ほっとステーションの連携により、多くの方の多様なお困り事に対応を図っているところです。区や地域センターなどの窓口でパンフレットを配布しているほか、定期的な区の広報紙への掲載やホームページなどでも周知を行っているところです。","id":"exchange-115"},{"speaker":"まつざわ委員","kind":"質問","question":"フリースペース等、当時は８つの地区で１０か所、現在はもっと増えているのではないかと思っています。１０か所の場所の記載がないというのも、周知にも力を入れていくべきではないかと考えますが、ご見解を説明を求めました。","respondent":"東野福祉計画課長","answer":"よりみちの場所の掲載や、中身の周知のための記載内容の変更等も含めまして、考えていきたいと思います。これまで行ってきました広報紙やＳＮＳなどの効果的な周知につきましても、これからも力を入れて行っていきたいと考えております。","id":"exchange-116"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、福祉を支えるすばらしい事業の拡充、そしてまた１２地区で１９か所と、よりみちなども新しくなっています。支え愛・ほっとステーション事業のもっと拡充になると思いますので、そういった更新をしっかりと要望しまして、早いですが質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"重なる部分もあるかもしれませんが、税金に対する基本的な考え方や、２３区として危機感を持たなければいけないという観点から質問します。先ほどの決算額との関係、そして区民税の損失率という関係から、改めて区長のお考えを伺いたいと思います。","respondent":"森澤区長","answer":"やはり非常に、先ほどご紹介しました順位もありますけれども、危機感というのを感じております。今後、拡充をしっかりとし、流出した分をできるだけ取り戻せるように取り組んでまいりたいと考えています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、特別区長会で国の制度の見直しなどの要望をしていただけるという話だったのですけれども、もう一歩踏み込んで何かできることはないのでしょうか。そういうところから、今言った国の仕組みの中で、果たしてそれはいかがなものかという観点で、どういう主張を国にしていっていただけるのか尋ねまし…","respondent":"遠藤財政課長","answer":"いわゆる、ふるさと納税制度の廃止を含めまして、これまでも見直しということで、特別区長会を通じて実施させていただいたところです。そういう部分で、意見ということで…","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"国に対しての、今、抗議というお話でしたが、ぜひ改善を求めていってほしいと求めました。議会事務局の職員の方々の任免、そして指揮命令権というのは、どなたにあるのか確認します。","respondent":"大澤区議会事務局長","answer":"議長にあります。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"議長だということですね。万が一、職員の方はどなたに通報して、どのような対応が行われていくのか尋ねました。","respondent":"桑村副区長","answer":"そういうものの通報制度をつくるのはなかなか難しいということがありますので、一義的には今、区の職員全てがやっている通報制度。これは、人事課あるいは人権啓発課が中心になっておりますけれども、その通報制度の中で訴えるという形を取っているものです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話があったのですが、正確に言うと上司になるわけですけれども、例えば区長部局にそれが伝わった。指導というのでしょうか、注意というのでしょうか、行われていくのか尋ねました。","respondent":"桑村副区長","answer":"先ほどの繰り返しになって申し訳ないのですが、様々なところで、そういう意味では協議という形になります。現実に調査を今、細かいことはなかなかできない形になりますので、やはりどうしても区長にお任せいただいて指導するような形になろうかと思います。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"１４４ページ、防災ラジオ売払代金、１６６ページ、防災ラジオ販売事業費収入について伺います。ですけれども、後者が収入済額は０円となっているところなのですけれども、この差はなぜこういう差が生じているのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらは、当初、科目を雑入といたしまして、防災ラジオ販売事業費収入５５０万円を予算計上させていただきました。ただ、こちらは事業内容と整合させるため、年度の途中に物品売払い収入で科目更正させていただいたものです。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問","question":"今みたいなことというのはよく起こるのか、当初予算の段階で、ある程度想定できなかったのかとも思うのですけれども、この辺りはどうなのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"本来であれば、予算計上の際にしっかりと事業内容と整合を取るべきところだとは認識しております。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問","question":"令和４年度の販売実績をお伺いしようと思ったら、今回の行政評価シートにしっかりと記載していただいていて、３,２６２台と記載されておりました。では令和５年度ですけれども、販売実績がどのくらいあるのかと、在庫の数をお伺いできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"令和４年度に関しましては、２,０００円で販売させていただいているものが３０７台ということで、合計３,２６１台という形になっています。一般世帯の方で１０５台、合計２６３台、金額といたしましては３６万８,０００円という状況になっております。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"令和４年度の防災ラジオの関連経費ということで５４５万６,１７７円が計上されているのですが、当初歳出予算の見積書を拝見させていただきました。配送委託のほうですけれども、令和５年度については予算見積書にはこれが計上されていないというところなのですが、これはどういう事情か尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"こちらですが、令和４年度から、新しいタイプの防災ラジオの配布を開始いたしました。事前に納付書でお支払いいただいて後日配送するという流れに変更になりましたので、こちらの委託は令和５年度は行っていないという形になります。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"令和５年度については、そういう委託はしていないということなのですが、では令和５年度は、このラジオを送るのは、個別にお送りすることになると思うのですけれども、これを送るのは大体幾らぐらいかけて送っていらっしゃるのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"令和５年度、防災ラジオに関しましては、ゆうパックで発送しています。単価が５８５円となっております。","id":"exchange-127"},{"speaker":"松本委員","kind":"質問","question":"防災ラジオは、高齢の方だったら１,０００円ぐらいで売っていて、一般の方にも２,０００円で売っているものです。やはりどうなのかということで、もう少し高いものを何とかできなかったのかと思うのですが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"内訳ですが、配送の委託が２,２００円、代引きの手数料が２２０円という形になります。〔同日後刻に「配送料２,２００円、配送手数料２００円」と答弁訂正あり〕","id":"exchange-128"},{"speaker":"松本委員","kind":"質問・要望","question":"これは令和５年度はもうなくなっているということなので、きっちりと安いといいますか、単価は計算して出してほしいと求めました。どういう方にお送りされたのか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"質問にお答えする前に１点訂正を。こちらの郵券として活用させていただいています。","id":"exchange-129"},{"speaker":"松本委員","kind":"質問・要望","question":"やはり防災無線が聞こえない方にどういうふうに防災情報を届けるかで、メールなど、やはりこれはラジオでという方がいらっしゃるのだと思います。こういうラジオがありますというのを伝えてほしいと求めましたし、そういう方たちに対して直接、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"防災行政無線が聞きづらいという方に対しましては、お問い合わせいただいた方には、防災ラジオのＰＲはしています。は広報紙等を通じて広く周知してまいりたいと思います。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"歳入とは何ですか。そして、歳入はどのように決まるのか尋ねました。","respondent":"遠藤財政課長","answer":"歳入につきましては、１年間の区の様々な予算ということで、いろいろな収入の総額と考えているところです。こちらはそれぞれの所管から歳入の項目がありますので、それを積み上げていくような形で予算が決まるというようなところです。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"ここでもう一点、質問なのですが、歳入の使い道はどのように決められていますか。使い道に違いがあるかについて説明を求めました。","respondent":"遠藤財政課長","answer":"どちらかというと、どれだけの収入があって、それの枠の中で歳出をどうするかというところになろうかと思っているところです。それから特定財源ということで、例えば東京都の補助金や国の補助金で一定決まっているようなものと、２種類あるかと考えております。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"それを教えてください。決められていることなので、財源はもうほとんど動かせないと考えてよろしいか尋ねました。","respondent":"遠藤財政課長","answer":"財源はある程度、決められているというところで、当然、継続性を持ってやる部分と、あるいは新規の施策でやるもの、あるいは一定程度、事業がもう必要ないだろうということで、廃止なり見直しなりというところで、様々なケースがあろうかとは考えているところです。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"ですから、あまり今の事業を、決められた事業以外には、今まで長年やってきたことについて動かすということはなかなか難しいのだろうと思います。６６５ページにわたっていますが、職員の方が考えられて進みますが、これはそんなに変えられるのか尋ねました。","respondent":"遠藤財政課長","answer":"７４.８というところで、令和４年度についても２３区で大体１８位になっておりまして、これは低いほどいいという形になっているところです。数字が高いほうが１位という形になりますので、いわゆる区で考えて施策を打つというところでは、余裕があるかと考えているところです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"意見","question":"６６５ページの行政評価シートが決算特別委員会に提出されましたが、さらに必要性と有効性を示し、その事業を評価するものです。これは私は、品川区としては最も大切なことだと思うのですが、この点についてご見解を説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"今回、６６５事業、行わせていただいたのは、そういったところもひっくるめて全てを点検していく。区民対応というところで、必要なところはどこかというところをしっかりと見るというところで、全件行ったです。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"英語教育はどうなのですか。もっと、やはり区民に、子どもたちに、学校に寄り添うという評価が必要ではないのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"６６５事業がありますとおり、各部に検討いただいたところではありますけれども、なかなかアウトカム指標が出せないというようなところもあります。各担当が区民の方、団体の方、意見を聞き取って適切に執行していると考えているところです。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"それはどうするのですか。それでいいのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価につきましては、必要性、有効性、効率性といったものを評価・分析しているものですけれども、当然ながら、区民の方あるいは団体の方、こういったご要望、あるいはこういった部分も含めまして評価シートに掲載させていただいているところです。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど石田しんご委員からもありましたけれども、こんなことをしていたら、本当に仕事ができるのですか。何を区民が求めているのだ。","respondent":"吉岡政策推進担当課長","answer":"まさに委員がおっしゃるとおりで、福祉の増進に向ける、あるいは区民対応を強化する。そういったところに振り向けるために、今やっている事業の効率性を、より高めるというところで、この事務事業評価を行っているところです。","id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、９５ページ・１１９ページのすまいるスクール運営費について、環境改善などについて伺います。区は、国の通知でも流用を認めていると説明しますが、１０％以上流用しているということは問題だと考えていないのか、伺います。","respondent":"石井保育支援課長","answer":"委員ご指摘の１０％が問題かどうかについては、１０％という数字そのものでもって、問題だ、問題でないという議論をするべきことではないと考えています。","id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"区にある保育園に使われないということですので、品川区としてもチェックすることが求められると思います。そして、１０％を超えて本部経費に回すということは保育の質の低下にもつながると考えますが、いかがか尋ねました。","respondent":"石井保育支援課長","answer":"１０％を超えるから直ちに保育の質が低下するということについては考えてございません。その他、様々な経費が保育園にはかかっている現状の中、一概に数字だけでもって評価するのは適当でないと考えています。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"本部からスーパーバイザーが来ているという話もありますけれども、そうしたことも含めて、やはり品川区としてチェックしてほしいと求めました。区の保育園の運営のために出されているという運営費が、他自治体に流れているということになるわけですが、これは問題と考えていないのか伺います。","respondent":"石井保育支援課長","answer":"拠点区分間、サービス区分間、繰入金等の支出に入る部分であると認識しています。もちろんこういった制度については国が考えている部分ですので、必ずしもその１つだけでもって不適当だと申し上げることはできないと考えています。","id":"exchange-141"},{"speaker":"のだて委員","kind":"提案","question":"直ちに問題とは考えていないということですけれども、これは１つの指標として私は提案しておりまして、そうしたところでのチェックというのは、しっかりとされているのかどうかを伺いたいと思いますとの意見を述べました。","respondent":"石井保育支援課長","answer":"こちらは、東京都に提出する際には一度、区を経由する部分がありますので、提出するに当たっては、我々も一度、書類を見ております。その上で、区を経由して各事業者に伝えられているところですので、様々な観点からチェックがなされているものと承知しています。","id":"exchange-142"},{"speaker":"のだて委員","kind":"質問","question":"本来、区内で使われるべき財政が流出しているわけです。区として、こうしたことに問題意識はないということなのか、伺います。","respondent":"石井保育支援課長","answer":"委託費の使途については適正に使われるべきだと思いますし、保育の質の向上のために使われるべきだと思ってあります。しかし、それそのものだけでもって問題だと考えているのではなく、きちんと保育の質の向上のために使うべきだと考えているところです。","id":"exchange-143"},{"speaker":"のだて委員","kind":"質問","question":"あるいは、これが１０％ではなく２０％、３０％の場合、問題だと考えているのか、伺いたいと思います。伺いたいと思います。","respondent":"石井保育支援課長","answer":"区内の保育園のことに関して、まず保育が適正に実施されているかが一番の評価のポイントであると考えています。全て総合的に検討した結果、今、私立保育園の運営については適正になされていると承知しています。","id":"exchange-144"},{"speaker":"のだて委員","kind":"質問","question":"そこは区としてもチェックすることが必要だということと、税金の使い方として、区に来たものが別の自治体で使われる。ほかの自治体のものも品川区に入っているということで、そうした使い方でいいのかということも聞きましたので、伺いたいと思います。","respondent":"石井保育支援課長","answer":"委託費の使途につきましては、適正な保育がされているかどうかをまず観点に置くべきだと考えています。こちらから何も申し上げることはできませんので、まずは適正な保育がなされているかどうか、そこに着目するべきだと考えています。","id":"exchange-145"},{"speaker":"のだて委員","kind":"提案","question":"あまりに低い３割台などの人件費は是正すべきだと考えますが、いかがでしょうか。人件費率について品川区のルールをつくるべきだと提案しますが、いかがか尋ねました。","respondent":"石井保育支援課長","answer":"それを一概に言うことはできませんし、あとは当然、そこというのは、事業者の経営の判断の部分になってくることです。適正な保育が行われているということに着目すべきであり、経営の一つ一つにまで行政が事業者に対して口出しをするものではないと考えています。","id":"exchange-146"},{"speaker":"のだて委員","kind":"質問・要望","question":"豊かな保育を提供していくというためにも必要だということで求めておりますので、ぜひそうした視点で、要望しておきたいと思います。こうした面でも、配慮が必要な子どもたちも過ごしやすい環境整備を求めたいと思いますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"学校との関係性もありますので、個別に各すまいるスクールで、どういった対処ができるかというところは検討してまいりたいと思います。特別な支援が必要な児童など、安心して過ごせるような対応は、今後も児童の皆さんが安心して過ごせるように努めていきたいと考えております。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問","question":"私からは、８８ページ、８９ページにかけて、国庫支出金、生活困窮者自立支援事業と区内私立保育園経費について伺います。委託先の業務の状況についても、区としての評価を伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"家計相談を対応させていただきまして、６名の方に対して３４回、対応させていただいたです。実績は十分あるかと考えておりまして、我々も信頼して今現在、業務を委託しているという状況です。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問","question":"その結果、その方の状況が生活困窮から抜け出したなどというような点についての評価も伺いたいのですけれども、その点についていかがでしょうか。有効性のほうの評価をぜひ伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"６名のうち２名の方は、暮らし・しごと応援センターで引き続き職員が対応していると報告を聞いております。なかなかこちらが支援したくても、手をつなげることができないという点で、曖昧な書き方になってしまっているということをご報告します。","id":"exchange-149"},{"speaker":"吉田委員","kind":"提案","question":"区としての加配を検討すべきと考えますが、見解を伺います。この欄の記載は誰がどのように行っているのか、伺いたいと思いますとの意見を述べました。","respondent":"石井保育支援課長","answer":"今回、委員ご指摘の置き去り事案に係る事故報告書を基にご指摘いただいたものであると認識しています。改善策の実施状況を確認し、新たな課題が発生するようであれば、まず保育支援課の職員でこちらを読ませていただきます。","id":"exchange-150"},{"speaker":"吉田委員","kind":"質問・要望","question":"東京都へ配置を増やすように求めているようにも見えますし、事故報告に記載する、そういうふうに求めていると理解してよろしいでしょうか。その辺を伺いたいと思います。","respondent":"石井保育支援課長","answer":"そういったところで、区が例えば今回の事案について、こちらは保育士をもっと配置したほうがいいのではないか。こういったコメント一つ一つを、東京都が施策に活かしていくというふうなことはあると考えています。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、そのようにこれからも東京都や国に主張してほしいと求めました。効果測定などということのためにも、これは文教委員会に資料として提供されるべき事故報告だと思いますけれども、その点について見解を伺います。","respondent":"石井保育支援課長","answer":"こういった内容ですけれども、まず現場で共有することが一番と考えています。私立保育園長会でも、個人名を抜いた形で共有等を行っているところですし、今後も適切な形で情報共有していきたいと考えています。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"確認","question":"１１２ページ、関連して福祉計画課長や公園課長にもお伺いしますので、よろしくお願いいたします。もう一つ、１０９ページ、民生委員活動経費、１２１ページ、高齢者安否確認事業、町会自治会のお祝い事業等への名簿提供について伺ってまいります。","respondent":"勝亦総務課長","answer":"こちらの補正予算の財源ですけれども、補正予算で一般財源で組んでいるものと認識しております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"確認","question":"１年前の第３回定例会の一般質問で、区内のウクライナ避難民の数を確認したところ、公表は差し控えたい」というご答弁でした。何で品川区は公表しないのか、改めてお伺いしたいと思います。","respondent":"勝亦総務課長","answer":"第一回定例会で過日ご答弁を総務課からさせていただいたととおり、プライバシーやセキュリティー上の問題といったものがあろうかと考えて、公表していないものです。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問","question":"これは、品川区では、令和４年３月２日から日本赤十字社のウクライナ人道危機救援金の受付というのを行っています。どの程度の募金があったのか、これは福祉計画課が窓口のようなので、教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"令和４年３月２日に、まず募金箱を設置いたしまして、その後２か月間、募金箱を設置してございました。募金箱に入っているお金については、この件数にはカウントされておりません。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの自治体はかなり熱心に支援メニューを上げて、どういうことをやっているかというまとめも公表されている自治体です。これは令和４年度に品川区議会と品川区長からロシア大使館に申し入れていると思うのですが、私はこの覚悟が必要だと思うのですが、ご見解を伺います。","respondent":"勝亦総務課長","answer":"支援につきましては、今、区内のご支援いただいている方には定期的にご連絡を取ったり、様々なご要望を受けて細かに対応している状況です。そういった意味では、人数にかかわらず、品川区は熱心にウクライナの避難民の方の支援を続けているところです。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"確認","question":"これは何度も確認して、今年の４月の予算特別委員会では、最終的な調整を行っていますというご答弁をいただきました。その最終的な調整、７か月間たっていますけれども、その７カ月間の最終の調整の結果について説明を求めました。","respondent":"勝亦総務課長","answer":"ご利用のご要望のあった健康センターは、品川・荏原につきましては無料で使えるようにご協力いただきまして、今、無料で９月から使えるということで、お知らせをしています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問","question":"９月２０日付のホームページ、小さなコラムというか、小さなニュースで、そのことが載っていました。どのようにお伝えされているのか説明を求めました。","respondent":"勝亦総務課長","answer":"先ほど申し上げましたとおり、避難されている方には、個別に定期的に連絡を取ってあります。そういった意味では、担当から、メール、ＬＩＮＥ等を使って、お一人お一人に情報を提供しています。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"確認","question":"確認しますけれども、これはもう確実に伝わっているということでよろしいのか尋ねました。","respondent":"勝亦総務課長","answer":"こちらから避難民の方ご個人にお送りしたメール、ＬＩＮＥ等をご確認いただければ伝わっていると考えております。","id":"exchange-159"},{"speaker":"あくつ委員","kind":"質問","question":"７か月間の最終調整の結果、健康センターのほかの施設の名前が出ていない。少し期待していたのですけれども、この点、全庁的にどのような調整をされたのか説明を求めました。","respondent":"勝亦総務課長","answer":"例えば区の施設につきましても、いろいろございまして、避難民の方ご個人で使われることはあまり想定できないような施設も多々あります。健康といった、精神をリフレッシュできるような施設をまずお使いいただこうということで、品川・荏原の健康センターの無料化を進めたもので…","id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問・要望","question":"聞き取りなどされているということでしたけれども、どういった要望があったのか、それでは教えてほしいと求めました。２つお聞きしましたけれども、取りあえず、そのことについてご見解をお願いしたいと思います。","respondent":"勝亦総務課長、高梨公園課長","answer":"区からの支援情報については、先ほど来申し上げていますように、個々人に対して丁寧に定期的にお送りしております。例えば病院の予約や、場合によっては同行してお手伝いをするといった、きめ細かなご支援をしています。 これから、しながわ水族館の事業者とも協議をして、前向きに検討してまいりたいと考えています。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国会議員を３人呼んで、ウクライナの通訳も準備いたしまして、どういうニーズがあるのかということも伺いました。特筆すべきものがあれば後で教えていただきたいのですけれども、そういったところを一歩乗り越えて、再度お伺いいたします。","respondent":"勝亦総務課長","answer":"今、ウクライナの状況、ウクライナに限らず世界では、貧困や戦争といったものに苦しんでいる方がいらっしゃいます。そういった方を、区として精いっぱい支援していくのは非常に大切なことだと考えています。","id":"exchange-162"},{"speaker":"こしば委員","kind":"質問・要望","question":"１６３ページ、７８ページ、１０２ページのスマートウェルネス住宅等推進事業補助金についてお伺いいたします。対象者の年齢や１人当たりの上限額などについて説明を求めました。","respondent":"飛田子育て応援課長","answer":"こちらは平成３０年度からは制度改正を行い、在学応援資金を創設の上、返還免除型で導入しております。金額としては、２,００６万５,０００円となります。","id":"exchange-163"},{"speaker":"こしば委員","kind":"質問","question":"ようやく３０代に入って完済した経験もありますので、滞納者の中には、少額でも払い続けている方もいらっしゃると思います。一方で、事情によって就職に就けず、支払いが滞っている人もいると思いますが、滞納してしまう人に対する品川区のアプローチについて説明を求めました。","respondent":"飛田子育て応援課長","answer":"現在、滞納している方に対しては、職員が直接お電話をしたり、また督促ということでお手紙を送ったりしております。なかなか返還をお願いしても応じない方もいますので、シルバー人材センターにも委託を行っておりまして、各家庭に、お宅に訪問して、注視しています。","id":"exchange-164"},{"speaker":"こしば委員","kind":"質問","question":"一定の収入がなければ、たとえ少額であっても負担感は大きい。先ほどシルバー人材の方が訪問されていると、それも対面ではあると思いますけれども、逆に区役所での対応について教えてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"その方の実情に合わせて、少しまた分割というか、月の額を減らしたりというふうに応じているところです。母子・父子の福祉資金という方法で、就学金よりも優先される貸付資金もありますので、そういうところもご案内したりしておるところです。","id":"exchange-165"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、各種事業参加費負担金について伺います。こちらは、この項目で多くの事業が列挙されておるわけですが、収入未済であった事業がどのような事業なのかをまず説明を求めました。","respondent":"藤村子ども育成課長","answer":"こちらに収入未済で記載されております金額につきましては、全額、すまいるスクールの利用料という形になっております。","id":"exchange-166"},{"speaker":"こしば委員","kind":"質問","question":"それ以降は１８時までで３,４５０円、１９時まで利用される場合は４,２５０円、月額でかかると認識しております。１８時ないし１９時まで利用する方がいらっしゃるのか、全体の登録者のうちどのぐらいの割合でいらっしゃるのかを教えてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"すまいるスクール全体の参加児童数というのが、全児童のうちの５４.８％です。今、Ｂ登録という６時までの登録の方が１,７００人程度、Ｃ登録という７時までの登録の方が１,１００人程度というような概況になっております。","id":"exchange-167"},{"speaker":"こしば委員","kind":"質問","question":"多分、その相関関係までは難しいでしょうか。お答えいただければありがたいのですけれども、相関関係は分かりますか。","respondent":"藤村子ども育成課長","answer":"相関関係です。就業されていない方が保護者というような形になっているというのが、必ずしもそうではないのですが、一般的かというところで考えております。","id":"exchange-168"},{"speaker":"こしば委員","kind":"質問","question":"１８時以降の利用を続けていく中で、負担に感じている保護者もいらっしゃると思います。なかなか支払いが難しいという方もいらっしゃる中で、区の取組について教えてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"３,２５０円、４,２５０円というところで、お支払いが滞ってしまうという場面はどうしても出てきてしまうです。","id":"exchange-169"},{"speaker":"こしば委員","kind":"質問","question":"生活の事情によっては支払いが滞ってしまうという話もありますけれども、これは何も子ども育成課だけではなく、生活福祉課であったり、内部で社会福祉協議会との連携といった情報も知っておく必要があると思いますけれども、そういった連携もされているという認識でよろしいのか尋ねました。","respondent":"藤村子ども育成課長","answer":"先ほども子育て応援課長から答弁がございましたように、仮にそういったお支払いということが難しいというようなお話がございましたら、社会福祉協議会など、別途、融資制度等のご案内というのをしている場面はあろうかと思います。","id":"exchange-170"},{"speaker":"こしば委員","kind":"質問","question":"続きまして、７８ページの区営住宅・区民住宅の使用料について、お伺いいたします。この１７件が債権を手放してしまっているのですが、これはどういった理由で手放しているのか、説明を求めました。","respondent":"竹田住宅課長","answer":"区民住宅の不納欠損のお問合せです。回収が困難だと思われる案件につきまして、債権管理審議会にお諮りし、回収不能とご判断いただいたものを不納欠損としている状況です。","id":"exchange-171"},{"speaker":"こしば委員","kind":"質問","question":"今の答弁ですと、破産や、相続人がいないというケースもあると。でも、中には相続人がいるけれども、相続放棄をするようなケースもあったりはするか尋ねました。","respondent":"竹田住宅課長","answer":"先ほど申し上げましたのは、居住者や連帯保証人の相続人がいないケースを申し上げておりますので、相続人がいるケースにつきましては回収の努力に努めているところです。","id":"exchange-172"},{"speaker":"こしば委員","kind":"質問","question":"そういった督促といいますか請求はされておるのか、また別の所管になってくるのか、その辺を教えていただけますか。","respondent":"竹田住宅課長","answer":"戸籍等を取り寄せまして、相続人等がいるかどうかを判断して請求しております。回収が事実上不可能だと思われる案件については、債権管理審議会にお諮りして不納欠損処理という形になっているものも、数件あります。","id":"exchange-173"},{"speaker":"こしば委員","kind":"質問・要望","question":"そして、あと１分少々、１０２ページのスマートウェルネス住宅等推進事業補助金。収入未済額に計上されておるわけですが、これはなぜそうなってしまったのか、お答えほしいと求めました。","respondent":"中道都市開発課長","answer":"令和４年度に建物の解体を予定しておりましたが、事前の調査によりアスベストが予定以上に多かったことや、繰越しを行いました。その繰越しにおける国の補助金２分の１を、今回、収入未済額と計上しています。","id":"exchange-174"},{"speaker":"こしば委員","kind":"質問","question":"こちらはまた、来年度ということは令和５年度には計上されておるということでよろしいか尋ねました。","respondent":"中道都市開発課長","answer":"令和５年度におきましては、またさらに建物の予算を計上しております。収入未済額につきましては、令和４年度の執行を今年度、今、行っている最中で、収入として入る予定です。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":126869,"voices":407}},{"id":"r05-20231003-4","meetingId":"r05-c-settlement","date":"2023年10月3日","dateIso":"2023-10-03","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件整理しています。","topics":[{"id":"topic-01","title":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、２１１ページ、しながわマラソン大会開催準備経費、１８５ページ、国際友好都市交流事業についてお伺いします。歳入でも質問があり、８月１日に実行委員会が行われたと伺いましたが、コースの検討状況も詳しくお知らせください。","respondent":"三井スポーツ推進課長","answer":"大会運営計画案の検討や、事前広報活動の実施などをしていきまして、コースおよび大会要項を決定していきたいと考えております。３月にはプレ大会等の実施も予定していきたいと考えています。","id":"exchange-001"},{"speaker":"えのした委員","kind":"意見","question":"令和５年３月、しながわシティランに向けたアイデアソンが開催されていたのですが、これは私も参加させていただきました。区のお考えを説明を求めました。","respondent":"三井スポーツ推進課長","answer":"まず、開催準備に向けましては、そちらにご参加いただいた公募区民の方々のご意見は参考にさせていただきたいと考えております。ご参加いただいた方々との今後の関わり方については、何かご協力いただけないかということは、今後探ってまいりたいと考えております。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。ランナーだけでなく、地域住民の方、観客、地域商店街など、各層を巻き込んだしながわシティランの実施を強く要望いたします。","respondent":"勝亦総務課長","answer":"実際、お子様が２５日間、今年も行かれております。英語で現地での交流をしてきたということで、国際感覚の養いですとか、そういった力を育むきっかけになっているのかなと考えています。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"応援に伺いましたが、昨日もパキスタン戦で勝利して予選グループ２位と、準決勝進出を決めました。オークランド市と品川区のホッケー交流で親交を深めるのはいかがか尋ねました。","respondent":"勝亦総務課長、三井スポーツ推進課長","answer":"品川にもオリンピック会場としてホッケー場があります。ホッケーを通じた交流をぜひしてまいりましょうということで、ニュージーランドのホッケー協会からも好感を持って迎えていただいたという状況です。 マラソンの国際交流について、私からお話しますと、マラソンの国際交流については大会のＰＲや、大会を魅力的にする一つの効果的なものかと考えていますので、大会を考えていく上で、今後参考にさせていただければと思います。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"この取組を活かしたモンゴルとのビジネス協定はいかがでしょうか。スタートアップの海外展開支援について、区のお考えを説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいま海外との交流ということでお尋ねがございました。モンゴルとの海外交流というのを進めているところですけれども、こういうことの拡大の可能性があるかということを探っていきたいと考えています。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問","question":"大使館との交流を拡充するのはいかがでしょうか。区のお考えを説明を求めました。","respondent":"勝亦総務課長","answer":"例えば大井どんたくにご出展いただくとか、関係する国のパネル展を庁舎で行うなど、交流を行っているところです。今後も引き続き、交流は拡充していきたいと考えています。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問・要望","question":"今は映像の時代ですから、関係都市の紹介映像とか、大使館の映像とかを分かりやすくパネル展と一緒に展開されるのはいかがでしょうか。既存の国際交流都市と、これまでの形式にとらわれない、さらなる交流強化を要望しますが、新しい取組があれば、区のお考えを説明を求めました。","respondent":"勝亦総務課長","answer":"品川と友好交流、また大使館があって交流しているような国の紹介、それから、品川区との交流につきまして、積極的に、今いただきましたような映像ですとか、様々な手法を検討いたしまして、ＰＲ、お知らせをしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"国を超えた国際交流となると、中学生・高校生になりますが、大使館の交流は小学校で、食を通じた交流ですとか、様々な取組をされていると思います。国際交流都市と、また新しい形の国際交流を強化することを要望して、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、２点お伺いいたします。１９９ページの旧荏原第四中学校管理費、同じく１９９ページの大井第三地域センター移転関連経費について、それぞれお伺いしてまいります。","respondent":"吉岡政策推進担当課長","answer":"跡地活用方針策定委員会をご案内いただきましたけれども、９月１２日に第２回の開催を行いまして、導入機能についてご議論いただいたところです。今後は、跡地活用方針策定委員会で方針案を策定いただくというところで…","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"豊町３丁目・４丁目の地域の方々、ふらっと立ち寄れて、ちょっとしたものやお茶を飲めるような空間があるところにしてほしいとの声を聴いています。地域の人間関係がつながれば、自助・共助にもつながると思われますが、こういったところで何かお考えはありますか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"先ほど施設コンセプトということで、まずは防災というところで、安心安全を支える場というところでご紹介させていただきました。３番目として誰も取りこぼさない支援の場、４つ目といたしまして、委員の方たちからもご意見をいただいたところです。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"２０１６年に品川区で、販売の事業者それぞれの地域連絡調整員の選任や、さらなる地域活性化に努めてほしいと求めました。本年３月の予算特別委員会にて当時の地域振興部長から、大井第三地域センター、区のお考えをお聞きしたいと思います。","respondent":"宮澤地域活動課長","answer":"地域の方々にご利用いただく地域コミュニティの核として、拠点としての地域センターですので、地域への説明というのはしっかりしていく予定です。今後、地域の防災活動等々に活用できるように、地域センターと連携していきたいと考えているところです。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"大井第三地域センターの自助・共助といった観点から、あと、ウェルカムセンター原を活用した取組といったところで、もう少し深く自助・共助といったところでお考えがあれば、お聞きしたいと思います。","respondent":"宮澤地域活動課長","answer":"大井第三地域センターに関わらず、各地域センターでは地域の方々と一緒に総合防災訓練をはじめ、日頃防災訓練というのを行ってあります。防災訓練の町会ごとの訓練等々、何か活用できるかどうかというところは、地域と話し合いながら進めていきたいと考えております。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、１８６ページの人権啓発費の中の人権啓発事業、そして男女共同参画推進事業について、併せて質問します。区として重要施策にこの項目が挙げられた理由、経緯について説明を求めました。","respondent":"加島人権啓発課長","answer":"８４２人から回答があったものですが、公平に接することはできない」と回答された方が、男性で２２.３％ございました。回答数として８４２人ですけれども、区として重点施策として、理解促進・支援を図っていくと考えた次第です。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"多様な性に関する理解の促進と、性的指向、ジェンダーアイデンティティに起因する日常生活上の困難等の解消に向けた施策についてお伺いします。そして区民の方の参加数、もし課題があれば、その点についても説明を求めました。","respondent":"加島人権啓発課長","answer":"ご案内のあったみんなのひろばにつきましては、昨年度は年２回実施いたしまして、今年度は年３回となっております。昨年８月には、杉山文野さんを講師にお招きし、「性の多様性と人権」の講演会を実施いたしました。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"そしてまた、理解を深めたいと考えている区民の方にとっても、参加することにハードルがあるのではないでしょうか。テーマをしっかりと伝えることで、興味のある区民の方々が参加することにつながると思いますが、いかがか尋ねました。","respondent":"加島人権啓発課長","answer":"ご意見を受けまして、対象者の表記には、今年度、まだあと２回予定していますので、工夫を図ってまいりたいと考えております。令和２年度の開始以降、映画とフリートークの内容について実施してまいりましたが、委託先とも協議してまいりたいと考えております。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"どこに相談すればいいか分からない、総合相談とは書かれているが、性的マイノリティの相談に対応してもらえるのか不安があるとの声も聞いています。ＤＶ相談とあり、このカウンセリング相談の窓口で対応してくれるのではないかと思うのですが、この認識でよろしいか尋ねました。","respondent":"加島人権啓発課長","answer":"委員がおっしゃるとおり、男女共同参画センターのカウンセリング相談の一環として、セクシャリティに関する相談を受けているところです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区で対応しているということがすぐに分かるように、ＬＧＢＴＱ相談と明確に明記をしてほしいと求めましたが、いかがでしょうか。その件数、そして相談件数に対し、区としてはどのように捉えているのか説明を求めました。","respondent":"加島人権啓発課長","answer":"職員のほうで苦しいお気持ちに寄り添うような対応をしたところ、そのときは実際には相談の予約には至らなかったということがあります。それから、区の事業をゼロから１００まで存じ上げているわけではないと思いますので、表記に工夫を図っていかなければならないと考えておりま…","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問","question":"東京都のほうに相談が行っているため、品川区自体に相談が来ていないのが現状ではないかと思いますが、そこでお伺いします。東京都の相談窓口に品川区民から相談があった場合、品川区にはどのようにフィードバックされるのでしょうか、説明を求めました。","respondent":"加島人権啓発課長","answer":"ただいまご質問にありましたＴｏｋｙｏ ＬＧＢＴ相談専門電話相談につきましては、東京都総務局人権部が外部委託により実施しているものでございまして、相談内容については、デリケートな内容であることから、区にフィードバックはございません。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そして、みんなのひろばの内容に反映していくべきだと思いますが、いかがでしょうか。区の考えを説明を求めました。","respondent":"加島人権啓発課長","answer":"東京都が令和３年度に当事者等を対象に実施いたしました「東京都性自認及び性的指向に関する調査」というのがございまして、困難な経験として。進めてきたと認識しておりますが、みんなのひろばの実施…","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区では現在、ジェンダー平等の推進に関する検討委員会も作成されて、条例について進めているところだと思います。この条例の中で、もし性的マイノリティ、どのような工夫をしていこうという意見などがありましたら、最後にお聞かせほしいと求めました。","respondent":"加島人権啓発課長","answer":"条例に関する検討委員会におけます性的マイノリティへの支援というところですけれども、計画改定時に落とし込んでまいりますので、これから頭を働かせて考えていかなければならないと考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"１９９ページ、１９１ページ、公契約条例について伺いたいと思います。それと、改善の必要性があると考えているのか、いないのか、伺います。","respondent":"横田情報推進課長","answer":"ＳＨＩＮＡＧＡＷＡ ＦＲＥＥ Ｗｉ－Ｆｉの１回の接続の利用時間が６０分で短いかどうかというお問合せですが、たまに受けております。６０分にしている理由ですが、標的型攻撃の踏み台とされているという理由があることから、警視庁からの要請に従いまして設定しているもので…","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"３時間半、４時間と分かれていますが、整えるべきではないかと思います。どういう意味なのか、区として時間内にオンライン会議ができるような環境を整える何らかの工夫というのはできないのでしょうか、伺いたいと思います。","respondent":"横田情報推進課長","answer":"フリーＷｉ－Ｆｉ自体を委託契約として結んでおりまして、施設ごとの設定時間の変更というのは、技術的にも難しいところです。ポケットＷｉ－Ｆｉ等の貸出しにつきましては、今後検討してまいりたいと思います。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問に入りたいのですが、この間、共産党も含め、議会では何度も公契約条例の制定を求める質問がされてまいりました。実効性のある条例の制定が重要ですが、条例の検討に当たっては、その鍵となる労働報酬下限額を定める考えがあるのかないのか、伺いたいと思います。","respondent":"佐藤経理課長","answer":"今後、課題に対応する実効性のある制度の構築に向けまして、さらに事業者との協議を重ねるなど、制定に向けて引き続き検討を進めていくです。制定している区あるいは自治体があることは認識しておりますので、そういったところも踏まえて検討を進めていきたいと考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"つまり、現場労働者は適正な賃金、労務単価の９割の賃金を受け取っていると答弁しているのです。この労働環境チェックシートの記入ですが、どのように行われているのか伺いたいと思います。","respondent":"佐藤経理課長","answer":"労働環境チェックシートのお尋ねです。労働環境チェックシートにつきましては、要綱を定めて実施しておりまして、予定価格２,０００万円以上の工事請負および委託契約につきまして。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですけれども、なぜ現場の労働者に聞いた調査結果では、他自治体の労働報酬下限額を下回るものはないという結果になるのでしょうか。その原因を、区はどのように分析しているのか、考えているのか、伺いたいと思います。","respondent":"佐藤経理課長","answer":"ご説明いただきましたアンケートにつきましては、必ずしも前提を一にするものではございませんので、必ずしも一致するものではないと考えています。そういった場面を通じまして、引き続き、適正な報告をいただくように努めてまいります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"現場の労働者の皆さんも毎年、適正な賃金が、労務単価に比べてすごく低いという訴えを、全ての会派、議員の人にも訴えているわけです。ですから私は、公契約条例の制定に向けて必要だと思うのですけれども、いかがか尋ねました。","respondent":"佐藤経理課長","answer":"現場の方のご意見ということですけれども、そういったところも含めまして、労働者の方へのアンケートにつきましては、この条例を検討する中で、引き続き研究していきたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"組合の皆さんは頑張っているわけですから、ぜひ区も、労働者に直接聞き取りなどを行っていただきたい。それについてはどのように検討していくのか、お願いいたします。","respondent":"佐藤経理課長","answer":"冒頭申し上げたとおりで、ほかの区の状況などを参考にいたしまして、引き続き検討してまいりたいと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"１８７ページ、２０５ページ、フィルムコミッション事業についてお伺いいたします。私もこれを提案させていただいて、今、本当にしながわシティランをすばらしい大会にしていただきたいと考えておりますとの意見を述べました。","respondent":"三井スポーツ推進課長","answer":"区の広い地域を走るコースも検討しておりましたが、安全性などを考慮して、断念せざるを得ない状況となっております。全く不十分とは考えておりませんので、このコース案を検討しながら、魅力的な大会にしていきたいと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"続いて、総務運営費に関連して、事務事業評価についてお伺いいたしますけれども、今、国民・区民は税金・社会保障費の負担が増えております。無駄削減の決断を行っていただきたいと考えておりますけれども、品川区、区長のご見解があれば伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"そうした状況変化に迅速に対応するために、エビデンスに基づいて、政策・事業を形成することが求められているという状況です。今後も各事業、政策の改善、見直しにつなげる実効性の高い行政評価を進めていきたいと考えているところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"ほかの区では賀詞交歓会に参加するとき、有償、お金を払って参加されているところがあります。ですから、飲食提供ならば有料化をしていっていただきたいと考えておりますけれども、それについてお考えを説明を求めました。","respondent":"勝亦総務課長","answer":"新年賀詞交歓会についてのお問合せです。今後そういった飲食の提供の在り方、また有償・無償の在り方について、しっかり検討して進めてまいりたいと考えています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"確認が取れました。特別職報酬等審議会の審議と議事録の公開を、ぜひ行っていただきたいと考えておりますけれども、いかがお考えか尋ねました。","respondent":"勝亦総務課長","answer":"審議の内容ですとか、そういったものにつきまして、情報公開の重要さは考えてあります。今後、必要なものは公開できるように、検討はしていきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"今後もっとＰＲをしていただき、シティプロモーション、観光の所管課とも連携していっていただきたいと考えております。提案として、音楽のプロモーションビデオ等々にも範囲を広げていっていただきたいと考えておりますが、お考えはいかがか尋ねました。","respondent":"篠田文化観光課長","answer":"フィルムコミッションについてのお尋ねです。実は今年の３月に、しなロケにも掲載しているので、ぜひご覧いただけたらと思います。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"私も確認させていただきたいと考えています。ぜひ今後ともよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１９７ページの地域課題の自主的解決支援、２０１ページの児童見守りシステム運営費について質問します。地域課題の自主的解決支援事業について、主要施策の成果報告書１５ページにあります地域振興事業からお聞きします。","respondent":"宮澤地域活動課長","answer":"町会とマンションとの関係づくりに課題があるという声をお聞きしているところから、マンションの管理組合の実態調査というのを実施しました。町会とマンションの関係づくりを促進するという点からも、コンサルタントを活用した伴走支援というのを現在実施しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"意見","question":"多岐にわたる業務の引継ぎに苦労することが想定されますが、これらにはデジタル活用で効率化できるものもあると考えます。デジタル機器の購入だけでなく、町会・自治会のデジタル活用による業務の効率化を促進していく支援の取組の考えを説明を求めました。","respondent":"宮澤地域活動課長","answer":"先ほども申し上げましたコンサルタントを活用した伴走支援の中でも、町会のデジタル化をテーマに交流会というのも実施したところです。デジタル機器の購入だけではなくて、ＳＮＳ等の活用に関した講習に係る経費等々にも活用ができるというところで支援しています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"意見","question":"個人情報保護制度は大切であると思うのですけれども、一方で、町会のお祝い事業も地域のコミュニティ形成には大切な事業であると考えています。区としてこちらの部分で何か支援できることはないか、お考えを説明を求めました。","respondent":"宮澤地域活動課長","answer":"町会・自治会から、名簿の提供がなくなるところでの対応の困難さというお声はいただいているところです。できることとして、各町会・自治会と密接に日頃から連携しておりますので、できる限りの支援というのは引き続きしていきたいと考えているところです。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"ご意見を伺うことも多くなっておりまして、ノウハウが蓄積されて、現在では児童と保護者から高く評価されるものに成長したことがうかがえます。まもるっち導入に関連する運営費の規模について、この費用がほかの自治体にとって障壁となっているとお考えか尋ねました。","respondent":"河合生活安全担当課長","answer":"品川区も平成１７年から、いろいろ変えたりして蓄積してきたノウハウがあって、ようやく今、ここにあるのかなと認識しております。システム維持管理経費というのが９,９３４万２,４９６円というところで、オペレーターの業務、位置情報を行います。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"１つ目が、文化予算（施設整備費込み）の区総予算比は、０.１％以上ありますでしょうか。２つ目が、文化計画に「社会的包摂」の記述はありますか尋ねました。","respondent":"吉野戸籍住民課長、辻広報広聴課長、勝亦総務課長、篠田文化観光課長","answer":"無戸籍のご質問だと思います。こちらですけれども、無戸籍になりますと、学業とか、児童手当とか、そういったサービスの提供とかが滞ると考えていま… 私からは、シティプロモーションの観点からのお答えをいたします。森澤区長が様々な場面に行かれたことと、その発信力によって… ９月に区長、それから議長が、現地で３日という期間の中でニュージーランドを訪問してまいりました。３０周年の記念交流事業… 私からは、文化活動支援に関してお答えいたします。お答えしますと、親しみ…","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"歳入の続きをお伺いしたいのですけれども、グリーフケアの理解を広めていくことが大切だと考えているのですけれども、区のご見解をお聞かせください。こちらは要望ですが、グリーフケアの観点から、お過ごしいただく時間を丸ごと包み込むような空間づくりを意識していただきますようお願いいたします。","respondent":"勝亦総務課長、吉野戸籍住民課長、崎村人事課長、田口人材育成担当課長","answer":"コロナが明けてまいりましたので、地方創生といったものに資するものについて、積極的に進めてまいりたいと考えています。 それから、おくやみコーナーですけれども、こちらは来年１月より実施を開始する予定でおります。委託先としましては、区民の方… 昨年度の休暇取得の状況ですけれども、昨年度に１０日以上取得した割合が７４.２％と、令和３年度に比べて上昇したところです。 研修についてですが、令和４年度からはコロナ以前の状況に戻っております。令和４年度からは…","id":"exchange-039"},{"speaker":"澤田委員","kind":"質問","question":"２１９ページの斎場運営費についてお伺いいたします。原油料の高騰などにより価格が上昇している中、当初予算内で収まる低い価格の支出となったのはなぜだとお考えか尋ねました。","respondent":"吉野戸籍住民課長","answer":"負担金ですけれども、こちらはその都度、社会情勢等を踏まえて検討しているところでありますので、この価格内で、こういった物価高騰に関しましても勘案してやっている状態です。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"予算に価格高騰分も織り込み済みだったからということか尋ねました。","respondent":"吉野戸籍住民課長","answer":"それぞれの社会情勢等も踏まえて、こちらは検討しているところであります。","id":"exchange-041"},{"speaker":"澤田委員","kind":"意見","question":"遺体安置に１日２万円ほどかかると言われ、火葬までの５日間、葬儀を行ったという事例もありました。臨海斎場における火葬待ちの現状をお知らせくださいとの意見を述べました。","respondent":"吉野戸籍住民課長","answer":"臨海斎場ですけれども、時間さえ選ばなければ、早い時間帯とか遅い時間帯であれば、待たずに利用可能となっております。","id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"これは品川区民にとって大変心強いことだと思うのですが、そこでお伺いします。臨海斎場には、霊安室の保冷庫が２４庫ありますけれども、その稼働率または混雑状況を、お分かりになる範囲で大丈夫ですので、説明を求めました。","respondent":"吉野戸籍住民課長","answer":"保冷庫の稼働状況ですけれども、利用率は令和３年度７９.１％、４年度は８２.４％になります。","id":"exchange-043"},{"speaker":"澤田委員","kind":"質問・要望","question":"今後迎えるであろう多死時代に備え、２０３０年度の開始よりもう少し期間を早めていただきたいというお声も届いております。区としてのご見解を説明を求めました。","respondent":"吉野戸籍住民課長","answer":"臨海部広域斎場組合議会でも、今後の大規模な災害に備えて、令和１２年度を前倒しにできないかという質問が上がりました。組合としましても検討してまいりますという回答がありました。","id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"続きまして、２０５ページ、フィルムコミッション事業についてお伺いいたします。先ほどほかの委員も質問されていましたけれども、フィルムコミッション事業として１,６２３万円が計上されておりますが、内訳等を説明を求めました。","respondent":"篠田文化観光課長","answer":"月２本程度コラムを作成していただいているのですけれども、こちらが２９０万円余、そちらが６７０万円余という形になってあります。そのほか、ロケ地の支援業務等に関しては、職員も対応しています。","id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"さらに、撮影されたシーンなどをホームページで見られるようにするなど、積極的に紹介するのはいかがでしょうか。区の見解を説明を求めました。","respondent":"篠田文化観光課長","answer":"一部しなロケがご協力させていただいて撮ったドラマ等については、そちらに載せるということでご了解いただいて載っているものもあります。それから、リンクを張ることにつきましては、こちらの全体の画面の配置等もありますので、今後検討してまいりたいと思います。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問","question":"１９１ページ、２１９ページ、それぞれ伺ってまいります。どのような番組を放映されているのか、また、区のお知らせ的なところがどのように放映されているのか、説明を求めました。","respondent":"辻広報広聴課長","answer":"イベント等の実施の報告等のニュース、これは毎週更新しておりますので、年間でどちらも５２本ずつです。区役所へ」というものがありまして、こちらは区のサービスのことをご紹介するような番組です。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢者を対象としてサークルを立ち上げて、定期的に会を行っている方々からお話を伺う機会がありました。ですので、区民チャンネルを活用して、申請の仕方を丁寧にそこで流していただくような工夫も、ぜひしてほしいと求めましたが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"高齢者の方は、確かに申請書等を書くのが非常に難しいところもあると思います。いろいろな課題はあると思いますが、うまく組み合わせてできることがあるかということは、研究してまいりたいと思います。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"続いて、庁舎整備費から、授乳施設に関してお伺いいたします。それぞれどのように授乳室がなっているのか、何か所ぐらい設置されているのか、現状を説明を求めました。","respondent":"佐藤経理課長、小林施設整備課長","answer":"私からは、総合庁舎における授乳室についてご答弁申し上げます。本庁舎の３階・７階にありまして、今ほど委員からご指摘のありました防犯対策というところでは、内側から鍵がかかるような形になってあります。 従来はなかなか設置されていなかったところではありますが、現在につきましては、必要な施設に応じて設置を進めているところです。従来は施設の機能に応じて設置をしてきておりますが、今後整備していく施設につきましては…","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"必要なところには全て整えていただきたいということも要望させてほしいと求めましたので、どうぞよろしくお願いいたします。どなたでも安心して投票ができるように、そういう体制を整えてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"２３区では４区ほど実施している区もあるのですが、支援の必要な方が、筆談の道具を用意しております。その紙にどう対応するかということで混乱が生じる可能性もありますので、よりよい支援ができるような方法を検討したいと考えております。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、２１９ページ、斎場運営費についてお聞きします。臨海斎場が２０３０年に施設の拡大予定ということですが、どれぐらいの受入れが増えるのでしょうか、説明を求めました。","respondent":"吉野戸籍住民課長","answer":"こちらですけれども、臨海斎場には今、火葬場が１０基あるのですけれども、こちらを６基増やしまして、１６基に拡大する予定でおります。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"臨海斎場と同じように、こちらの桐ヶ谷斎場も品川区で買い上げるお考えはないのでしょうか。こちらの桐ヶ谷のほうも運営していくという予定はございませんか尋ねました。","respondent":"吉野戸籍住民課長","answer":"公営の火葬場の建設については、今のところ計画はありません。ただ、臨海斎場に関しましては、先ほどお伝えしたとおり、火葬場の増設等を計画しておりますので、こちらで需要は満たされると考えております。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区民の安定した生活環境を整えるために、様々な角度から問題解決に向けて、今後も取り組んでいってほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"山本委員","kind":"質問","question":"私からは、１７７ページの広報経費、２１１ページの地域スポーツ支援について伺います。１７７ページの広報経費について伺います。","respondent":"辻広報広聴課長","answer":"こちらの閲覧数は、月にして令和４年度の閲覧者数が３３万人、総アクセス数が月にして１０９万８,０００回です。ＬＩＮＥが３万４,０００、こちらのユーザーが月平均で４,９００人、ダウンロード数で言いますと２万３,０００件程度あると認識しております。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問","question":"ご答弁ありがとうあります。この利用状況について区ではどのようにお考えでしょうか、お考えを聞かせください。","respondent":"辻広報広聴課長","answer":"これは令和２年度の末に開始したのですが、こちらは３万４,０００ということで、情報を流すのには非常に有益なものかなと思っています。課題として考えておりますのは、より伝わりやすいホームページになるかなというふうには、課題としては感じております。","id":"exchange-055"},{"speaker":"山本委員","kind":"提案","question":"スマートフォンの世帯普及率は約９割と言われ、重点的に展開することが有効であるのではないかと考えますが、いかがでしょうか。以上、品川区の総合的な情報発信に関する独自のアプリの開発についてご提案させていただきましたが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"ホームページは今、一応スマホ対応の画面などもありますが、どういった形が一番皆様に届くか。伝えるのではなくて伝わる形をどうやったら取れるのかというのは、区民の皆様の意見もお伺いしながら、今後いろいろ考えていきたいと思います。","id":"exchange-056"},{"speaker":"山本委員","kind":"質問・要望","question":"区民の皆様の利便性向上や満足度を考えたときに、これは大事な課題でもあると思いますので、ぜひとも前向きなご検討をお願いいたします。地域スポーツ支援についてお聞きしたいと思いますが、要望としては、こういった支援について要望させていただきたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１８７ページのＤＶ・カウンセリング相談です。そういうことで、ＤＶ・カウンセリング相談、ＤＶ全般で区が取り組まれている取組を説明を求めました。","respondent":"加島人権啓発課長","answer":"ＤＶに関して区の取組ですが、まず、ＤＶ相談、男女共同参画センターで実施しております相談窓口の設置、それから、男女共同参画推進講座の中で今年度、デートＤＶ、それからＤＶに関する講座を開催いたしました。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ＤＶ相談という中で、品川区のホームページ、男女共同参画のところに「女性相談員による総合相談」というのがあると思います。この専門の相談員というのはどういった方が対応しているのか、ここ数年の推移なども、分かりましたら説明を求めました。","respondent":"加島人権啓発課長","answer":"令和４年度分ですけれども、ＤＶ相談につきましては５５件です。令和３年度につきましては６０件、それから、令和２年度につきましては５６件、遡ってで恐縮ですが、そのような推移となっております。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"要は１か月間でキャパシティーが、１２人しか今相談ができないという状況になっていて、この辺の区の受け止めはいかがでしょうか。拡充するとか、そういったことはお考えでしょうか、お願いします。","respondent":"加島人権啓発課長","answer":"ＤＶ相談は確かに、今ご案内いただいたとおり、日中が月３回、夜間が月１回という実施の状況になってあります。私どもといたしましては、今ある回数をきちんと１００％近くに稼働させていく、相談を周知していくということが課題だと考えております。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では、この平日の時間帯と夜間の時間帯での稼働率の内訳というのはいかがか尋ねました。","respondent":"加島人権啓発課長","answer":"大変申し訳ございませんが、手元の資料では時間別の内訳はございません。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"できればそこをしっかりと把握していただいて、もし夜間のほうに偏っているのであれば、ぜひ対策というか、拡充をしてほしいと求めました。よろしいか尋ねました。","respondent":"加島人権啓発課長","answer":"ご要望はお受けいたしましたので、この後、課で統計を取り直してまいります。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"よろしくお願いします。加害者に対しての更生のプログラムなどがこれから求められるのではないかと思うのですが、そういった対応というか検討はされていますか尋ねました。","respondent":"加島人権啓発課長","answer":"委員からございましたような専門的知識、対応を伴うプログラムの重要性については、認識はしております。区で実施するに当たって、現状につきましては、東京都ウィメンズプラザの支援につなげているところです。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ただ、やはりこういうプログラムというのは、１回当たり大体安くて３,０００円、高いと１万円ぐらいのお金がかかると。ちなみにＤＶ被害者の方たちの支援活動を行っている団体への支援、補助金などというのは、区ではどの程度行っていますか尋ねました。","respondent":"加島人権啓発課長","answer":"支援団体への補助金というお問合せですけれども、こちらについては区で現在補助制度はございません。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ積極的に取り組んでほしいと求めました。アクションプランも策定していますので、そういった取組もぜひ参考にしていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"まつざわ委員","kind":"確認","question":"ホームページを拝見しますと、現段階におきまして、品川区ではＺＥＢ認証を５施設、ＺＥＨ認証を１施設で取得していると確認が取れました。施設の運営から１年以上が経過しており、令和４年度１年間を振り返りまして、お示しください。","respondent":"小林施設整備課長","answer":"令和４年度の実績ですが、屋上に多くの太陽光発電が設置されておりまして、設計時の９１％を大きく上回る９７％の削減につながっているところです。運用につきましては様々試行錯誤した部分ではありましたが、一定の成果があったものと認識しております。","id":"exchange-066"},{"speaker":"まつざわ委員","kind":"確認","question":"大幅なエネルギー削減の計画を立て、実行し、確認しながら改善していく。見えない部分でご苦労があると思いますが、快適性と省エネを両立させるための工夫、それに対してどのようにしていたのか、お示しください。","respondent":"小林施設整備課長","answer":"人が活動するエリア、大体床から２メートル辺りになるかと思いますが、例えば省エネに配慮しつつも利用者の快適性が担保される工夫をしています。この施設につきましては、測定等を行うことによりまして…","id":"exchange-067"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"公共施設を多数持つ都市部の自治体の特性から、強力なシティプロモーションの一つとして、強みになるのではないでしょうか。そこで、来年度に向けての取得について、また他自治体から民間事業所への波及、広がりについての考えをお示しください。","respondent":"小林施設整備課長","answer":"既存施設のＺＥＢ化も非常に重要な取組だと認識しているところでございまして、様々な角度から検討を重ねていきたい。理解に努めていく、普及につなげていく、そのようなことを引き続きやってまいりたいと考えているところです。","id":"exchange-068"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"課長がお話のとおり、今までの知見といったものが大きく活用される大切な１年です。管理職におきましても適性などを踏まえた新たな人事制度、こういったものの検討などを期待、そして要望しまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問","question":"１８７ページ、ＤＶ・カウンセリング相談、２０１ページ生活安全推進事業、２１４ページ、戸籍及び住民基本台帳費について伺います。男性相談の視点でありますけれども、これは先ほど来質疑がありますけれども、男性相談についての相談実績をまず説明を求めました。","respondent":"加島人権啓発課長","answer":"最後に、令和２年度分につきまして、こちらは合わせて２６１件のご相談がございました。そのうち３５件が男性の方からの相談で、こちらは割合といたしましては１３％となっております。","id":"exchange-070"},{"speaker":"つる委員","kind":"確認","question":"先日の報道で確認させていただきましたが、日常、被抑圧性に苦しむ人がいるというところであります。例えば２３区で見ても、窓口対応としての男性相談、こうした視点についての今のお考えを説明を求めました。","respondent":"加島人権啓発課長","answer":"実際そのような方とお話ししたこともありますが、そのような理由から、今、ＤＶ相談については、女性のみとさせていただいているところです。少し男性の男らしさについてご発言がございましたが、区のほうで今後…","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"これはもう要望ベースでありますが、答弁では１,２８０台とご答弁いただいているのですが、令和４年度まで含むと１,４５６台になると思うのです。それから目標については、行政評価シートを確認すると、令和１１年までのあと７年間で年度１００台ずつ増やしていく。","respondent":"河合生活安全担当課長","answer":"実際残っているかどうかの確認を、これから町会のほうにいま一度確認して、正確な台数を把握したいと考えています。どのぐらいの要望があるかというところは注視しながら、やはり調査研究しながら、その必要性等は判断していきたいと考えております。","id":"exchange-072"},{"speaker":"つる委員","kind":"提案","question":"ここについては他区の事例もありますので、個人宅向けの防犯カメラの設置助成については、大きい部分で検討してほしいと求めました。この臨海斎場を一部事務組合でやったらどうだということを提案させていただいて、非常に感慨深く質疑を確認させていただいたところでありますがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは２０１ページ、歩行喫煙防止、１９５ページから１９７ページの地域振興経費、２０９ページの歴史館についてお伺いします。大枠で大体どのくらい、件数は分からなくてもいいのですが、大体どのくらいあるか、もし把握をしていたら説明を求めました。","respondent":"河合生活安全担当課長、宮澤地域活動課長、篠田文化観光課長","answer":"特に指定地区５地区の中でも、紙たばこの煙の苦情が多いところにはコンテナ化を進めているところです。そういった個別具体的な対策を… 一緒にできることというのも非常に多々あると思います。町会がどういった形で地域のコミュニティを発展させていけるかというところで… １０万円以上になると備品登録をする形になりますので、美術品ですとかそういうのを全部ひっくるめて、歴史館全部のものという形になってしまう。…","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どういうふうに社会が形成されていくのか、なぜ町会が必要なのか、こういったことを改めて考えてやっていかなければいけない。バーチャルの空間も活用して、どんどん品川区が持っている財産を皆さんに紹介していただきたいなと思いますが、その辺もお知らせください。","respondent":"河合生活安全担当課長、宮澤地域活動課長、篠田文化観光課長","answer":"加熱式たばこと紙たばこの対策ですが、マナーについては公平にやっていきたいと考えています。喫煙所につきましては、やはりニーズに、比率に沿って… 転入者へのご案内というところでは、それぞれの地域センターでそれぞれの地区ごとのパンフレットというのをお渡しして、工夫をしています。… 今後、様々検討してまいりたいと思います。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１８３ページの非核平和都市品川宣言について、２１８ページの選挙費に関わって、投票権、参政権の保障を求めて質問します。そこで伺いたいのですけれども、この品川の宣言、ここには何と書いてあるのか伺います。","respondent":"勝亦総務課長","answer":"すみません、全文を読むわけに、手元にはあれなのですけれども、非核平和の核兵器の廃絶、それから恒久平和の確立に向けたということをうたっているものです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"核兵器廃絶と恒久平和の確立ということで説明されました。その中で、やはりそれに向けて、持てる国は即時に核兵器を捨てよと書いてあると思うのですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"おっしゃるとおり、そのように記載されております。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"そのとおりに書いてあるということですね、やはりそこを見ると、この品川区の非核平和都市宣言は、核抑止論、これは、核兵器をいざとなったら使うぞということで相手を恐怖で抑え込むというものですけれども、この抑止論を否定していると思いますが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"記載のとおり、核兵器を捨てよというふうに訴えているものと考えています。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"核兵器を捨てよと書いてあるということは、この核抑止論、核兵器を持って脅すということを否定していると思いますが、改めて伺います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言につきましては、非核平和都市品川ということで、核兵器の抑止について記載しているものではないと考えております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"抑止については書いていないということですけれども、核抑止と核兵器廃絶、恒久平和の確立ということを訴えているわけですね、品川宣言では。区の宣言は、即時に核兵器を捨てよという立場で区としても書いてあるのですから、改めてその姿勢を伺いたいと思います。","respondent":"勝亦総務課長","answer":"「持てる国は、即時に核兵器を捨てよと」、そのように記載していると認識しております。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"なぜ品川区の宣言が核抑止論を否定しているということを表明できないのか。こうしたことを表明していくことが、さらに核兵器廃絶、また恒久平和の確立への強い発信になると考えていないのか、伺います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言によりまして、区が自治体として、平和に対する思い、そういったものを区民に着実に伝えていくということが、区の務めであると考えています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は、今もこの宣言と同じ認識であるということでよいのでしょうか。確認させてほしいと求めました。","respondent":"勝亦総務課長","answer":"これは、歴史の恐るべき証明である」、このように記載されております。こういった、こういったものを区民の方にしっかり伝えて、恒久平和の確立に向けた取組をしていくというのが区の役割だと考えております。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で、Ｇ７広島サミットを目前にということで公開書簡を出しておりまして、核軍縮および近代化の中止を要請するということで書いてあります。さらに核兵器廃絶への発信、平和首長会議とともに核抑止論を否定して核廃絶へと歩んでいただきたいと思うのですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"憲法の趣旨を踏まえたこの非核平和都市品川宣言の訴えを、非核平和、恒久平和を訴えていく、区民の方にお伝えしていくのが、品川区の自治体としての役目だと考えています。","id":"exchange-083"},{"speaker":"のだて委員","kind":"提案","question":"少し提案をしたいと思うのですけれども、核兵器廃絶を求める非核宣言自治体協議会というのがありまして、ここにぜひ参加をしていただきたい。既に２３区の中でも、品川区としても加盟してほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"核兵器廃絶、恒久平和の確立に向けましては、区民の方にこういった非核平和都市品川宣言を踏まえたお伝えをしていく、それを踏まえた今までの事業をしっかり展開していく、そういったものを品川区は今後やっていきたいと考えております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"核抑止論では駄目なのだと、核廃絶こそ必要なのだということで発信をしていっていただきたいと、これは強く要望しておきたいと思います。何人の方が実際に投票されているのでしょうか、伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"そのうち病院が１６、特養ホームを含む老人ホームが２０、それから、障害者施設が１という内訳になっております。この４月に行われました区議選において指定施設での投票については、４１１名の方から請求があり、利用していただいているところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"老人施設の中には、認知症グループホームなども入っているのでしょうか、伺いたいと思います。障害者施設１か所ということで、１か所というのはなかなか少ないと思うのですけれども、なぜなのか伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから５０床以上のベッドがある老人ホーム、身体障害者支援施設、精神障害者の施設は対象になっていないというのがあります。それから施設の構造上、要件を満たすところが少ないということもありまして、都の審査まで行っていないという現状があるのが一面だと考えております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"いろいろな要件がある中で、障害者施設は様々、その要件に入っていないということだと思います。いかがでしょうかということと、具体的にはどうすればこの仕組みを使って投票できるのか、伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"いろいろな支援が必要な方の投票に関しましては、できる限り支援策を講じて、努めているところです。それから、近くの地域センターの期日前投票所などを合わせまして、その中でできる限り投票の権利の確保というのに取り組んでいるところです。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"入所されている方の不在者投票のやり方、ぜひそれを区からも働きかけていただいて、病院などからも有権者の人に働きかけてほしいと求めました。郵便投票、予算特別委員会で聞いたときには、年１回言う機会があるということで言われたのですが、その状況を伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから区の選挙管理委員会から、説明会や関連の機会を通じまして、呼びかけは行っているところです。それと、施設のほうで、やはり先ほど申し上げた人的なもの等の制約があるということは聞いております。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"１９４ページ、地域活動費の中の町会活動支援につきまして、先ほどせらく委員も取り上げられた観点からお伺いしたいと思います。以前は品川区が条例で管理していたものが、何ゆえ情報提供ができなくなったのかというのを、より具体的にご説明ほしいと求めました。","respondent":"宮澤地域活動課長","answer":"それが、この４月の法律の改正に伴いまして、条例の個人情報保護の部分に関しては削除されまして、法律の下の運用になりました。その中で、そういったところに関しては、個人情報保護法の運用の下では提供ができないということになっております。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"探った結果、どのような状況になっているのか、お聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"個人情報保護法の改正に伴いまして様々確認していますが、やはり先ほどの答弁のとおり、個人情報の取扱いのガイドラインにのっとっても、目的外で本人の同意なく提供するということは、困難という結論です。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"この目的にも、両者のバランスを取るべきだということを目的とすると規定されているように、特に町会の皆様とは私は必要だと考えています。そういう観点、この目的に照らした中で、やはり国によるガイドラインによって一切提供できないというご判断なのか尋ねました。","respondent":"宮澤地域活動課長","answer":"町会・自治会が行っていますお祝い事業というのは、やはり地域のコミュニティ発展に大変有意義な事業だとは認識しております。今後、条例ではなく法律の下ということになりますと、国の示す指針に基づいて行っていくです。","id":"exchange-091"},{"speaker":"田中委員","kind":"意見","question":"私はこの法に対してはしっかり対応できるのではないかと、素人ながらの解釈をしておりますが、そこはいかがでございましょうかとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"区としてもお祝い事業というのは実施しているところではありますけれども、やはり目的外の提供になってしまうところです。何で情報を知っているのですかということでの苦情もあったというところで、個人情報の保護の運用に関しては、重要かつ慎重に行うべきかです。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"では、どういうふうに解釈したら対応できるのかという観点も含めて、ぜひ取り組んでいただきたいと存じます。積極的に有効活用する視点でぜひ取り組んでほしいと求めましたが、すみません、残り数秒でお願いします。","respondent":"宮澤地域活動課長","answer":"名簿の提供というところに関しましては、これまでは同意がないところですが、ご本人の同意があるものは提供しているというものです。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２０１ページ、地域支え愛活動経費、同ページで生活安全活動費、２２１ページ、公報関係費、この３点からお伺いしたいと思います。区内の被害件数や認知件数、被害総額、また被害件数のうち自動通話録音機が未設置の件数などが分かれば、それぞれお答えください。","respondent":"河合生活安全担当課長","answer":"特殊詐欺は、品川区では合計３７件の認知となっております。やはりアポ電は９割が固定電話になっておりますので、自動通話録音機の設置促進というのは今後また引き続きやっていきたいと考えております。","id":"exchange-094"},{"speaker":"こんの委員","kind":"意見","question":"その白いアップルカードは詐欺事件の手口なのだよと電話口で大きく叫んでくれて、それで、その場で１１０番をしてくれたそうなのです。こうしたことも対策を考えていく必要が今後あるのではないかと考えていますが、こうしたことについての区のご見解を説明を求めました。","respondent":"河合生活安全担当課長","answer":"区といたしましては、この手口の周知活動、今回１０月１日付の広報しながわでも、最近の多い手口というところで、こちらは紹介しています。私も警察等と連携して、調整といいますか、いろいろ状況は確認しています。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"発行に当たって、候補者の掲載文や写真、レイアウトや規格など、掲載方法に規定はあるのでしょうか。この意味するところ、どのようなことを想定された条文なのか、その辺を確認させてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"これは１７１条までに６条にわたって選挙公報の規定が公職選挙法でされているのですが、それから都道府県の首長の選挙についてのみになっております。この１７２条は、それから区市町村に関しては…","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"文字のサイズ、漢字にルビをつける、候補者の訴えが伝わりやすく分かりやすいものにという要望の声が聞こえてまいります。そのことにぜひ協力をお願いしたいと呼びかけて、そして協力を求め、こうした広報誌を作られたそうです。","respondent":"鈴木選挙管理委員会事務局長","answer":"各候補者の公平性の担保というところで、選挙管理委員会として対応できることは、現実的にはないのかなです。そのような中で、ご指摘にあった多くの方の選挙権の行使の確保というのは、進めていきたいと考えております。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後、品川区の障害者団体が制作を検討する際には、ぜひ選挙管理委員会としても連携する、何か協力できることがあったらお願いしたい。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"提案","question":"１７３ページ、本当に生きがいを感じながら政策をしっかり提案していただいて、大変期待しております。こういう形の政策の提案というのは、どう今の現状を捉えているか、教えてほしいとの意見を述べました。","respondent":"佐藤企画課長","answer":"１点目は、所管のほうで日々現場の対応、窓口で区民の方だったり支援している事業者の声を聞いて、それを政策に反映する。人員を１名増やしていただきまして、大規模用地の検討もしておりますし、政策の検討も進めているところです。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"提案","question":"そうすると、庶務担当課長の部分で、今はとてもではないが庶務担当課長のレベルで政策を提案できる状況には、私はないと思っています。横串を刺してそれを専門的にやっていく方をもっと増やす、この２通りかなとも思うのだけれども、この辺のところの考え方を教えていただきたいとの意見を述べました。","respondent":"崎村人事課長、久保田企画部長","answer":"職員を増やして対応といったところのお話をいただいたかと思いますが、新しい事業になかなか取り組む余裕がないという声もいただいているところです。体制を強化していこうということを考えているところですので、そういった体制強化… 先ほど企画課長も言いましたけれども、人を増員してもらったということも踏まえながら、広く政策提案ができるような土台を今つくっているところです。…","id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"提案","question":"こういうところを、せっかく組織改正もされるのであれば、区長がやはりそれを言っていかないと、多分これ、できないですよ。１００の事業もいろいろどんどんやられて、いろいろな提案をしてくるにしても、少しだけお話があればありがたいですとの意見を述べました。","respondent":"森澤区長","answer":"時代に合わせてしっかりと施策をアップデートして、区民の幸せに向けた体制を職員と共に、一緒につくっていきたいと考えています。そして、若い職員から様々な気づきを得た提案も出てきておりますので、そういったものもしっかり形にしていきたいと考えています。","id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"提案","question":"１点だけ最後、せっかくいろいろな提案がある、例えば企画でもいいです。先ほど言ったいろいろなところで、一回計画を作成してほしいと思うとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"こしば委員","kind":"確認","question":"外国人学校に通う児童・生徒は４％、それ以外は就学が確認できていない、ないしは就学していないとの調査が出ています。前提としまして、今、品川区に住んでいらっしゃる外国人の児童、就学児童は大体どのぐらいいらっしゃるのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"すみません、この件ですが、本来であれば、戸籍住民課では外国人の就学数は把握していない、全体の数しか把握していないところなのですが、学務課に問い合わせたところ、小学生が３００人ほど、中学生が８０人ほどと聞いております。","id":"exchange-103"},{"speaker":"こしば委員","kind":"確認","question":"区内に住民票があれば、日本国籍の有無を問わず所得限度額未満であれば児童手当がつくのは、所管には確認済みです。内容、３か国の外国人学校に通われている国籍の数、あと目的について教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"昭和５０年代にこういった支援をしてほしいということで請願がございまして、議会で全会一致で採択された後、制度として運用を図っているものです。目的につきましては、授業料の一部を補助いたしまして…","id":"exchange-104"},{"speaker":"こしば委員","kind":"質問","question":"それぞれの国の内訳、その３か国の中で、中国が何人など、その具体的な内訳を説明を求めました。","respondent":"勝亦総務課長","answer":"内訳です。先ほど申し上げました北朝鮮が２２、中国が１０、韓国が６という内訳になってあります。","id":"exchange-105"},{"speaker":"こしば委員","kind":"質問","question":"こちらでどうこう言うことはできませんが、疑問が残ることが、課長の答弁を聞いてはっきりといたしました。質問させていただいたときに、何を根拠にして負担の軽減のために補助金を出しているのか、教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"こちらの目的といたしましては、保護者の教育費についての負担を軽減するということを目的にしておりまして、そういった文書や歴史的な経緯も踏まえて、行っているものと考えています。","id":"exchange-106"},{"speaker":"こしば委員","kind":"質問","question":"保護者の負担ということですけれども、であれば、ほかの外国人学校に通う外国人の児童・生徒の保護者にも、品川区は補助金を出せるという理屈にもつながってくると思うのですけれども、では、そういった方向性があるのかどうかも含めて、教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"こちらにつきましては、昭和５５年の話ではありますけれども、議会で全会一致で採択しているということを鑑みて実施しています。必要に応じてご支援をしていくという考え方はありますので、今後、必要があれば検討していきたいと考えております。","id":"exchange-107"},{"speaker":"こしば委員","kind":"質問・要望","question":"韓国も最近、コンビニに置かれていますコーヒーだとか清涼飲料水は、もう既に日本の物価の約２倍ぐらいの値段で販売されておりました。一度ここで立ち止まって、ぜひ見詰めてほしいと求めましたが、区の見解を説明を求めました。","respondent":"勝亦総務課長","answer":"こういった、今、区の就学援助等につきましても、所得の制限を設けて実施しているところがあります。今、ご意見をいただきましたので、そういったご意見、いろいろな意見を踏まえながら、検討、研究をしていきたいと考えています。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、１８７ページ、ウクライナ避難民生活支援経費について伺います。今しました質問とはまた変わりまして、遠い日本に避難を余儀なくされたウクライナの人々ではないか尋ねました。","respondent":"勝亦総務課長","answer":"国際友好協会で、日本でお住まいになられるに当たりまして、日本語教室を無料でご受講できるように対応しています。そちらがなかなか継続していただけないようですので、区でも携帯翻訳機等を準備して提供していきたいと考えています。","id":"exchange-109"},{"speaker":"こしば委員","kind":"質問","question":"携帯翻訳機等の貸出しもされているですが、そういった支援があって、その後、なかなかコンタクトが取れない、そういった事情も出てくるかもしれませんが、そのあたりのサポートについて教えてほしいと求めました。","respondent":"勝亦総務課長","answer":"なかなか言葉の問題を含めまして、まず、昨日のお問合せの答弁とかぶりますけれども、お一人お一人と定期的に連絡を取り合いながら、ご要望を伺いながら、必要な支援におつなぎしているという形でご支援をしている状況です。","id":"exchange-110"},{"speaker":"こしば委員","kind":"質問","question":"品川区民の方々の中には、個人ベースですが、支援の意思を示している方もいらっしゃる。そして、最後は祖国のウクライナの地を踏めるような環境をつくっていただきますようお願い申し上げまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問","question":"私からは１７７ページ、上から９行目、広報紙発行経費からお聞きいたします。この決算の内容を一応説明を求めました。","respondent":"辻広報広聴課長","answer":"広報発行は年間で３８回、うち３回は臨時号で発行しております。その下、外国語広報は、８月を除く月１回、英語版広報誌を発行しておりまして、その経費です。","id":"exchange-112"},{"speaker":"木村委員","kind":"質問","question":"ということは月に４回ぐらい発行して、１週間に１回ぐらいの計算になりますけれども、こういう計算でよろしいでしょうか。新聞の折り込みの実績などがあれば、これが今どのようになっているのか、それも説明を求めました。","respondent":"辻広報広聴課長","answer":"広報しながわの発行ですが、毎月、１日、１１日、２１日号となっていまして、それ以外に特集号を組んです。それから、折り込み経費ですが、今年度は、部数としては８万４,０００部を折り込みしています。","id":"exchange-113"},{"speaker":"木村委員","kind":"意見","question":"新聞を取っていない区民は、広報しながわをどのように手に入れているのか。今、広報スタンドというものが区内には６１か所ありますけれども、具体的に説明を求めました。","respondent":"辻広報広聴課長","answer":"こちらは駅ですとか、あとはコンビニエンスストアですとか、区内に設置しています。もう一つは、新聞未購読者の方で区内在住の希望者の方には、個別に配送しています。","id":"exchange-114"},{"speaker":"木村委員","kind":"意見","question":"そして、外国語広報というのもありますけれども、これが１１回とありますけれども、これはスタンドなのか、それとも自宅配布なのか、これはどのように手に入れるのか、外国の方々に対してどのようにこれを知らせているのか、説明を求めました。","respondent":"辻広報広聴課長","answer":"外国版の広報ですが、外国の英字紙などに折り込みをしています。","id":"exchange-115"},{"speaker":"木村委員","kind":"質問・要望","question":"今ご答弁いただいた広報紙の個別配送もいろいろありますけれども、新聞を取っていない方、外出が困難な方などには非常に助かる制度だと思っています。この周知はどのように行っているのか、また今後の見込みなどがありましたら、お聞かせほしいと求めました。","respondent":"辻広報広聴課長","answer":"足が元気な方でしたら、お散歩がてら外に行って、広報スタンドで取っていただくということも可能かと思います。そのような形で周知をしていきたいと考えています。","id":"exchange-116"},{"speaker":"木村委員","kind":"質問","question":"１人でも多くの区民の皆さんに、足に対していろいろ障害が出てきた人たちのためにも、ぜひともそういう点についてもお願いしたいと思います。次に、１９７ページの地域振興経費から、町会・自治会新規事業定着化補助、および児童参加地域事業補助についてお伺いいたします。","respondent":"宮澤地域活動課長","answer":"町会・自治会が新たに立ち上げた事業の実施経費を補助するもので、新たな取組を支援するというところで、令和２年度に４件。主な活動内容ですが、コロナ禍においては密にならないように、ウォークラリーや防災イベントというのを工夫して実施していると伺っております。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問・要望","question":"いろいろと大変な時期でありますけれども、頑張ってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"第２回定例会での私の質問に対して、それを少し明確に教えていただきたいと思いまして、再度お聞きしたいと思います。区長にとってどういうふうに具現化していくのかということを、長期というお考えがあるかと思いますので、そのお考えをまず説明を求めました。","respondent":"佐藤企画課長","answer":"私からまずは答弁します。大きな視点で考えておりまして、多くの区民の方が幸せに、それができる社会状況を構築していくという意味で使っていると理解しております。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"それを聞いているのではありません。区政運営に関してどういう方向性を持って、自分らしさを実現するのですかということを聞いているので、答弁をお願いします。","respondent":"森澤区長","answer":"ただいま企画課長からお答えさせていただいたとおりだと考えています。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"きちんと区長の思いを私たちに伝えて、それで、どうですかというのを私たちに問うべきだと思うのです。だけど、今回は新しい手法を使っての人事でありますから、それはきちんと議会で説明するべきだと思うのですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"今委員がおっしゃいましたけれども、従来と同じ形で任命同意は出しています。ちなみに要件としましては、品川区に在住いただいている方で、地域でご活動いただいている方です。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"いいですか。おかしくないか尋ねました。","respondent":"桑村副区長","answer":"どのような説明をしていけばいいかということだと思います。基本の形は議会運営委員会で議会にご説明をしているわけですけれども、今までは会派を回らせていただいたり、あるいは各個人の方にご説明申し上げる。","id":"exchange-122"},{"speaker":"西本委員","kind":"提案","question":"なのに、なぜ今回、常設としていじめ問題調査委員会を区長部局がつくらなければいけないのですか。何のためにつくるのか尋ねました。","respondent":"勝亦総務課長","answer":"いじめ防止対策推進法の第２８条に基づきますいじめの調査委員会の結果の報告が出てあります。教育委員会、ご提言をいただいた中で、区長部局にこの組織を設置するものです。","id":"exchange-123"},{"speaker":"西本委員","kind":"意見","question":"時間がなくなったので、もっと突っ込みたいのですが、これは教育費のほうでしますが、役割分担がまず分からない。何をどうするか分かりませんので、これは教育費のほうでしっかりとやらせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"法務局がプロバイダー等に対して人権侵害情報の削除を求める要請を行った件数が、これはまた課長のご見解があると思いますけれども、私も昔一度。人権尊重都市品川宣言３０周年ですか、たくさんお尋ねしましたが、。","respondent":"加島人権啓発課長","answer":"今、実施している他区ですとか、ご指摘がございました先進自治体のところで調査研究してまいりたいと考えております。その中で、なかなか回収件数が５０％を超えないというのは悩ましいところですけれども、回答を区民に呼びかけてまいりたいと考えております。","id":"exchange-125"},{"speaker":"若林委員","kind":"意見","question":"２,０００名というところ、何かもう来年度の人数が決まっていて、予算の関係でみたいなご答弁がありましたけれども、これはこれから予算を組んでいかれると思いますので、ぜひ予算を、もう一声頑張っていただいて、私の趣旨も酌み取っていただいて…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１８８ページの人事管理費と、１９５ページ、公金取扱事務費でよろしいでしょうか。令和４年度においては、病気等休職者は何名いるかお伺いします。","respondent":"崎村人事課長","answer":"分限の休職者数ですけれども、令和４年度については約９０名ほどとなっております。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"さて、品川区では、病気休職中のメンタル不全者の数について、平成２９年度からお伺いします。さらに、メンタル不全者の中で、パワハラが原因で休職せざるを得なかった職員の数、こちらもお伺いします。","respondent":"崎村人事課長","answer":"平成２９年度からの実績ということでございましたけれども、大体７割程度が精神疾患による病気休職者となっておりまして、委員ご紹介のとおり年々増加しているような状況です。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"確認","question":"メンタル不全者の中で、パワハラが原因で休職されたことは今はないということですが、今までないということで、確認でよろしいでしょうか。すみません、改めてもう一度。","respondent":"崎村人事課長","answer":"休職に入る際に、直接休職者に聞き取り等を行っておりますけれども、パワーハラスメントを原因として休職に入ったというような事例はございません。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"この件はどのように発覚し、どのような経過で懲戒処分に至ったのでしょうか。その経過を伺います。","respondent":"崎村人事課長","answer":"今回の事例につきましては、本年の３月に職員から人事課にご相談いただきまして、また、併せてその翌月にも他の職員から同様の相談がありましたことから、人事課を中心として調査を行い、処分を実施したところです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから、苦情処理委員会というのですか、それがあると思います。もう１回そこの辺の経過、そして、苦情処理委員会にかけたとすれば、そのメンバーというのをもしお話ししていただけるならば、お尋ねします。","respondent":"崎村人事課長","answer":"人事課長と人事係長、あと総務部長が指名する職員ということで、３名で調査を実施したところです。その他区長が認める管理職２名ということで、５名体制で審議を行ったところです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"私が知っているところではなかったわけで、過去にこういったパワハラで処分された職員はいらっしゃるのか伺います。先ほどは、パワハラにおいて休職せざるを得なかった職員の方ですが、パワハラで処分をされた方のほうです。","respondent":"崎村人事課長","answer":"過去、パワーハラスメントで懲戒処分を行ったという例はございませんでした。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"区の中でどういうことが起きているかということが、ホームページで分かりますので。そこで、「より一層の」という点が入っていますので、その点を含めて具体的に、改めて今後の考えをお伺いします。","respondent":"崎村人事課長","answer":"必ずハラスメントの研修を受けるということを行ってまいりましたけれども、ハラスメントの研修については全職員に実施するということで、来年度の予算要求をさせていただきたいと考えているところです。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"意見","question":"その負担が来年の１０月から増えます。今年度、幾らだったのか、それが来年度幾らになってしまうのか、それを令和６年度予算でどのように予定しているのか、お願いしますとの意見を述べました。","respondent":"大串会計管理者","answer":"年によって変わってまいりますが、今現在、この振込手数料、年間で１,５００万円ほどです。ですが、ざっとした試算ですけれども３,７００万円ほどの金額になろうかと考えています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのサービスはしようがないのですが、何とか方策を考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-135"},{"speaker":"西村委員","kind":"質問・要望","question":"インバウンド向けコンテンツ開発、ＰＲ、積極的なセールスまでできる取組を要望したく、質問します。地域経済に直接影響のあるこのような取組をどうお考えか、団体に支援をできないか、伺います。","respondent":"篠田文化観光課長","answer":"今も、同じ品川宿ですけれども、ゲストハウスに体験型として様々なゲストツアーを実施していただいたりといった取組をしています。これまでの事例等も研究しながら、今後、検討してまいりたいと考えているところです。","id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"この京浜エリア全体で捉えますと、海外の方を救い上げるチャンスのある地域として、京急も大変力を入れておられると伺っています。品川区は羽田への行き帰りに立ち寄れる場所ですから、品川区としてこのインバウンド需要に関してどのようにお考えで、説明を求めました。","respondent":"篠田文化観光課長","answer":"トランジットの待ち時間等を利用して、天王洲などの地域にも誘致できるような形で、ご案内できればなと思っているところです。先ほど申し上げた、川崎市、大田区とは３都市連携ということで、一緒に３つの都市で、海外に向けて情報発信等も行っているところです。","id":"exchange-137"},{"speaker":"西村委員","kind":"意見","question":"魅力的な建築物もたくさんありますし、そのようなヒト・モノ・コトを品川ならではの魅力あるコンテンツとしてＰＲできる予算が必要だと考えています。区のお考えを説明を求めました。","respondent":"篠田文化観光課長","answer":"昨年、ホッケーのときにも、実は地域の方と連携して様々な体験をしていただくような形でのツアーを組んだところです。特に海外からのお客様に関しましては、私どもも何らか取組ができるように、今後考えてまいりたいと思っているところです。","id":"exchange-138"},{"speaker":"西村委員","kind":"質問・要望","question":"先日はホッケーしなフェスにも伺いましたが、まちづくりというのはこんなことまでできるのだと、今の品川区に本当に感動しております。改めまして今年度の取組、また区の評価、抱負を説明を求めました。","respondent":"篠田文化観光課長","answer":"ホッケーの選手、ユニフォームを着た本当の選手の方々が歩かれて、またお店で飲食などをされているというのもかなりあったと伺っております。私どもも、どういった形で有効な手立てが打てるのかということは、常に研究してまいりたいと考えているところです。","id":"exchange-139"},{"speaker":"西村委員","kind":"質問","question":"７月に社会人サッカーチーム品川ＣＣセカンドとのエキシビションマッチがありまして、伺いましたけれども、今も在住でいてくださっていると。いろいろなことが相乗効果になってきていると思いますが、一言、区からもいただけますか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今回、日本代表候補のトレーニングマッチも行いまして、いい関わりができたと考えています。今後も、デフサッカーを盛り上げていきたいと思っていますので、今後、次年度に向けていろいろ準備していきたいと考えております。","id":"exchange-140"},{"speaker":"松本委員","kind":"質問","question":"私からは、１８７ページ、男女共同参画推進事業、少し時間が足らないかと思いますが、２０１ページ、できれば歩行喫煙防止推進経費について伺います。男女共同参画推進フォーラムの講師料は、歳出予算見積書上はフォーラム講演会の業務委託料に含まれているのか、伺います。","respondent":"加島人権啓発課長","answer":"令和４年度の男女共同参画推進フォーラムにつきましても、令和５年度同様、委託料の中に含まれております。こちらの委託料の支出の内訳ということですけれども、申し訳ございません、今、手元には所持しておりません。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問・要望","question":"目標値を上げているのかなと思って、今回出していただいている行政評価シートを確認すると、参加者の目標は一貫してずっと２５０人ということでした。令和５年度にいきなり予算が２倍近く増えているのは、よくあるのですけれども、これはどういった事情なのでしょうか、伺います。","respondent":"加島人権啓発課長","answer":"今、委員からもございましたとおり、男女共同参画推進フォーラムでオンライン配信のための経費を新たに委託料に計上いたしました。それから、カレンダーの関係で上下することがございまして、そういったものが影響しているのではないかと考えております。","id":"exchange-142"},{"speaker":"松本委員","kind":"質問・要望","question":"一方で、その４日後ですから２９日に、中止しますという判断が出たという連絡が来たのです。これが中止になった理由はどういう事情でしょうか、お願いします。","respondent":"加島人権啓発課長","answer":"区としてその内容をなかなか見過ごすことはできないのではと考えまして、今回、中止の判断に至りました。区議会の皆様、区民の皆様にご迷惑、ご心配をおかけしたことは、大変申し訳なく思っております。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"ということで、これはクレームがあったと理解していいのでしょうか。お願いします。","respondent":"加島人権啓発課長","answer":"やはりネットニュースと相違がないこと、それから、全体のジェスチャーの中でもなかなか見過ごせないものがございました。そういったことを判断いたしましたのと、あと、区内からもやはり苦情のお声というのは届いております。","id":"exchange-144"},{"speaker":"松本委員","kind":"確認","question":"確認ですが、これ、クレームは区内からということでいいでしょうか。あくまでまずは区でその番組を確認して、これはやはり呼ぶにはどうなのかなということで判断されたとお伺いしてよろしいでしょうか、お願いします。","respondent":"加島人権啓発課長","answer":"ふれあい掲示板にポスターを貼らせていただいて周知をしていたような関係で、お声があったものは区民というふうにこちらで判断いたしました。中止の件につきましては、ただいま委員からもご案内がございましたとおり、発言内容を考慮いたしまして…","id":"exchange-145"},{"speaker":"松本委員","kind":"質問・要望","question":"大体、委員の方の報酬等も含めると、全部で１８０万円ぐらいかけている事業かと思います。クレームが来たとしても、そういったキャンセルカルチャーにしっかりと対抗していくというふうに求めたいと思いますが、ご見解を伺います。","respondent":"加島人権啓発課長","answer":"男女共同参画推進フォーラムではないのですけれども、昨年１２月に人権週間講演会を実施いたしまして、講師に安田菜津紀さんをお呼びいたしました。こちらについては、ご意見があったとしても講演会をそのまま開催させていただいたことがあります。","id":"exchange-146"},{"speaker":"松本委員","kind":"意見","question":"例えば田嶋陽子さん、政治的にどうかと言ったら、私も全然異なる立場もあると思います。今日は、以上で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"飲食はもう有料でやったらどうだという質問をずっと、要望を含めてしていたのですが、そこを改めて伺います。だけど、何でこういうところをやらないのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"そこら辺のメンタルをどういうふうにフォローしていくのか、その辺についてお伺いします。当選することよりも、ポスターを貼る番号が４９番以降にならないでほしいと。","respondent":"小林施設整備課長、辻広報広聴課長、勝亦総務課長、岡秘書担当課長、崎村人事課長、田口人材育成担当課長、河内環境課長、河合生活安全担当課長、提坂税務課長、鈴木選挙管理委員会事務局長","answer":"私からは、照明器具のＬＥＤ化についてお答えいたします。平成３０年度から計画的に進めているところでございまして、その効果ですが… こちら、区民と共に進めて８年目になるわけですが、現在、森澤区長の下、新時代の品川を進めていく状態です。そろそろこの合い言葉とは… 私からは賀詞交歓会についてお答えいたします。区と関係の深い団体との親睦を目的として実施していますけれども、会場での飲食の提供等については… 自治功労賞等の表彰は総務課の事業ですが、秘書担当で実施しております。…","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、せっかくですから、秘書担当をどんどん活用してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１８７ページの男女共同参画推進事業、１８９ページの職員給与費で会計年度任用職員の給与費と、それから保健師の増員を求めて質問したいと思います。ぜひこの私立学校、国立、都立も含めて、学校給食費の無償化を品川区でも行っていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問・要望","question":"全ての子どもたちの１８％もいるわけですから、私はこの子どもたち、それから家庭を差別すべきではないと思います。勤勉手当というのが会計年度任用職員には反映されていないのですが、これについても反映されるべきだと思うのですが、いかがか尋ねました。","respondent":"崎村人事課長","answer":"自治体によっては、こちら、昇給ですとか経験加算を実施している区もあるということは認識しております。特別区職員労働組合連合会と、そういった勤勉手当の支給に向けて、今後交渉が行われると伺っているところです。","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、そこに対しての加算なり手当なりを出すようにしていただきたいと思うのですが、いかがでしょうか。そこのところを是正するという意味からも、私はこの会計年度任用職員の待遇改善というのは欠かせないことだと思うのですが、いかがか尋ねました。","respondent":"崎村人事課長","answer":"それが賃金に加算されるということは、常勤職員でもありませんので、そういった考えはございません。賃金に差を設けているわけではありませんので、会計年度任用職員の処遇改善をしたからといって、そこの格差が縮まるといった認識はございません。","id":"exchange-153"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今現在どうなっているのか、また来年に向けてどうしようとしているのか、伺いたいと思います。医師会の要望書の中でも、保健師確保のための予算の確保をご検討くださいという要望書を、その点いかがか尋ねました。","respondent":"崎村人事課長","answer":"２３区の平均が、それを満たすためには約１０名の増員が必要と、今のところの数字として把握をしています。近年でも保健師の人数、採用と育成のバランスも考えながら、増員については図っていきたいと考えているところです。","id":"exchange-154"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひとも計画的に保健師の増員ということで、もう本当に早急に、せめて２３区平均までは持っていっていただきたいということで、要望します。これを明記して、この視点をしっかりと入れるべきではないかということを申し上げてきたときに、明記することになった理由も少し伺いたいと思います。","respondent":"加島人権啓発課長","answer":"男女共同参画センターでも啓発を進めております、生涯健康でいられるための考え方として、基本理念に加えさせていただいたところです。それから、リプロダクティブ・ヘルス／ライツに関する考え方は今でも同じかというところですけれども…","id":"exchange-155"},{"speaker":"鈴木委員","kind":"質問・要望","question":"性と生殖に関する健康と権利というところで、ウィキペディアを引いただけでも、もっと深い中身が記されているのです。こういう権利が９項目、もう少し深く捉えて、ここに反映させていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、１７９ページ、情報公開等経費、１８７ページ、男女共同参画推進事業でＤＶ・カウンセリング相談について伺います。問題がぴんとこなかったということも含めて、区全体の認識が甘いのではないかということを懸念いたしましたが、改めて見解を伺います。","respondent":"辻広報広聴課長","answer":"その裏に、その内容について申立てがあるときは、品川区長に対して３か月以内に審査請求することができますと書いてあります。私どもとしましても取りまとめの課として、そこのところはきちんともう一度各機関にお知らせするといいますか、徹底するようにしたいと考えています。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問","question":"本来の請求先にきちんと回されて、弁明書など、その後の手続に入れると理解してよろしいでしょうか。そうすべきと考えますが、見解を伺います。","respondent":"辻広報広聴課長","answer":"前例としまして、行政委員会に審査請求を出すところを区長部局に出したというような事例はないのですが、もしも仮にそういうことがあったときには、それは出す先が違うということでもちろんお伝えして、適正に権利が行使されるようにはしたいと思います。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"さあ、一応相手先を確認して間違いに気づいたというところもありまして、きちんとその辺のところを認識していないといけない。行政情報の公開または開示を求める権利が保障されている」、区民と区政との信頼関係を強化するため不可欠な事業である」と評価されております。","respondent":"辻広報広聴課長","answer":"指標のところでは、不服申立てがこのぐらいあるだろうという計画値に対して、その計画より上回っていたということで書いてはあります。予定していた回数よりも審議会の開催回数が少なかったので、報酬費が少なかった、執行率が低かったという記載になってあります。","id":"exchange-159"},{"speaker":"吉田委員","kind":"質問","question":"次に、１８７ページ、ＤＶについて伺いたいと思います。これは、男女共同参画センター以外に、どこで目に触れることができるのか、教えてほしいと求めました。","respondent":"加島人権啓発課長","answer":"」の冊子の件ですけれども、こちらにつきましては、設置しているというよりも、若年層に向けて配布をさせていただいています。それから、男女共同参画センターで行っております啓発講座、デートＤＶに関する講座の中でお配りしている形になります。","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば地域センターとか、それから児童センターとか、そういうところにも配布することはできないでしょうか。ぜひ前向きに検討していただきたいのですが、いかがでしょう。","respondent":"加島人権啓発課長","answer":"児童センターへの設置というところにつきましても、各所管に可能かどうか、話合いをしてみたいと思います。","id":"exchange-161"},{"speaker":"吉田委員","kind":"確認","question":"それから、相談窓口ですが、品川区内ではきゅりあん３階の男女共同参画センターということで理解していいでしょうか。きゅりあんで最後までご相談していただけるのか、その辺のことを確認したいと思いますが、いかがでしょう。","respondent":"加島人権啓発課長","answer":"こちらですけれども、ご本人の希望ですとか相談員の勧めで、複数回の予約をこちらからお願いすることもあります。相談者の２次被害の防止、それから、こちらは東京都性犯罪・性暴力被害者ワンストップ支援センターにつないでいくように心がけているところです。","id":"exchange-162"},{"speaker":"吉田委員","kind":"質問","question":"それで、やはり２５％ぐらいは男性が被害者です。これだと男性は相談しにくいかなと思うのですが、その辺の男性に対する配慮というか、その辺はいかがか尋ねました。","respondent":"加島人権啓発課長","answer":"東京ウィメンズプラザで男性のための悩み相談というのを実施しておりますが、確かに委員ご指摘のとおり、この裏表紙からはその情報が読み取れない形になっておりますので、改善を図ってまいりたいと思います。","id":"exchange-163"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちも啓発とか、気をつけるようにしますけれども、ぜひ一緒に進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"端的に２つ、改めて伺います。避難民の人数について公表することが、個人の特定や脅威にはつながらないと考えますので、改めて伺います。","respondent":"勝亦総務課長","answer":"当初、支援の声が強く、少し避難民の方が不安を抱くようなケースがあったという経緯もあります。今後、人数についてはまずお知らせいたしまして、今後さらなるウクライナへの支援を行ってまいりたいと考えております。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"質問","question":"早速ですけれども、それでは、直近、何世帯、何人のウクライナ避難民の方が品川区にいらっしゃるのか伺います。","respondent":"勝亦総務課長","answer":"現在、６人の方が区内にいらっしゃいます。","id":"exchange-166"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その上で、昨年来、私が求めているのは、品川区として支援への積極的な姿勢を打ち出すための、全庁的な対応ということでした。改めて慎重かつ迅速な、全庁的な調整と決断を求めてほしいと求めましたが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"そうした考え方の下、ウクライナの方への支援の拡充、こちらを今、区の幹部も部長級そろって聞いております。慎重、かつ積極的に支援の拡充を図ってまいります。","id":"exchange-167"},{"speaker":"あくつ委員","kind":"質問","question":"お伺いしたいのは、昨年、令和４年度までにいろいろな事業があったと思うのです。これ、名簿の提供はどういう仕組みでされていたのかということと、ハレーションが他自治体では起きていないのかどうかということを伺います。","respondent":"宮澤地域活動課長","answer":"町会・自治会への高齢者等の名簿の提供がどういう仕組みかというところからまずお答えいたします。掲示板等で募集して、応募して、その中で提供していると把握しているというふうにお聞きしています。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問","question":"７５歳以上の方に向けて全部調査をかけて、そこに地域の見守り事業について提供してもいいですかというものもくっつけて送っています。そうした同意を得た名簿、これは見守り活動の一環としてそういうものを活用できないのか、このことについてお伺いしたいと思います。","respondent":"宮澤地域活動課長","answer":"区では３年に一度、民生委員の方が高齢者の実態調査というのを実施しております。同意を得られた方、また調査対象も絞られていると聞いておりますので、あくまでも補完資料という位置づけなのかなと考えているところです。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問・要望","question":"地域の対象年齢の方の住基の情報が全部提供されていたわけですから、補完資料ということですけれども、このことについては周知をしていただきたい。簡単にはご答弁できないと思いますけれども、ご見解を説明を求めました。","respondent":"宮澤地域活動課長","answer":"従前の名簿の提供というのは難しいというところで、町会・自治会においては、いわゆる手挙げ方式で取り組んでいるというのも認識しております。支援の仕方等を示しておりますので、そういったところも活用しながら、できる限りの支援策というのを考えていきたいと考えています。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"少し時間がなくなってしまったので、１点だけ伺います。それを通して品川区でひもづけのミスがあったのかどうか、苦情が１件でもあったのかどうか、最後にお伺いします。","respondent":"吉野戸籍住民課長","answer":"ひもづけに関しましては、間違いはありませんでした。苦情等もありませんでした。","id":"exchange-171"},{"speaker":"せりざわ委員","kind":"質問","question":"１８７ページのＤＶ・カウンセリング相談、関連して１７９ページの犯罪被害者支援、時間が余れば１９７ページの地域美化推進補助について伺います。区がやる意義というのを改めて説明を求めました。","respondent":"加島人権啓発課長","answer":"先ほど令和２年４月１日付で配偶者暴力相談支援センターの機能を整備したと申し上げましたが、こちらは。自治体として配偶者暴力防止のために相談支援を行っていくということは、安全、自治体として非常に重い責任を感じております。","id":"exchange-172"},{"speaker":"せりざわ委員","kind":"質問","question":"大阪府警のデータによると、２４時間の中では夜間・休日のＤＶ相談というのが８０％あると伺っています。区がそれは責任を持ってやりますよというような連携も必要なのかなと思うのですが、その２点、説明を求めました。","respondent":"加島人権啓発課長","answer":"東京都との連携というところですけれども、２４時間、電話によるＤＶ相談プラスというものを行っております。それから飛び込みでいらっしゃる方もいらっしゃいますので、そういった方のお気持ちに寄り添って、面談等につなげていくように努力してまいります。","id":"exchange-173"},{"speaker":"せりざわ委員","kind":"提案","question":"別れるという選択肢を品川区が提案してあげるというのも、これは踏み込んだ話になると思いますが、必要なのだと思うのです。その被害を受けている方々も別の道があるのだということをしっかり見せるということも、一つ必要なのかなと思うのですが、ご見解を説明を求めました。","respondent":"加島人権啓発課長","answer":"今、一定、電話予約というのは意味があるのかなと考えております。それとも仲を修復したいのか、そういったお話をよく聞き取った上で、最善の支援につながる提案をしたいと考えております。","id":"exchange-174"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"電話である必要性はないのかなと思うので、それをネット上でできるような仕組みというのは、もう一度お考えほしいと求めました。こういう道もありますよという道を示してあげるのも、相談体制としては必要なのかなと思いますので、最後は要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":120294,"voices":407}},{"id":"r05-20231005-4","meetingId":"r05-c-settlement","date":"2023年10月5日","dateIso":"2023-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を155件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"２７３ページ、病児保育、２６５ページ、子どもの未来応援事業についてお伺いいたします。病児保育の対象年齢を小学校１年生から３年生くらいまでに拡充していただきたいと要望いたしますが、区としては、どのようにお考えか尋ねました。","respondent":"立木保育課長","answer":"そうしたことも含めまして、まずは、病児保育を実施できる施設の充実を図らせていただきたいと考えています。そうした中で、年齢の拡大については、そういったところで検討をさせていただきたいというふうに考えているところです。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"空きが出ているときには、小学生でも利用できるように柔軟に対応していただけるように、区として働きかけていただくことはできますでしょうか。区としての見解を説明を求めました。","respondent":"立木保育課長","answer":"病児保育の新しい施設は、今、東大井の施設で交渉を進めている最中でございまして、来年度に向けてできればと思っているところです。施設のハード・ソフトの面で対応が可能かどうかというところもありますが、実施者と、今後協議は進めていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"働きながら子育てをする保護者のセーフティネットとしての病児保育は、ぜひ拡充していただきたいと改めて要望いたします。続きまして、子どもの未来応援事業についてお伺いいたします。","respondent":"飛田子育て応援課長","answer":"寄附額が増えた要因については、なかなか分析は難しいところですが、こちらの事業は、令和元年度から始めて昨年度で４回目となりました。電話等で相談や支援につなぐ事業も行っております、そちらのほうに４.１％、諸経費として３.６％使用しております。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問・要望","question":"利用された方からも、ふだん買物に行く際に、ローソンなどからの寄附でいただいた食器用スポンジ等の日用品も大変喜ばれているとお聞きしています。洗剤などの日用品の同封を今後も継続していただきたいとの要望をいただいておりますので、区としての見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"子どもたちの食の支援へのご協力をお願いしますとうたっておりますので、寄附をされている方はそれについてご賛同いただいていると認識しております。ですので、区が行う食品配送につきましては、今後も食の支援を中心として行いたいと考えております。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"新たにＩＴ分野にも拡充されたことを踏まえ、広く周知していただくためにも、その案内を同封していただきたいと望んでおります。始まった後にも改めてご紹介するというように、繰り返し周知していただくことも大切なのかと思いますけれども、区としてのご見解を説明を求めました。","respondent":"飛田子育て応援課長","answer":"そういうところを引き出しながら、その人に合った支援、そういうところを一緒に相談しながら新しい施策等も紹介していきたいと考えています。いずれにしましても、各家庭の自立を目指して支援に結びつけられるよう、これからも取り組んでまいりたいと思います。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。以上、要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、障害者支援費から２点お伺いいたします。２３３ページの地域生活支援事業、２３４ページの日常生活用具給付事業について、それぞれお伺いしてまいります。","respondent":"松山障害者支援課長","answer":"シルバーセンターマッサージでは、報酬を受けとられることによって経済的な支援とみなされ、国では同行援護の対象とはなりませんでした。非常に私たちも悩みまして、今、研究を進めているところです。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"視覚障害者福祉協会の団体からの要望も受け、本年も継続して公明党の会派要望として上げさせていただいている内容でもあります。この重度障害者等就労支援特別事業について、改めて本区でのお考えをお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"委員ご提案の重度障害者等就労支援特別事業についての区の考えです。こちらの重度障害者就労支援特別事業の導入により、他区の状況も確認しつつ、視覚障害者団体のお声も伺いながら検討を進めていきたいと考えています。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"続いて、日常生活用具給付事業について質問いたします。どういったものなのか、ここ数年の、支給実績や活用された現場の声などがもし分かれば教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"１つは、携帯会話補助装置ですが、肢体不自由で音声言語の著しい障害のある方にご使用いただいております。奥行きが１０cm程度の立方体のものでして、少し持ち運びに不便だというお声をいただいておりまして、こちらのほうの実績はございません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"アプリはカタログ等で視覚・聴覚等障害者の日常生活に資することが確認できるアプリであれば、有料、無料を問わず対象としています。どうか時代に即して、メールソフト以外の視覚障害者向けソフトを追加することを要望しますが、区のお考えをお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"これまでも障害者団体のお声を聞きながら品目の変更ですとか、どの品目で、どの機器をカウントするかといった整理などのご要望をいただいております。毎年行っております日常生活用具検討会で、今後、具体的に検討を進めていきたいと考えています。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区では、里親証明書などの作成は考えているのでしょうか、区のお考えをお聞かせください。失語症者向けの意思疎通支援者の派遣事業も、東京都の制度を利用しながら進めていただきたいと思うのですが、いかがか尋ねました。","respondent":"飛田子育て応援課長、川原高齢者地域支援課長、長谷川児童相談所開設準備課長、松山障害者支援課長","answer":"そして、在学応援資金は２６人の方が利用しました。区としてもそれに合わせて設定をしております。 今年度も昨年度に比べまして９,０００人を割る人数となってしまってあります。行政としても、そこの会員の増強化であるとか… 区としましても、他自治体と同様の運用方法を検討しております。区が認定証をつくったとしても、区児童相談所が開設する際には… とはいいましても、失語症の方への支援は大事だと考えております。それで支援者を確保するということが大事だと考えております。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現在、外国籍の里子も増えてきているとの話も伺っております。こちらは重ねての要望とします。","respondent":"飛田子育て応援課長、川原高齢者地域支援課長、長谷川児童相談所開設準備課長","answer":"今まで免除になった割合ということですが、こちらの事業を行いまして、人数は延べ４４名となっております。そういうこともありましたので、その方は… 高齢者クラブの広報活動の取組など、ご提案をいただきました。いただいたご意見につきましては、今後、連合会の会長である副会長の皆様と協議を重ねながら… 里親に対する研修を充実させていくことと、マッチングをする際に双方の意向を十分に確認することが重要であると認識しております。区としましても…","id":"exchange-012"},{"speaker":"ひがし委員","kind":"確認","question":"高齢者クラブ支援事業については、またご検討いただけるということで、前向きな答弁だと確認いたしました。そして、開設の準備の段階で運用に向けて検討を様々と進めてほしいと求めましたので、引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"今年２月の一般質問と、３月の予算特別委員会で、定員割れ私立保育施設への加算制度について伺いました。保育支援課長は代わっていますけれども、なぜそうなるのか伺いたいと思います。","respondent":"石井保育支援課長","answer":"令和５年度予算では、こういった事業を行うことで、逆に空きがあることがチャンスだというふうに思っている事業者もおります。一義的に補填をすることが、そういった努力しようとしている事業者の工夫の妨げになるのではないか、そう考えているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"もう少し伺いたいのですけれども、人件費を削減しなさいよと、そういうことを差して言っているのでしょうか。もう一度伺いたいと思います。","respondent":"石井保育支援課長","answer":"先ほども申しましたが、園児数が減ったことによって保育園を減らす、これは経営努力ということではなく、様々な園児獲得のための努力、空きスペースや空き定員を活用した新たな事業、そういったことが経営努力につながると考えています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、これまで品川区の保育を担ってきた地域の保育園の存続、定員定額制を品川区でも検討すべきではないのでしょうか。改めて伺います。","respondent":"石井保育支援課長","answer":"処遇改善臨時特例事業について、認証保育所運営費の中でもその分が工面されているところですので、一時的なものではないというふうに認識しています。それらを踏まえまして、定額制にするということについては考えてございません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し細かい話でまず伺うのですけれども、例えば、タクシー料金が２,１００円でした。こういう場合に、おつりは出るのでしょうか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"先ほど委員がおっしゃった計算ですと、おつりとしては出ません。ただし、その場合、現金をお支払いいただくという方法はあります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"当事者団体からも毎年要望が上がっていて、一般質問でもありましたし、なぜ増やしていただけないのでしょうか。なぜやらないのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"福祉タクシー券の券種についてのご質問です。１００円券を増やすと非常に扱いにくいというご要望もいただいておりまして、今の状態で調整させていただいているです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"６,０００円分の商品券が交付はされましたが、これ、恒久的に続くわけではないわけです。やはり視覚障害者の外出を保障するために、補正にとどまらず、金額そのものを上げるべきだと思いますけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"対象者の方として、下肢体幹や視覚障害、内部障害、愛の手帳をお持ちの方がいらっしゃいます。今後も利用者の状況、今後の物価の推移を見ながら、さらなる検討をしてまいります。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"２４９ページ、２８９ページ、これは時間があれば伺います。今までとどう変わっていくのか、どうよくなっていくのか、その点をお伺いいたします。","respondent":"東野福祉計画課長","answer":"参加支援、地域づくりに向けた支援、こちらを重層的支援と位置づけて進めているものです。今言った相談支援、参加支援、地域づくりに向けた支援に向けまして。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"第８期品川区介護保険制度推進委員会等でこのことについてご検討されていると思うのですけれども、今後、課題があるのでしょうか。支え愛・ほっとステーションのことが取り上げられているかと思うのですけれども、今後の支え愛・ほっとステーションの役割を説明を求めました。","respondent":"東野福祉計画課長","answer":"先ほどの説明に加えましてですが、重層的支援体制整備事業の中で、外部の機関との連携についても求められているところがあります。検討を進めているものでございまして、どう取り組んでいくか、区民への浸透がこれからの課題となってくるかと考えています。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"１０年ほど前、また、ほかの区では同様の事業はあるのでしょうか。説明を求めました。","respondent":"東野福祉計画課長","answer":"地域の方、それから行政とでお互いに支え合っていくという部分での意味合いが込められているものと考えています。支え愛・ほっとステーションにつきましては、福祉的なところを補っていただいているというような位置づけとなっています。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"なぜこのような質問をさせていただいたかといいますと、今、マンション内とかでも掲示されていることかと思います。その点、どうお考えなのか尋ねました。","respondent":"東野福祉計画課長","answer":"それから、パンフレット等につきましては、区内の施設での配布を行ってまいりました。今後もこういったパンフレットの配布、周知、それから、今、ＳＮＳなどでも取り上げて、周知を図っていきたいというふうに考えているところです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"行政評価シートの７２ページで、地域活動課の事業として今後も実施を続けるかは検討が必要と考える」ということなのです。確かに似たような事業はなるべくまとめて整理されるべきかなと考えておりますけれども、その点、いかがお考えなのか尋ねました。","respondent":"東野福祉計画課長","answer":"支え愛・ほっとステーションの企画している内容の１つとして、身近な地域で高齢者の方等が参加できるスペースの提供、場の提供を行っております。その点につきましては、支え愛活動の部分を今後どうしていくかということで…","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"続いて、高齢者向けパソコン・スマホ教室について伺いますけれども、今、どんどんＤＸ化が進んでおりまして、行政のほうでもＤＸ化が進んでおります。Ａｎｄｒｏｉｄ２か所というような、開催場所も４か所からもっともっと増やすべきでありますし、いかがお考えか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"もう１つ、昨年度の８月から事業を開始いたしました「はじめてのスマホ体験教室・スマホよろず相談」、こちらは事業者によるものです。エリアを考えて設置、開催の約１か月前に周知をさせていただいて、応募を承っているところです。","id":"exchange-025"},{"speaker":"筒井委員","kind":"意見","question":"今後はどんどん高齢者の方もスマホをぜひ使いこなしていってほしいですし、世の中のＤＸ化で取り残されてしまう、ひいては、社会全体の活性化の遅れということになってもきますので、この高齢者向けパソコン・スマホ教室の拡充をぜひよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"せらく委員","kind":"確認","question":"ガイドラインの改定が平成３０年度に行われたという記載を確認しています。次の改定時期はいつか尋ねました。","respondent":"立木保育課長","answer":"それを盛り込んだ形で検討してまいりたいと考えていますので、そういったものを見極めた以後に、というふうに今は考えているところです。こちらの受講者の目標数値の考え方ですけれども、これは理想とする保育士像を考えた上で設定しているようなところです。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"子どもに対する犯罪防止には、対策や知識をアップデートをしていくことが求められていると考えます。後ほど、私立園での状況もお聞きしますが、まず区立園のことでお願いします。","respondent":"立木保育課長","answer":"保育者から子どもたちに、そういったことを伝えているというような、そういうようなやり方をしています。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"保護者会等で保護者への情報共有をして知識のアップデートを進めるべきだと思いますが、いかがでしょうか。お互いに自分を守るための保育・教育をお願いしたいと思いますが、こちらは区の見解を伺います。","respondent":"立木保育課長","answer":"そういった中で、もし何か適用できるようなものがあれば、考えていきたいと思います。のびしなプロフェッショナルスクールの中でも、何かそういういいものがあれば、取り入れていきたいというふうに考えております。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"私立保育園で伺います。このような取組を私立保育園でもするべきだと思いますが、保護者会での幼児からの性教育情報の共有については、いかがか尋ねました。","respondent":"石井保育支援課長","answer":"今年８月、９月を、そういったことで普及啓発に対してご協力いただきたいというふうな要請が来てあります。こういったことの依頼がありますので、区としましても、きちんと国の要請に基づき適切な対応を行ってまいりたいと考えています。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちらは、学校では既に周知がされていると会議録でも確認しておりまして、保育士研修などでもぜひ取り入れてほしいと求めました。こちらについて、ご意見をお聞かせいただきたいです。","respondent":"立木保育課長","answer":"こちらは区立保育園においてもしっかり取り入れて考えていきたいというふうに考えておりますが、のびしなプロフェッショナルスクール等の場を使いまして、そういったものに適用できるような形で何かしら考えていきたいと思います。","id":"exchange-031"},{"speaker":"せらく委員","kind":"意見","question":"子どもの大事な命を守るためにも、保育環境を引き続きよくしていただきますよう、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私は、今年８月、警視庁大森少年センターの取組について、黛前所長からお話を伺いました。心理の専門職の方々のお話も伺いましたが、少年非行の相談があった場合には、どのように対応しているのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"対応の部分ですけれども、子ども家庭支援センターにおきまして、非行相談を受けております。つなぐといった形で対応していますし、連絡を密にとりながら対応しておりまして、そちらの連携は非常に重要なものだと認識しています。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"人間でいうと差し飲みというのでしょうか、１体ずつを仲よくしていって、それが全て終わったら群れに戻すというような形をやっているそうです。お伺いいたしますが、関係性を築いていますでしょうか、現状を説明を求めました。","respondent":"染谷子ども家庭支援センター長、藤村子ども育成課長","answer":"はつながりを持つことが重要というところにつきましては、こちらも同様の認識をしています。それから、そういったところでも継続的にメッセージのやり取りをさせていただきながら… 先ほどの子どもの意見を取り入れるというところのご質問です。児童センターの在り方検討等を踏まえて、中でも意見を取り入れておりますので、今後も検討してまいりたいと思います。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"２５７ページ、４８２ページ、介護認定審査会費についてお伺いしてまいります。そして、今後の取組についてもお伺いいたします。","respondent":"松山障害者支援課長","answer":"令和３年の条例制定以降、区職員向けの手話講座を実施いたしました。２０２５年、デフリンピックの東京開催が決定いたしておりますので、また大会の機運醸成を図ってまいりたいと考えております。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"１０月１４日に、スポーツ推進課と連携をして今進めていただいていることと思いますが、こういう機運醸成のための取組が大事かなと考えています。当然ながら、この事業、アイルしながわで行われます内容に関しては、障害者団体の方との連携はとられているのでしょうか、お伺いいたします。","respondent":"松山障害者支援課長","answer":"委員にご紹介いただいた１０月１４日の「デフスポーツ＆アートフェア」についてです。私どももブースを１つ設けまして、当事者の団体と調整しながら、今、こちらのブース開催に向けて取り組んでいるところです。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ団体の方のご要望を伺っていただきながら、ご検討を進めていただきたいと要望をしますので、どうぞよろしくお願いいたします。その後、現状どうなっているのかということを確認させてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"すまいるスクール全３７か所のうち、令和３年度に調査させていただいた際に、トイレの状況に難があるというのが１１か所程度あるということです。その１１か所のうちの８か所は、トイレの数が増えたり、洋式化が進んでいるというような状況で改善しているという状況です。","id":"exchange-037"},{"speaker":"新妻委員","kind":"意見","question":"そうしますと、残り３か所、この３か所につきまして、どういう対応がとられているのか、今後の予定も含めてお知らせくださいとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"すまいるスクールの活動場所の階と同じ階に使えるトイレがないというようなところが３か所残っているような形になっております。今後の対応といたしましては、和式を洋式に変えるという検討ができないかですとか、そういった対応をとっていきたいというふうに考えております。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"区議会公明党は、学校の中での洋式トイレの推進もしていますが、これまでも何回か要望しています。改めて要望しますが、見解を伺います。","respondent":"藤村子ども育成課長","answer":"委員の要望を踏まえまして、教育委員会と協議を進めていきたいと思います。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問","question":"すみません、最後の質問は時間がなくなりましたので、以上で終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"えのした委員","kind":"質問","question":"私からは、２３７ページ、障害児者福祉施設運営費、２４５ページ、福祉人材確保・定着事業についてお伺いします。北品川つばさの家の修繕工事費等に２,９００万円がついていますが、こちらは何の修繕に使われたのか尋ねました。","respondent":"松山障害者支援課長","answer":"脱衣室内装改修工事およびドアチェーン取付工事等で７８万円余、加えて、電気設備更新に伴う改修工事で１,６５８万円余です。後段の電気設備更新工事につきましては、同じ建物内の品川児童相談所との共有部分の改修工事となるため、負担金の扱いとなっております。","id":"exchange-041"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。今年の８月に、我が会派で、北品川つばさの家へ視察に伺いました。","respondent":"松山障害者支援課長","answer":"委員ご指摘の手すり等につきましては、利用者が安心して過ごせるよう、現在、指定管理者と協議、調整しています。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問・要望","question":"障害者が本当に安心できる生活支援、障害者グループホーム整備のさらなる推進、また拠点づくりの推進を要望いたします。令和５年５月からは、対象者が７名から２名増えて９名として事業を実施しているとのこと、こちらはバリアフリー化なども整備されているのか尋ねました。","respondent":"松山障害者支援課長","answer":"西大井つばさの家のバリアフリーに関してのご質問です。職員が手を添える、必要なところには手すりをつける等、配慮して対応してまいります。","id":"exchange-043"},{"speaker":"えのした委員","kind":"質問","question":"引き続き、ご対応をお願いいたします。以前、会派としても質問している小山七丁目障害者グループホーム整備について、進捗状況をお知らせください。","respondent":"川崎障害者施策推進課長","answer":"令和４年度、障害者グループホームの整備に当たりまして、各町会へのご説明に加えまして、住民説明会もこれまで４回行いました。今後は、運営事業者による住民説明会を開催予定で、令和７年度中に開設を予定しております。","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"続けて、福祉人材確保定着事業についてお伺いします。生徒募集活動等に専任職員１名を配置する人件費を助成したとありますが、また、具体的にどのような成果があったのかお知らせください。","respondent":"菅野高齢者福祉課長","answer":"今年度は２３人で、昨年度が１５人、その前が２４人ということになっております。入学者の減少が課題となっており、学校のＰＲの強化等のために、専任の営業職配置を支援しているところです。","id":"exchange-045"},{"speaker":"えのした委員","kind":"確認","question":"私も主要施策の成果報告書を確認しましたが、高校の訪問数２５６件、これは２５６校ということなのでしょうか。令和３年度は１５人と、１名の職員を増員するだけで、区のお考えをお知らせください。","respondent":"菅野高齢者福祉課長","answer":"やはり全体の７割程度が、２割程度の学校が、例えば就学資金貸付制度等のメリットを知らなかったというようなお話もあります。地道ではありますが、そういった高校訪問は大きく実を結んでいると思いますので、さらに営業職の強化をしていきたいと思っているところです。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問","question":"やはり認知度が低いということで、これからも周知、広報、こちらの拡充をお願いしたいと思います。卒業後３年間、そこの学費が免除されるということで、こちらは少し詳しくお知らせいただけますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そのうち全授業料に当たる１４０万円を借り受けできる制度となっております。卒業後、区の指定する施設で３年以上、介護業務に従事すると、返済が免除される仕組みとなっております。","id":"exchange-047"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。介護職員初任者研修等の受講に要した費用を助成しておりますが、こちらの実績、受講者数などをお知らせください。","respondent":"菅野高齢者福祉課長","answer":"続きまして、介護福祉士実務者研修等の資格助成についてお答えします。令和２年度３３人、令和３年度５２人、令和４年度９６人と着実に実績を上げているところです。","id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"２０２５年度に２２万人、２０４０年度には約６９万人が不足すると試算しており、介護業界は慢性的に人手不足と言われています。こちらについても国の人数にはなりますが、区の今後の取組がありましたら、お聞かせ願えますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"慢性的な介護人材の不足というところで、委員のおっしゃるとおり、国からそういった不足の人数が推計として示されているところです。今後、区としては、少しでも介護サービスの安定に向けて支援を実施していきたいと思います。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"福祉計画課の高齢者安否確認事業、高齢者福祉課の高齢者安否確認事業、高齢者福祉施設運営費についてお伺いいたします。近年の設置件数と、こちらの要望を受けまして緊急出動の件数についてお伺いいたします。","respondent":"東野福祉計画課長","answer":"一方、救急代理通報システムですが、平成１２年度から開始しております。こちらが平成１２年度開始以降、現在まで続いております。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"そうしますと、品川区がせっかくいいことをやっているのに活用されていない、知られないのはもったいないというご意見をいただきました。品川区外のご家族の方の目に触れたり、お知らせする方法があってもいいのではないかと思いますが、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"今、委員からお話がありました周知につきましては、様々な媒体を使って考えていきたいと考えています。在宅介護支援センターですとか、その周知方法につきましても、拡大に向けて検討してまいりたいと思います。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"次に、高齢者福祉課のほうの高齢者安否確認事業で、自動消火装置の設置と外出同行支援についてお聞きいたします。令和３年度は１件ずつで、令和４年度は０件だったようですが、今年度も申請はないのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"近年、全ての住宅に住宅用火災警報器の設置が義務づけられており、この事業の在り方について考えなくてはいけないかなと認識しているところです。実績としましては、令和４年度は２０６件、令和３年度は２０７件ということで…","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今年度も０件ということでしたが、廃止する前に一度対象を広げて状況を確認するか、廃止の前によく検討してから決めていただけたらいいなと思います。次に、認知症高齢者支援事業についてお伺いいたします。","respondent":"川原高齢者地域支援課長","answer":"こちらのミーティングセンターは、全国に先駆けて令和４年に都内で初めて実施いたしました。現在も引き続き積極的に活動していただいています。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"意見","question":"始まったばかりで試行錯誤などいろいろあるとは思いますが、八潮地区などもありますので、ぜひ高齢者のもどかしい思い……。〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問","question":"ほかの委員からもご質問がありましたが、私からは、２４９ページの高齢者向けパソコン・スマホ教室について伺います。品川区で令和４年８月から開始している６０歳以上でスマホを持っていない、それから、おのおの開催回数と参加人数の実績をお教えください。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました「はじめてのスマホ体験教室・スマホよろず相談」、昨年の８月より事業を開始したものにつきまして、ご説明します。参加人数２０３名、実施回数１４４回、延べ人数で７８６名の方にご参加いただいております。","id":"exchange-055"},{"speaker":"山本委員","kind":"質問","question":"８か月ということは、年間にすると、スマホ教室は約３００名参加しており、よろず相談は、年間約１,２００名が利用しているということですね。スマホ教室とよろず相談、それぞれアンケートなどで利用者満足度や理解度は把握されておりますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"こちらは、１コース、月４回実施しているような形ですが、毎回受講者のアンケートを紙でいただいているような状況です。参加率も非常に高く、８５％から９０％台を推移しております。","id":"exchange-056"},{"speaker":"山本委員","kind":"質問","question":"とてもよいことだと思います。スマホ教室とよろず相談ですが、利用者の方の相関関係はありますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"こちらは教室と相談のつながりがございまして、同じ会場で午前中に教室を実施し、午後に相談を実施しています。３０分ごとの枠になっていますので、空いている枠に関しては、午後の相談に参加してくださるという形で相関関係があります。","id":"exchange-057"},{"speaker":"山本委員","kind":"質問","question":"この９,０００人が初めの一歩を踏み出すためのスマホ教室を受講するには、今の年間３００人のペースだと３０年かかります。スマホ教室の年間開催数を増やすことは具体的に計画されていらっしゃいますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"１人の方に寄り添った丁寧な対応を、今、事業者のほうで行っていただいているところです。そして、教室は、令和４年度は３か所で実施をしていたのですが、引き続き増やしていきたいと思います。","id":"exchange-058"},{"speaker":"山本委員","kind":"提案","question":"私自身、品川区議会議員として、最重要課題の１つとして取り組んでいきたい課題であります。提案、要望をさせていただきまして、私の質問を終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"時間があれば、４９５ページの運動系介護予防事業もお願いします。来年、２０２４年に介護報酬の改定がありますが、品川区として、総合事業について、何か報酬の見直し等を行うご予定はありますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"私からは、介護報酬の改定に伴っての総合事業についてお答えします。その旨につきましては、介護報酬の結果を見ながら、区としても検討していきたいと考えているところです。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"国はきちんとした対策をとってくれていません。そういった状況で、さらに疲弊してしまうと思いますので、そういったことはしっかりと考慮に入れていただけるということでよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そこが上がると介護保険料も上がってしまうという、そういった悩ましいところもありますので、その辺りのバランスを考えながら検討していきたいと思います。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ですので、その辺はしっかりと考慮してお考えいただきたいというふうに思います。区の指定する施設で３年間働けば免除になりますというお話がありましたけれども、区の指定する施設というのは、どういった条件か尋ねました。","respondent":"菅野高齢者福祉課長","answer":"１点目の総合事業の単価についての介護事業者の厳しい状況ということは、ご意見として承らせていただきます。２点目の介護福祉専門学校の就学資金の指定の場所につきましては、実習生の受入れとか、指定ということで就職をしていただいているところです。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"恐らく認識が６月議会よりも大分、今後とも支援が必要ということは、ぜひその支援をもっと拡充させていただきたいと思うのです。介護報酬を増やすということが介護事業者の支援にもつながりますし、そういった両面での支援を、ぜひ私は要望したい。","respondent":"菅野高齢者福祉課長","answer":"介護サービスが安定的に提供できることが責務だと考えていますので、区としてはアンテナを張りながら、事業者と連携をとりながら支援等をしていきたいと思っているところです。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そして、本当にスキルを持って仕事をしている、そういった方も多いことを認識してほしい。以上、要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"つる委員","kind":"質問","question":"２５５ページ、２５７ページ、すまいるスクール運営費について伺っていきたいと思います。この３か年は、前後３か年で相談支援の充実を図っていくとなっているわけですが、その認識で合っているのかどうかということを説明を求めました。","respondent":"東野福祉計画課長","answer":"重層的支援体制の整備ということでありますと、そういったものの構築をもう少しバランスよく地域に広げていく必要性があると考えています。それから民間でやっている事業、ＮＰＯ等が行っているもの…","id":"exchange-065"},{"speaker":"つる委員","kind":"質問・要望","question":"どうとっていくのかというところでは、本庁であれば、そこで連携をしていくというような進め方も考えているということも確認をしたときもありました。これは先の一般質問でも確認させていただいて、そこに位置づけをしていくということで、ご答弁ではいただいているところであります。","respondent":"東野福祉計画課長","answer":"重層的支援体制整備を進める中におきまして、例えば在宅介護支援センターですとか、検討しているということでご理解いただければと思います。地域協議会の設置につきましては、区におきましては、この協議会の設置に向けまして取り組んでいきたいと考えております。","id":"exchange-066"},{"speaker":"つる委員","kind":"提案","question":"なかなか短時間では、それぞれ確認したりするのは非常に難しいとは思っています。自民党のせりざわ委員が既にもう提案をされていて、２年たって、今回は一定程度のご答弁をこれまでは福祉部門からいただいてきたのですとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"どういったことができるかというところを検討していますけれども、今、今年度中に実施ができないかというところでお話を進めているところです。その際には、どういった運用にするかというところがありますので、そちらをクリアしつつ調整していきたいと考えているところです。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"これが先ほど前段で確認させていただいた重層、広くその取組が広がるようなことも含めて、引き続きの検討をお願いしたいと思います。こういうふうな軸足でありますので、そこも含めた今の状況と、今後の検討状況を説明を求めました。","respondent":"藤村子ども育成課長","answer":"続きまして、仕出し弁当ですけれども、第一日野小学校で８月に１０日間試行実施したところでアンケート等をとらせていただきました。一定、学校の拡大ですとか、そういった形で選択肢を保護者の方に増やすというところで進めたいと考えております。","id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、２９１ページ、システム構築、保守経費についてお伺いします。","respondent":"石井保育支援課長、菅野高齢者福祉課長","answer":"そういうふうなところのライフスタイルの変化があったりとか、あと、職場での人間関係もすごく多いところです。そういったところで悩みを持っていらっしゃる保育士もいらっしゃいますし… 全国１４.９３％に対し、区内法人は１０.７％となっており、全国平均を今のところ下回っている状況です。今も保育支援課長が申し上げましたが、あとは…","id":"exchange-069"},{"speaker":"石田（し）委員","kind":"意見","question":"これは介護、保育だけではなくて、３０年間、日本の給料は世界から見ても上がっていない。それぞれの保育士、介護士の改善について、意気込みと思いをお聞かせほしいと求めました。","respondent":"石井保育支援課長、菅野高齢者福祉課長","answer":"民間事業者はそれぞれ様々やっていますし、例えば、今ちょうど国のほうでも子ども・子育て支援制度に関しての公定価格の見える化の検討をしています。内閣府でも、そういった経営実態調査の結果が出てまいりますので… 常勤で約３２万円、年収約４００万円弱となっておりまして、民間の平均給与である約４３０万円に対して低い金額となっております。は、研修会等を実施したりとか…","id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"補助があまりよくないのではないかみたいな話も出ていたけれども、では、どうするのですかと。なぜこのようにシステムを改修しないとできない給付なのか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"令和３年度以降開始されました臨時給付金について、それらに対応するために、なかなか素早く対応できないものにつきまして。マイナンバー制度につきましては、今後どのように使えるかということは、各所管と協議していく必要があるかと考えております。","id":"exchange-071"},{"speaker":"西村委員","kind":"質問・要望","question":"２５７ページ、４９７ページ、栄養改善事業について伺ってまいります。併せて、現状の取組を説明を求めました。","respondent":"長谷川児童相談所開設準備課長","answer":"例えば、被害確認の面接を実施できる環境が整っており、ここでモニター室を活用しながら子どもの様子を確認することで二次被害を防いでまいります。ソフト面としましては、通常の入り口とは別の職員通用口から入ってもらう運用ですとか…","id":"exchange-072"},{"speaker":"西村委員","kind":"質問","question":"様々に想定して準備していただいていることがよく分かるのですが、今おっしゃった二次被害というのは、どのようなことが考えられるのか説明を求めました。","respondent":"長谷川児童相談所開設準備課長","answer":"二次被害は、先ほどご説明させていただきました被害確認面接というもので、児童虐待事案に係る子どもの心理的負担等に配慮した面接の手法です。警察や検察と児童相談所が連携し、一度きりの面接で終了することを基本に実施いたします。","id":"exchange-073"},{"speaker":"西村委員","kind":"意見","question":"私のこれまでの知識や経験を超えるぐらい、十分に配慮していただいていることがよく分かります。こういった活用を想定して蓄電池や太陽光を設置していただいていると思うのですが、改めてどのような場合を想定されているか説明を求めました。","respondent":"小林施設整備課長","answer":"太陽光につきましては、再生可能エネルギーをつくり出す環境面と併せまして、停電時に電源の確保による事業継続を期待しているものです。事業継続という観点でいきますと、発電機も設置をしているところでございまして、必要最低限の生活ができるように設置しています。","id":"exchange-074"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、一般質問でも質問させていただいたのですが、子どもの意見聴取等の仕組みの整備が厚生労働省より求められております。区では、事業として制度を位置づけて準備していただいていると思いますけれども、このアドボケイトの準備状況について伺わせてください。","respondent":"長谷川児童相談所開設準備課長","answer":"子どもとの信頼関係を丁寧に構築する必要があることから、週１回程度は児童相談所に訪問してもらうことを想定し、現在、検討を進めております。この支援員をアドボケイターと呼びますが、子どもの意見を考慮した支援の実現を目指して、検討を進めているところです。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"念入りに準備してくださっていることが課長のお話を伺っていると本当によく伝わってくるのですけれども、以前、私も忘れられずにおります。区のお考え、また、今後の取組を説明を求めました。","respondent":"長谷川児童相談所開設準備課長","answer":"現在、ペアレント・トレーニングをはじめとするあらゆる心理手法を用いまして、子どもに寄り添った対応をしていきたいと考えております。多くの研修に参加し、技術を身につけると同時に、所内での実践を通して組織的な導入を実現してまいりたいと考えております。","id":"exchange-076"},{"speaker":"西村委員","kind":"質問・要望","question":"委員からも様々質問がありますけれども、私もニーズの高まりを大変実感しておりまして、こちらについて伺ってまいりたいと思います。どのように受講者の方に伝えているのか、改めて説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"３回目、４回目のコースで、参考ということで載せしています。それと同時に、アプリやスマホを使うと、こういった詐欺に遭う可能性があるというところを周知徹底をさせていただいているところです。","id":"exchange-077"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区の高齢者介護予防の一環として、様々新しい取組もトライしていただきたいと考えています。このゲームのような新しいコンテンツの拡充ですとか、そういった取組について、何か検討されていることがあれば、説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"昨年度、令和５年３月に、１回限りの試行的体験事業ということで、はじめてのゲームアプリ体験を実施したところです。そして人との交流もできるものを、来年度、研究をしてまいりたいというふうに考えてあります。","id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"最後に、介護予防のための通いの場について伺ってまいりたいと思います。改めて今年度の実績と取組、また、課題についても併せて伺えればと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらは、区内法人に勤務するリハビリテーション専門職、住民主体による通いの場によるモデル実施を図っているものです。こちらとは別に、団体登録をしなくても、出張する講座を別途行っておりまして、こちらも令和４年度から引き続き大変好評をいただいているところです。","id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"５人以上集まれば講師が出向いてくださると、なんだかんだ忙しいのよ」と高齢者の方々が言ってくださることがすごくうれしいので、この通いの場をぜひ町会の皆さんなどにも広げていけるように周知をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"２４５ページ、福祉人材確保・定着事業に関してお伺いしたいと思います。特別養護老人ホームの視点からお伺いしたいのですけれども、５日間はとるものの、そこには派遣の方の応援もいただいている。","respondent":"菅野高齢者福祉課長","answer":"それが派遣料が高いから、結果、経営を圧迫させてしまうとか、そういったお話も聞いております。７５歳以上の後期高齢者が増える中、介護事業者と連携をとりながら、サービスの提供に滞りがないように努めていきたいと思っているところです。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"世田谷区が１３万幾らとかということも踏まえて、そういうこともやっていただきたいですし、ケアマネジャーとしてのステップもあるのだと思います。将来のことも安心感を持っていただけるので、そういったキャリアアップの観点からの取組をお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"選んだ講座によっては、８万円よりも安い講座もあったりしますので、一概には８万円はそんなに安くはないのかなと思っているところです。さらに、ケアマネージャーとか、キャリアアップについての助成についても検討していかなければいけないと感じているところです。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからどう進めていくのか、この会議は、今後どのようなスパンで開かれるのかを伺いたいと思います。それと同様に、ホームページへの掲載もしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"なお、品川区の当課で行っております在宅レスパイト事業および障害児支援の利用者のうち医療的ケアを要する人数ということになっております。１８歳以上については、把握はしてございません。 これまでコロナの影響があったため、開催の見送りであるとか、書面開催となっておりまして、令和４年度に対面での実施をさせていただきました。年内に１回目は開催予定で進めております。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に改善が求められるところですので、今回の１回だけでなく、ぜひ充実をさせてほしいと求めました。４つの電源がとれないということで伺ったのですけれども、蓄電池２個を対象にできないかと思っているのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"日常生活用具検討会の中で、当事者の団体もいらっしゃいますので、ご意見を伺いながら検討していくということになります。それは今後も品川区内の医療ショートを、ほかのところも含めて… 呼吸器をつけた方の受入対応の件ですが、そして医療的ケアが必要な方も地域で安心して暮らせる支援体制の整備が必要ということは認識しております。今後は、区内の医療的ケアの方の状況、現状を踏まえまして考えてまいります。","id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"出石と小山七丁目のグループホームが、障害支援区分６の方まで受け入れるということで考えられているのか、その点についても伺いたいと思います。なぜ品川区は高校卒業までとしているのか、利用できるように対象年齢の拡大をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"今後、委員もおっしゃった出石つばさの家が令和６年４月１日開設予定、そして令和７年度中に小山七丁目障害者グループホームを開設予定です。ですので、現在のところ、小山七丁目のグループホーム… そのため、日中一時支援、いわゆるお預かりで対応せざるを得ないというような状況があります。それに比べて品川区としましては、各施設の生活介護の延長で対応していただいているので、それはありがたいことだと感謝しております。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区立はこれからなかなかつくらないという方向でこの間伺ったので、すごく求められておりますので、つくる方向でご検討ほしいと求めました。令和４年度は１８億円を超えましたので、なぜこういう形で、令和５年の見通しはどのような状況なのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そして、見込みを上回るなどの場合には、介護保険の財政の均衡を保つことになっております。現在の基金は１８億円になっておりますが、今年度、バランス等を考えながら取崩しについては検討していかなくてはいけないと感じているところです。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが１８億円まで増えているということなので、その理由がどうなのかというふうなことで伺ったのですけれども、今の説明ではよく分からない。いよいよ９期がまた始まりますので、保険料の引下げにぜひとも活用していただきたいということで、意見として申し上げて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"こんの委員","kind":"質問","question":"２４７ページの高齢者社会参加支援と、高齢者外出習慣化事業、もう１つが、２２７ページ、地域福祉推進費からお伺いしたいと思います。そこで、まず高齢者の孤食について、区の見解を説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"１つとしても、クッキングの教室など、２つを実施しています。今年度、事業も４月から９月までは持ち帰り軽食なのですけれども、参加いただいた皆様のお声を聞きながら考えていきたいというふうに思っております。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"シニア食堂というものはできないでしょうかというお声がありました。シニア食堂についてのご見解と、お分かりになれば、少し概要などをお知らせいただけますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"残念ながらこういった形のシルバー食堂という銘を打って実施はしていないのですが、現在、今年度どんどん増えております。来年度も引き続き実施するのかですとか、引き続き調査をしてまいりたいというふうに、情報収集も含めて行ってまいります。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"いろいろな食材をみんなで作るというところも１つのポイントで、作り方が分かると、その辺のところも併せてできたらといったところです。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"確認","question":"脱会をされて、「なぜですか」と言ったら、「あんなの、入っていても何の役にも立たない。これは１つ安否確認になるのだろうなと思っているので、１つは、行政側の普及啓発活動を見守りと一緒のように高齢者クラブの方々に配布してもらう。","respondent":"川原高齢者地域支援課長","answer":"１つひとつ滅びることがないように支援をしていきたいと、より活性化していくように、会員の増強に取り組んでまいりたいと思います。全老連による実態調査が実施される予定となっているということを伺っておりまして、その調査結果を分析・検討されて、また提言が図られるです。","id":"exchange-091"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"福祉政策で１つ教えていただきたいのは、福祉は結構やらないと、組織強化をしないと駄目だと思っている。ごめんなさい、そこら辺のところが何となくあるような気がしてならなくて、そこら辺のところが分かれば教えてほしい。","respondent":"菅野高齢者福祉課長","answer":"再任用職員だけで回しているような事業があるかというと、見当たらないので、その辺りのところは正規職員が少し事業整理をしながら効率的に事業の運営を図っていると認識しているところです。","id":"exchange-092"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は正規職員の方がいて、それはしっかりそういう政策をどういうふうにしていくのだ、そこはそういう形でやっていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"木村委員","kind":"確認","question":"座ったまま、また今日もよろしくお願いします。２３１ページの障害者まつりについてお伺いいたしますけれども、確認ですが、これと一緒だということでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃるとおり、９月１６日に中小企業センターで行われたおまつりが「ふくしまつり」、障害者まつりと同じものです。","id":"exchange-094"},{"speaker":"木村委員","kind":"質問","question":"これはなぜ名前が違うのでしょうか。私が理解できないので、それが分かれば説明を求めました。","respondent":"松山障害者支援課長","answer":"「障害者まつり」と「レクリエーション」というものが２つあるのですけれども、それをひっくるめて「ふくしまつり」ということで、ふくしまつりについては、実行委員会形式で行っておりますので、通称として「ふくしまつり」というふうに呼ばせていただいております。","id":"exchange-095"},{"speaker":"木村委員","kind":"質問・要望","question":"つまり、障害者まつり当日は、多くの方々が参加をして、そして大盛況であったということを聞いております。どれぐらいの参加者があったのかお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"参加人数についてです。延べで１,８７０人の方にご来場いただきました。","id":"exchange-096"},{"speaker":"木村委員","kind":"意見","question":"１,８００人余の多くの方々に気にかけていただいているということだけでも大変うれしいことであります。多くの方々が参加されていましたけれども、けがやトラブル等はなかったのかどうか、それも説明を求めました。","respondent":"松山障害者支援課長","answer":"当日の安全についてのお尋ねです。ふくしまつりも４年ぶりの現地開催ということで、４年ぶりなので、笑顔であふれておりました。","id":"exchange-097"},{"speaker":"木村委員","kind":"質問","question":"これは当日何もなかったということで最高ですから、これからもまた安全に行うことを願っています。実行委員会形式で行っていると思いますが、どのような団体が、何団体ぐらいが参加された実行委員会をつくっているのか尋ねました。","respondent":"松山障害者支援課長","answer":"３２団体の方が参加されました。本当に毎回話合いを重ねて一緒にふくしまつりをつくり上げたものです。","id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"私も今、松葉杖をついて歩いている状況でありますから、このような気持ちも分かりますし、皆さんと共にまた頑張っていきたいと思っています。大変なご苦労であったと思いますけれども、実行委員として参加された団体の声が何かあれば、お聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"やはり４年ぶりの現地開催ということで、皆さん、補ってやっていこうよというような状況でした。すごく期待も大きくて、本当にやってよかったと、当日は本当に笑顔にあふれていて、皆さん、満足げにお帰りになられていました。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"障害を持った団体、方々、やはり多くの方々と力を合わせながらやっていくことが一番だと思いますから、ぜひ行政として音頭をとっていただいて、みんなが元気に無事に過ごせることをぜひ願っておりますが、その点を最後に力強くお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"ふくしまつり」も実は２８回目を迎えておりまして、ああだこうだ言いながらつくり上げているものです。ふれあう場として非常に大事なふくしまつりだと考えていますので、これからも職員一同、力を合わせて支援してまいります。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"何の差別もないわけでありますから、そういう点についても十二分に注意をしていただいて、これからも頑張ってほしいと求めました。作品展に出展される作品の数、出展者の数なども教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"出展された数としては、１１３作品です。最近は、結構、各団体や特別支援学校で合同で皆さんで作るような大きな作品ですとか、力を合わせたようなものが多くなってあります。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"それぞれの講座を受けた方々の人数を教えてください。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"２７３ページのぷりすくーる西五反田についてお聞きします。その課題をどう解決して認定こども園にしていくのか、そのスケジュールを説明を求めました。","respondent":"立木保育課長","answer":"解決しなくてはいけない課題は、やはり園庭の問題でございまして、今現在の施設ですと、約９０m2ほど不足をしております。検討を進めている最中でして、今後の予定のところはお示しできないのですけれども、今後検討を進めていくという。","id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"隣には西五反田保育園がありますので、今後どういうふうにしていくのかというのは、総合的に考えてほしいと求めました。子どもの利益とは何ですか、親子の関係で大切なのは何ですか、いかがか尋ねました。","respondent":"立木保育課長","answer":"そうしたときに、やはり親御さんがそばにいていただくというのは、これはもう間違いないことだと思います。そういうような考え方の中で、今、制度を整備しているというようなことです。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"これをやります、子どもの利益とは何でしょうかということが一番大切なことだと思いますので、それを念頭に置いて行ってほしいと求めました。課題は何か尋ねました。","respondent":"藤村子ども育成課長","answer":"今回のすまいるスクール仕出し弁当試行ということで８月にやらせていただいたというところですが、ごみの持ち帰りですとか、そういった運営面での問題があったかというふうに考えております。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"そして、改めて、すまいるスクールの役割とは何でしょうか。それはどういう理由なのか、そして、すまいるスクールの役割は何か尋ねました。","respondent":"藤村子ども育成課長","answer":"遊び、スポーツなど、様々な体験ができる場所として運用するというのがすまいるスクールの役割と考えています。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"そういう仕組みになっているのですが、品川区はなぜ今の形態にしたのでしょうか。目的は何か尋ねました。","respondent":"藤村子ども育成課長","answer":"保護者の方々が自由にお預けして、子どもの育成というところで、こういった観点が一番というところで、この今のすまいるスクールの形になったかと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、夜も７時まで預けられるようになってきたという経緯はあります。ＰＴＡはあるけれども、それよりももっとすまいるスクールというのは、これからのすまいるスクールの在り方についてお答えください。","respondent":"藤村子ども育成課長","answer":"これからのすまいるスクールの在り方としては、保護者の方の教育というところももちろんですけれども、子どもにとって通いやすいですとか、楽しんでいただけるというようなすまいるスクールを目指してやっていきたいと思います。","id":"exchange-108"},{"speaker":"まつざわ委員","kind":"質問","question":"これによって１人の館長が委託館を多く抱えているということはお聞きしております。どうしてこのような状況になったのか、大変に心配しているところでありますが、ご説明をお願いいたします。","respondent":"藤村子ども育成課長","answer":"令和４年度に児童センターの在り方検討ということで、児童センターのニーズですとか、そういった総合的な調査を行ったところです。地域、学校、保育園などとしっかり連携をとっているような状況になってあります。","id":"exchange-109"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"個人的に、この児童指導職は増やしていくべきと思いますので、継続して頑張っていただきたいと思っています。この２つの事業の最近の利用率、そして利用数をお示しください。","respondent":"藤村子ども育成課長、立木保育課長","answer":"２人１組で訪問しておりまして、その後に１回訪問して、もう一度訪問するというような形で２回訪問しているようなところです。実際、児童センターでやっている事業に参加されるというような形をとったりするので… ５月以降、８園ありまして、それから保育体験等で合計２６名の方にご利用いただいております。","id":"exchange-110"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そうすると、これは児童センターの区割りではなくて、どういった割合でこの事象が起こっているのか教えていただきたいのが１点。児童センターの負担もあるかもしれないですけれども、そういった事業の整理が必要かと思いますが、ご見解を説明を求めました。","respondent":"藤村子ども育成課長","answer":"投函は地域センターの１３地区で区分して、児童センターがそれぞれ対応する館長館でやっているので、というところです。コロナも明けているので、拡大したいというふうに考えているところなのですが、こちらについては学校と調整をしてまいりたいと考えています。","id":"exchange-111"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"新規事業にそういう結びつけというのは、私は効果があると思うので、そういった意味でいろいろ取り組んでいただきたいと思っています。どのような事業で、どういう状況なのか、ご説明をお願いいたします。","respondent":"藤村子ども育成課長","answer":"こちらについては、２種類、父親の関係の事業がございまして、児童センター全館で実施している父親の子育て応援事業というものがまず１つです。多胎児についてお話しいただいたのですが、多胎児を対象にした事業の実施はないのですけれども、そういったカテゴリというか。","id":"exchange-112"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要望を聞けば、もっともっと拡充したいという、これは要望で終わります。もの忘れ検診もガイドブックがすばらしくなったので、どういう経緯であのすばらしいガイドブックができたのか、お伺いします。","respondent":"川原高齢者地域支援課長","answer":"オレンジフェスタの取組、ご参加、ご見学いただきましてありがとうございました。令和４年度新規事業として開始しましたので、そちらの検討も踏まえまして、さらに充実を図ったところです。","id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"続けまして、これは今年度から始まった事業の確認をさせてほしいと求めました。申請数、それから助成決定数、ここら辺を確認しておきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"そういったご意見を踏まえながら場所は検討してまいりたいと思いますが、昨年度の形になるのですが、さらに研究を進めてまいりたいと思います。耳の聞こえ相談会ですとか講演会を実施して、そのかいもございまして…","id":"exchange-114"},{"speaker":"若林委員","kind":"質問・要望","question":"ゆうゆうプラザも４か所のうち３か所、しっかり所管の中で、まずどこまで広げられるかチャレンジをしていただきたいというふうに思います。そういったベーシックな支援とすることが、私は望ましいというふうに思っておりますので、この点についてもご答弁をお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"その辺りは、財政部門とも相談をしながら速やかに実施に向けて取り組んでまいりたいというふうに考えてあります。自立支援の向上、やはり考えていただかなければいけないところですので、他区や都の助成内容の動向も見ながら研究を進めてまいりたいと思います。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"それぞれ大変前向きなご答弁をいただいたと思います。一般質問、品川区のシステムで補聴器が生活の質の向上等に資するかどうか、事業の拡充をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和２年４月開園ですが、不備があれば、その段階で修正していたことがあったのでしょうか。お伺いします。","respondent":"石井保育支援課長","answer":"しなおおコスモ保育園に対する補助金受給の件です。補助金の申請があった後、幾つか打ち返しをしながら経費の精査をした上で補助金の交付決定をしています。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"確認","question":"品川区は入っていなかったのですが、その報告書を取り寄せて、再確認を実施していれば、その方法を今どういうふうにして行っているか。していなかったら、していなかったで結構ですが、お伺いします。","respondent":"石井保育支援課長","answer":"本件報道等を受けまして、一度、文教委員会で報告をさせていただいてあります。厨房機器のほうで１つ疑義が生じているということで、もし不正等がありましたら、返還請求等を行ってまいる所存です。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"確認","question":"では、確認しますと、最初に補助金等を交付したときにはオーケーだったと。チェックしていくということですが、東京都と一緒に行って監査をしなければいけないのだと思うのですけれども、その点はされていますか。","respondent":"石井保育支援課長","answer":"１点、こちらは区が都や国の財源を用いながらやっているものですので、区のほうでチェックをしていくというふうなところです。児童福祉法や子ども・子育て支援法に基づいた、例えば、そこについては切り分けて考えているところです。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"これらの施設に年に１回の監査を実施するとすれば、多大な時間と人員が必要と推測されます。来年度に向けて児童相談所を開設するわけですから、監査体制の充実をどのように考えていらっしゃるのか、具体的に体制整備の状況をお伺いします。","respondent":"立木保育課長","answer":"ですので、それに合わせた人員体制を、令和４年度から順次人員を増やした形で指導検査ができる体制を、今、構築している最中です。それに合わせて人員要求等も年次で行っているというような状況です。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど、令和４年度から増やしているということですが、令和５年度以降もそうやって整備、体制を強化していくところでしょうか。その点、お願いします。","respondent":"立木保育課長","answer":"区全体で考えなければいけないため一遍に増やすことがなかなか難しいので、毎年毎年体制を強化しながら、令和４年度、令和５年度、そして来年度という形で、今、増やしてきているところです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"文教委員会でも少し確認させていただいたのですが、児童相談所開設を先行している８区で、措置費共同経理課を区政会館内に設置するということです。この措置費共同経理課について簡単にご説明いただいて、品川区では来年度予算にどのように反映させ、どれくらいの予算規模になるのか尋ねました。","respondent":"長谷川児童相談所開設準備課長","answer":"まだ根拠となる設置条例がありませんので規約には載せておりませんが、児童相談所設置条例を提案した後に、改めて提案をする予定となっています。その措置費共同経理課に派遣する職員の経費、あるいは負担金…","id":"exchange-122"},{"speaker":"松本委員","kind":"確認","question":"私からは、２２７ページ、長寿お祝い事業、少し時間が間に合わないかもしれませんが、２５７ページのすまいるスクール運営費について伺います。長寿お祝い事業ですが、この事業の目的を改めて確認できればと考えています。","respondent":"東野福祉計画課長","answer":"直接本人または家族の方にお祝い金を手渡すことにより、所在確認、安否確認を行うという側面も持っているものです。社会福祉協議会も区と同様のお祝いをお渡しするということで、区と同じような形の事業を社会福祉協議会の事業として行っているものです。","id":"exchange-123"},{"speaker":"松本委員","kind":"確認","question":"さらにお伺いしていきたいのですけれども、かつては、傘寿の方にも配られていたというふうに議事録で確認いたしました。この平成３０年〔同日後刻に「令和元年」と発言訂正あり〕に廃止されたときの経緯と、あと、この辺りの経緯をお伺いできればと思います。","respondent":"東野福祉計画課長","answer":"男性の平均寿命が８０歳を超えてから５年以上経過したというところから、廃止に踏み切ったということになってあります。こちらにつきましては、丁寧に説明し、ご理解いただいたということでの記録があります。","id":"exchange-124"},{"speaker":"松本委員","kind":"確認","question":"１００歳、あと１０１歳以上の方に区内共通商品券を、約３,０００万円かけて実施しているというふうなことかと思います。少し確認なのですが、これ、１０１歳以上というのは、１０１歳以上の方に毎年配られているということでよろしいか尋ねました。","respondent":"東野福祉計画課長","answer":"１０１歳を超えている方につきましては、毎年配ってあります。","id":"exchange-125"},{"speaker":"松本委員","kind":"確認","question":"令和４年度の配布人数が３,５４１人で、前年度を確認すると、３００人ぐらい増えているかと思います。今後かなりの増え方をするのかなというふうに思うのですけれども、こちらは区としては今後の増え方をどのように考えていらっしゃいますか尋ねました。","respondent":"東野福祉計画課長","answer":"品川区におきましても、７５歳以上の後期高齢者の人口が増えてきておりますので、この後も増えてくるというような見込みをとっております。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"ただ一方で、特別区内を見ましても、１００歳の方にだけお配りしているというふうな自治体が３区ほどある。９０歳と１００歳では１年、１００歳以上の方たちについては毎年ということなので、ご意見を伺えればと思います。","respondent":"東野福祉計画課長","answer":"近隣区でいきますと、ほぼ全区が８８歳のお祝いをしている、今年の８月に調べた実績ではそうなってあります。お電話もいただいているところですので、高齢者の方に向けて、安否確認も含めた事業として続けていきたいと考えているところです。","id":"exchange-127"},{"speaker":"松本委員","kind":"確認","question":"なかなかこれは決断が難しいところだと思うのですが、少し観点を変えて、先ほど、安否確認というところのお話があったかと思います。一方で、簡易書留で送っているというふうな情報もあるかと思いますが、これは今、どういうふうに送られているのか尋ねました。","respondent":"東野福祉計画課長","answer":"実は、コロナ禍におきましては、直接お届けすることが非常に難しい状況ということを踏まえまして、郵送で簡易書留等を使ってお送りしています。今後もそれを続けていきたいと思っているところです。","id":"exchange-128"},{"speaker":"松本委員","kind":"質問・要望","question":"令和５年度からは民生委員の方が伺われているということで、安否確認に関しては、独居老人といわれる方もいらっしゃるかと思います。そこから安否確認をしていただきつつ、これは要望ですけれども、ぜひとも見直しをしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"},{"speaker":"藤原委員","kind":"質問","question":"福祉部についてお伺いしますが、あの人数でこれだけの事業をやられていて、本当に痛み入ります。それで、課長、メンタル面をどう支えているか説明を求めました。","respondent":"松山障害者支援課長、豊嶋生活福祉課長","answer":"私どもは、庁舎３階で、本当に入ってすぐ、区民の方が入ってすぐのところですので、区役所の顔だと考えています。職員一同、本当に区民の方に対して、安定した丁寧な対応に努めているところです。 各相談員が一人ひとり考えて、日々、職員は精進しています。システマティックにみんなで対応できるように日々動いておりますので、今後もさらに気を引き締めて動いてまいりたいというふうに考えております。","id":"exchange-130"},{"speaker":"藤原委員","kind":"確認","question":"４９７ページ、介護保険特別会計で、これ、しながわ出会いの湯事業が入っているのですけれども、これはなぜ介護保険特別会計なのですか。伺いますが、きちんとした施策ですから、それの確認。","respondent":"若生健康課長、東野福祉計画課長、川原高齢者地域支援課長","answer":"もともとは福祉部の高齢部門のほうでモデル実施というところから、高齢者が気軽に参加できるプログラムと入浴サービスとを合わせて実施して。… 重層的支援体制整備事業と一体的に進める必要性があるということで、隙間の課題について、応募をさせていただいたものです。… 窓口の職員の対応が非常によいであるとか、ご意見をいただきまして、大変ありがとうあります。ご質問いただいたように心に偽りはなく精いっぱい頑張ってお…","id":"exchange-131"},{"speaker":"藤原委員","kind":"質問・要望","question":"２４５ページ、福祉人材確保・定着事業についてお伺いします。私は、何回も要望しました。","respondent":"菅野高齢者福祉課長、若生健康課長","answer":"交付人数が約２００人で、年間２,０００万円規模の予算で、区独自の経費で実施しているというふうにも聞いております。品川区としてはもう少し様子を見ながら検討していきたいと思っているところです。 今後、浴場組合ですとか、委託しているシルバー人材センターともお話ししながら進めていきたいと考えております。","id":"exchange-132"},{"speaker":"藤原委員","kind":"質問・要望","question":"その委員が求めているのです、どうにかしましょうと。求めて申請する人には、品川区が先駆的なのですから、それはしていってほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"そういった中で、本当に介護事業者たちは常に心を込めて利用者に接して、その結果がメッセージに込められているのだと私も実感しております。国のほうも、介護報酬の見直し等で議論しているところですので、もう少しその動向を見ていきたいと思っているところです。","id":"exchange-133"},{"speaker":"のだて委員","kind":"質問・要望","question":"ですので、ぜひ手話通訳者を毎日配置してほしいと求めましたが、いかがでしょうか。そのときにも拡充を求めまして、区は、利用状況を見たいということでしたけれども、どういう状況になっているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"委員おっしゃるとおり、現在、半日、週３日、配置しております。利用状況につきましては、半日たっぷり埋まるところもあれば、お客様がいらっしゃらないときもあるという状況です。","id":"exchange-134"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者支援課に毎日配置をしてほしいということも伺いましたので、ご答弁ほしいと求めました。","respondent":"松山障害者支援課長","answer":"今現在、品川区内の通訳者ですと２８人の方が登録されております。障害者支援課に配置ができるかどうかにつきましては、また登録通訳者の方々とご相談、調整したいと考えています。","id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"協会の方からも、聞こえる人はいつでも相談に行けるのに、聴覚障害者はできない、聞こえる人と平等にしてほしいとの声も出ています。手話通訳者を毎日配置するということは、合理的配慮の提供の１つではないかと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"手話通訳者の配置についてです。２８人それぞれ派遣状況等もありますので、それらを踏まえて相談、調整し協議していきたいと考えています。","id":"exchange-136"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は手話通訳者の派遣をしていると思いますが、先ほど、登録者の方は２８名ということで、今、利用回数はどれだけになっているのか伺います。さらに合理的配慮の提供を進めるために、団体利用を無料にすることが有効だと考えますが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"それから、料金の関係です。あるいは、通訳者の会の方々とも実は意見交換をしながら、いつも適正な価格を決めているところです。","id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、合理的配慮の提供に向けて、さらに求められていくのだと思います。ですので、ぜひすそ野を広げて、手話通訳者の拡大を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"少なくとも４年、５年、２回の非常に難しい試験を合格されているです。今も努めているところです。","id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"昨年１２月に聴覚障害者協会と通訳者の代表者の方、そして障害者支援課で勉強会を実施したということですけれども、その後の進捗状況を伺います。区として、手話通訳者の処遇改善を検討してほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"通訳者を養成したいのに、半年か１年か、少し多くかかってしまうというような課題もありまして、非常に実務的なところで、今、検討を進めているです。そういった面で手話通訳者の方々の環境的な整備、健康管理などを支援していこうというものです。","id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"併せて検討してほしいと求めましたが、いかがでしょうか。実際、こちらもぜひ養成研修を拡充していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"同行援護の課題の経済的なところには使えないという課題解決に向けて、今、検討しています。ガイドヘルパーに向けても、増やすというか、継続をしながらきちんとヘルパーとして従事していただくことを考えております。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ品川区としてさらに進めていっていただいて、利用できないということがないようにしていただきたいというふうに思います。こうしたバリアを取り除いて、障害がある方も、誰もが安心して暮らせる品川区にすることを求めて終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-141"},{"speaker":"吉田委員","kind":"確認","question":"区立園は、区として全園にそういうものがあるというふうに確認していると理解してよろしいでしょうか。中には少し時間がたってからというところもあって、この辺もルールはあったほうがいいのではないかと思いますが、その点についても伺います。","respondent":"立木保育課長","answer":"誤食の部分と、そのほかを含めまして、職員間の連携の部分で少しミスがあったというようなところが原因です。まずは電話等で一報を入れた上で、再発防止等、全てきちんと整った報告書という形で区の保育課に上げてもらっているというような状況です。","id":"exchange-142"},{"speaker":"吉田委員","kind":"質問・要望","question":"０歳児、０歳児や１歳児とは違う意味で多くの目が必要になると思いますが、いかがでしょうか。ぜひそちらも確認させていただきたいのですけれども、ぜひそちらの方向で要求してほしいという意見を申しましたけれども、いかがか尋ねました。","respondent":"立木保育課長","answer":"通常であれば１人という形にはなるのですけれども、そこをきちんと職員を多めに付けて保育をさせてもらっているという中で対処をしております。少し一時的に確認とか連携のミスが出てしまったというところで、再度…","id":"exchange-143"},{"speaker":"吉田委員","kind":"質問・要望","question":"いかがでしょうか。一旦それでお答えをお願いします。","respondent":"立木保育課長","answer":"看護師等の確認をとった上で病院等に連れて行っておりまして、その場から離れるということはございませんので、ご安心ください。保育課も園も含めて一緒に考えておりますので、そうした中でしっかり子どもと向き合う時間を確保してまいりたいと思います。","id":"exchange-144"},{"speaker":"吉田委員","kind":"質問","question":"１回事故を起こしたから、すごくどうこうと言うつもりはないのですけれども、事故報告も対象となるべきなのではないかと思います。こういう事故報告の扱いは、モニタリングの際にどうなっているのか伺いたいと思いますが、いかがか尋ねました。","respondent":"立木保育課長","answer":"しかし、こちらは、園運営の中で保育課とも連携をとった中でしっかり対処はしています。公私立連携協議会もやっておりますので、そうした中でこうした事例は共有させてもらって、再発防止に努めているところです。","id":"exchange-145"},{"speaker":"吉田委員","kind":"確認","question":"それから、指定管理者が行った定期点検報告は、所管で報告を受けていると考えてよいでしょうか。そこに定期点検の妥当性を判断できる人が配置されているのか、その辺を確認させてください。","respondent":"松山障害者支援課長","answer":"利用者の安全性に関わるようなものについては、早急に対応させていただいているところです。各所管には、そこまでの専門家はおりませんので、施設整備課に相談しています。","id":"exchange-146"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。では、最終的には施設整備課のほうで、その専門性を持った点検がされるという理解でよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"点検自体につきましては、所管で行う場合もありますし、我々のほうで行う場合もありますけれども、当然、所管のほうで行った内容につきましても、ご相談を受けた内容を見て、これがやるべきなのか、やらざるべきなのか、そういうところは判断しています。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり区の施設ですので、最終的には、やはり施設整備課が責任を持って、所管から上がってきた報告書は点検してほしいと求めました。当然と思いますけれども、改めてお願いをして質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-148"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、２７５ページ、保育関係事務費について伺ってまいります。先日、双子のお子様がいらっしゃるご家庭から、なぜ品川区には多胎児であることの加点がないのでしょうかというお問合せをいただきました。","respondent":"立木保育課長","answer":"今のところ設けておりませんで、兄弟で入園する場合には、１点の加点という形になってあります。他区の情勢等を見ながら、毎年見直しはかけておりますので、そうした中で検討しますというようなお答えをさせていただいているところです。","id":"exchange-149"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私が直接お伺いしたようなご要望が区にも届いている。寝る間もなく、ファミリーサポートセンターに一時的に預けたらどうですかと利用を勧められたそうですが、結果的に利用しなかったそうです。","respondent":"立木保育課長","answer":"今の事例に関しまして、あったかないかというところも含めて、今、手元に資料がないので、はっきりとお答えすることができません。申し訳ございません。","id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜなら、それは多胎児を条件とする項目がないですから、把握しようと思ってもなかなかできない。早急に、早急に母親が多胎妊娠中あるいは入園する子どもが多胎児であることに加点を行ってほしいと求めましたが、ご見解を伺います。","respondent":"立木保育課長","answer":"多胎児家庭の実情につきましては、今、お話もいただきまして、十分理解はさせていただきました。例えば年子のご家庭はどうなのか、そういったことも総合的に勘案しまして、いろいろな面から検討させていただきたいと思います。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１点、既に保育課にはお伝えしていますけれども、大事な要望です。ですから、これ、やはり子育ての品川としては、検索できるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"立木保育課長","answer":"これは、お声をいただきまして、今、作業に入っているところでして、早急に直したいと思います。","id":"exchange-152"},{"speaker":"せりざわ委員","kind":"質問","question":"２４７ページの認知症検診から、見守りアイテムだったり、補聴器も含めてお伺いします。時間があれば、２４９ページの高齢者多世代交流支援施設運営費についてお伺いしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"現在は、そちらを踏まえまして、医師会との検討委員会を踏まえて、医師会のご協力もいただきまして、認知症検診の期間をまず延ばしていただきました。３０医療機関に引き続き受診率を上げる取組を、あとは区の努力というところで…","id":"exchange-153"},{"speaker":"せりざわ委員","kind":"提案","question":"本会議で幾つか提案をさせていただいていまして、早期診断、早期治療。例えば区で言い訳をつくってあげるということも１つ方法かなと思って、２人分で３,０００円ぐらいで、ぜひご見解をお聞かせほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"医師１人が診られる時間がやはりかかってしまうというところで、集団検診という捉え方も考えの１つとして必要であるのではないかと研究をしています。若い層、６５歳以上の方をキャッチするような手法を考えていきたいというところと…","id":"exchange-154"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"１３ブロック、その１３ブロックにそれぞれ希望大使がいて、そこら辺もぜひご見解をお聞かせほしいと求めました。今、スマホ教室という話もいろいろあったと思いますけれども、そちらについてもご見解を説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"実は作成している「品川“くるみ”認知症ガイド」という冊子に、本人大使の方のイラストを入れるような形で、今、検討しています。そして３点目、スマホ教室のところでは、児童センターとの連携も含めて実施をしてまいりたいと考えています。","id":"exchange-155"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":126021,"voices":353}}]);
